  ui_story_5046_50460201_64_dialog_content = "Termos? Como trocar uma coisa por outra?",
  ui_story_5046_50460201_65_dialog_content = "Eu acho PlayerName é precioso para você. Você é PlayerName?",
  ui_story_5046_50460201_66_dialog_content = "S-Sim, sou eu. Eu serei seu refém, apenas deixe a garota ir.",
  ui_story_5046_50460201_67_dialog_content = "Não faça nada estúpido, Dark Slayer!",
  ui_story_5046_50460201_68_dialog_content = "De novo com isso? Que irritante!",
  ui_story_5046_50460201_69_dialog_content = "O cachorrão é mau...",
  ui_story_5046_50460201_70_dialog_content = "Eca-!",
  ui_story_5046_50460201_71_dialog_content = "Dark Slayer tem PlayerName!",
  ui_story_5046_50460201_72_dialog_content = "Chegue mais perto e eu vou matá-lo.",
  ui_story_5046_50460201_73_dialog_content = "Já que este parece tão importante para você, deixe-me ficar com ele por um tempo.",
  ui_story_5046_50460201_74_dialog_content = "Ei, onde você está me levando? Solte-me!",
  ui_story_5046_50460201_75_dialog_content = "Socorro!",
  ui_story_5046_50460201_76_dialog_content = "Detenha-os, guardas!",
  ui_story_5046_50460201_77_dialog_content = "Não deixe Dark Slayer fugir com PlayerName!",
  ui_story_5046_50460202_1_dialog_content = "Os guardas perderam o Dark Slayer.",
  ui_story_5046_50460202_2_dialog_content = "Desculpe senhor...",
  ui_story_5046_50460202_3_dialog_content = "Não é sua culpa. O Dark Slayer pode controlar o fogo, o que lhe dá uma vantagem.",
  ui_story_5046_50460202_4_dialog_content = "Além disso, ela se move muito mais rápido do que as pessoas comuns.",
  ui_story_5046_50460202_5_dialog_content = "Não é uma surpresa que você não conseguiu acompanhá-la.",
  ui_story_5046_50460202_6_dialog_content = "Bem, seu plano de contingência foi útil.",
  ui_story_5046_50460202_7_dialog_content = "Ainda é caótico, mas pelo menos os convidados foram evacuados com segurança.",
  ui_story_5046_50460202_8_dialog_content = "Mas você poderia me explicar como PlayerName foi feito refém pelo Dark Slayer?",
  ui_story_5046_50460202_9_dialog_content = "Desculpe, falhamos em cumprir nosso dever.",
  ui_story_5046_50460202_10_dialog_content = "Não, é minha culpa que PlayerName foi sequestrado...",
  ui_story_5046_50460202_11_dialog_content = "Identificamos o suspeito, senhorita Bethel.",
  ui_story_5046_50460202_12_dialog_content = "Tudo bem, muito bem.",
  ui_story_5046_50460202_13_dialog_content = "\"Hati, mulher, 18 anos, local de nascimento desconhecido.\"",
  ui_story_5046_50460202_14_dialog_content = "\"Tive uma curta estadia no Orfanato Umbraton. O Shadowlord a acolheu depois que ela causou um incêndio que queimou o orfanato.\"",
  ui_story_5046_50460202_15_dialog_content = "(Pai...? Foi ideia do Pai?)",
  ui_story_5046_50460202_16_dialog_content = "Provocou um incêndio que queimou o orfanato? Parece um infrator reincidente.",
  ui_story_5046_50460202_17_dialog_content = "\"Hati completou 18 anos há dois meses e deixou a propriedade após uma avaliação bem-sucedida.\"",
  ui_story_5046_50460202_18_dialog_content = "(É melhor avisar o Pai sobre isso.)",
  ui_story_5046_50460202_19_dialog_content = "Como um incendiário conhecido como aquele poderia ser libertado...?",
  ui_story_5046_50460202_20_dialog_content = "De qualquer forma, vou transmitir isso ao Shadowlord e informar todas as facções em Umbraton para procurar PlayerNameparadeiro de.",
  ui_story_5046_50460202_21_dialog_content = "Mas isso vai tornar público...",
  ui_story_5046_50460202_22_dialog_content = "Estou preocupado com a reação no orfanato quando se espalha a notícia de que um VIP foi sequestrado durante o ensaio.",
  ui_story_5046_50460202_23_dialog_content = "Mas nem sabemos se PlayerName está vivo agora!",
  ui_story_5046_50460202_24_dialog_content = "Suspirar...",
  ui_story_5046_50460202_25_dialog_content = "Perder Bethel, Sr. Hamell.",
  ui_story_5046_50460202_26_dialog_content = "Se você está disposto a confiar em mim, por favor, mantenha PlayerNameseqüestro de sob sigilo por enquanto.",
  ui_story_5046_50460202_27_dialog_content = "Se divulgarmos, o Dark Slayer pode ameaçar PlayerNamevida de.",
  ui_story_5046_50460202_28_dialog_content = "Vou localizar o Dark Slayer e libertá-lo PlayerName O mais breve possível.",
  ui_story_5046_50460202_29_dialog_content = "...",
  ui_story_5046_50460202_30_dialog_content = "Por favor, perdoe-me por não ter confiança em você.",
  ui_story_5046_50460202_31_dialog_content = "Se você não pode confiar em nossas habilidades...",
  ui_story_5046_50460202_32_dialog_content = "Estou disposto a atestar meu instrutor, Knight Zenas, em nome de Ivan.",
  ui_story_5046_50460202_33_dialog_content = "Você não precisa fazer isso, minha senhora...",
  ui_story_5046_50460202_34_dialog_content = "Por favor, nos dê outra chance de compensar nosso erro, Srta. Bethel.",
  ui_story_5046_50460202_35_dialog_content = "Eu ouvi histórias sobre o Cavaleiro Zenas.",
  ui_story_5046_50460202_36_dialog_content = "Muito impressionante abrir caminho de uma família nobre decadente para onde ele está agora.",
  ui_story_5046_50460202_37_dialog_content = "Tudo bem, já que os Ivans estão atrás de você, vou confiar em você por enquanto.",
  ui_story_5046_50460202_38_dialog_content = "Mas esteja ciente de que o Shadowlord ouvirá sobre isso eventualmente.",
  ui_story_5046_50460202_39_dialog_content = "Você tem três dias.",
  ui_story_5046_50460202_40_dialog_content = "Eu quero PlayerName na cerimônia, ileso, três dias depois.",
  ui_story_5046_50460202_41_dialog_content = "Se você não pode fazer isso, eu vou lidar com isso do jeito Umbraton.",
  ui_story_5046_50460202_42_dialog_content = "Minha gratidão.",
  ui_story_5046_50460202_43_dialog_content = "Meu também.",
  ui_story_5046_50460202_44_dialog_content = "Ok, é assim que vamos lidar com PlayerNameé o sequestro de agora.",
  ui_story_5046_50460202_45_dialog_content = "Enquanto isso, precisaremos de sua ajuda para acalmar os convidados, Sr. Hamell.",
  ui_story_5046_50460202_46_dialog_content = "É claro é claro!",
  ui_story_5046_50460202_47_dialog_content = "Por aqui, Sr. Hamell.",
  ui_story_5046_50460202_48_dialog_content = "Por favor, deixe-me ajudá-lo a rastrear o Dark Slayer, senhor.",
  ui_story_5046_50460202_49_dialog_content = "Eu gastei muito esforço aprendendo Luminatics e habilidades de combate ao longo dos anos apenas para poder protegê-lo um dia.",
  ui_story_5046_50460202_50_dialog_content = "Por favor, dê-me uma chance!",
  ui_story_5046_50460202_51_dialog_content = "Não.",
  ui_story_5046_50460202_52_dialog_content = "Você não confia em mim por causa do que aconteceu naquele incêndio?",
  ui_story_5046_50460202_53_dialog_content = "É tudo culpa minha. E você teve que me salvar de outro incêndio.",
  ui_story_5046_50460202_54_dialog_content = "Oh, por que eu sempre coloco você em apuros...?",
  ui_story_5046_50460202_55_dialog_content = "Pare de se culpar, minha senhora.",
  ui_story_5046_50460202_56_dialog_content = "Eu sempre vou resgatá-lo das culpas, no passado, presente e futuro.",
  ui_story_5046_50460202_57_dialog_content = "Então por que...",
  ui_story_5046_50460202_58_dialog_content = "Você é capaz de discernir pistas vitais de relatórios de crimes e documentos associados.",
  ui_story_5046_50460202_59_dialog_content = "Então, comparado a perseguir o culpado no campo, acho que investigar a cena do crime e investigar os documentos são mais adequados para você.",
  ui_story_5046_50460202_60_dialog_content = "Prefiro não ver você se forçando a fazer algo em que não é bom.",
  ui_story_5046_50460202_61_dialog_content = "Eu chamaria isso de algo que não faço com frequência, em vez de algo em que não sou bom...",
  ui_story_5046_50460202_62_dialog_content = "Minha dama?",
  ui_story_5046_50460202_63_dialog_content = "N-Nada.",
  ui_story_5046_50460202_64_dialog_content = "Então, por favor, fique para trás e examine o local do incêndio criminoso. Tenho certeza que você encontrará leads valiosos.",
  ui_story_5046_50460202_65_dialog_content = "Ok, entendi!",
  ui_story_5046_50460202_66_dialog_content = "Não deixarei pedra sobre pedra!",
  ui_story_5046_50460202_67_dialog_content = "Pai, foi isso que aconteceu.",
  ui_story_5046_50460202_68_dialog_content = "O que devemos fazer em seguida?",
  ui_story_5046_50460202_69_dialog_content = "Hum...",
  ui_story_5046_50460202_70_dialog_content = "Não é uma coisa agora.",
  ui_story_5046_50460202_71_dialog_content = "Mas e quanto a PlayerName...",
  ui_story_5046_50460202_72_dialog_content = "Não se preocupe, alguém vai ficar de olho PlayerName.",
  ui_story_5046_50460202_73_dialog_content = "Sim, meu senhor.",
  ui_story_5046_50460301_1_dialog_content = "<color=#e8d9bb>Firefly Bar em Umbraton</color>",
  ui_story_5046_50460301_2_dialog_content = "Você voltou.",
  ui_story_5046_50460301_3_dialog_content = "(Onde Dark Slayer me levou?)",
  ui_story_5046_50460301_4_dialog_content = "Achei que você tinha ido ao ensaio hoje? E o que há com o gato de rua que você trouxe de volta?",
  ui_story_5046_50460301_5_dialog_content = "(Parece que estou em um bar. Provavelmente devo fingir que ainda estou fora e ouvir o que eles dizem...)",
  ui_story_5046_50460301_6_dialog_content = "É o carrapicho que gruda em você.",
  ui_story_5046_50460301_7_dialog_content = "Haha, você quer dizer a semente com espinhos afiados que ficam em suas roupas como os cardos?",
  ui_story_5046_50460301_8_dialog_content = "Sim. Mamãe costumava trazê-los para casa sem querer, e eu sempre os pegava dela.",
  ui_story_5046_50460301_9_dialog_content = "Oh, você conseguiu a coisa?",
  ui_story_5046_50460301_10_dialog_content = "Não. O carrapicho me segurou, e então mais pessoas apareceram, então eu não pude fazer nenhum movimento.",
  ui_story_5046_50460301_11_dialog_content = "O cocklebur parece ser uma figura muito importante. Eles estavam preocupados.",
  ui_story_5046_50460301_12_dialog_content = "Ei, este não é o celestita?",
  ui_story_5046_50460301_13_dialog_content = "O que foi?",
  ui_story_5046_50460301_14_dialog_content = "Você não conhece a Celestita? Ah, isso mesmo, esqueci que você só está no mundo há dois meses.",
  ui_story_5046_50460301_15_dialog_content = "Os celestitas gostam de fingir que estão dormindo?",
  ui_story_5046_50460301_16_dialog_content = "(O quê? Ela sabe que estou espionando?!)",
  ui_story_5046_50460301_17_dialog_content = "Não sei. Nenhum tabloide em Umbraton mencionou isso.",
  ui_story_5046_50460301_18_dialog_content = "Ei, levante-se.",
  ui_story_5046_50460301_19_dialog_content = "(Ela está me sacudindo com força suficiente para quebrar meus ossos!)",
  ui_story_5046_50460301_20_dialog_content = "(Vou ter que fingir que acabei de acordar.)",
  ui_story_5046_50460301_21_dialog_content = "Hum...",
  ui_story_5046_50460301_22_dialog_content = "Onde estou?",
  ui_story_5046_50460301_23_dialog_content = "Por que você finge que acabou de acordar? Você estava espiando pelo bar quando entramos.",
  ui_story_5046_50460301_24_dialog_content = "Uh, haha, do que você está falando? Eu obviamente apenas recuperei meus sentidos.",
  ui_story_5046_50460301_25_dialog_content = "Uma boa pessoa não mentiria.",
  ui_story_5046_50460301_26_dialog_content = "Tudo bem, não vamos assustar PlayerName.",
  ui_story_5046_50460301_27_dialog_content = "Como você sabe meu nome?",
  ui_story_5046_50460301_28_dialog_content = "Você é popular em todo o país. Não é incomum saber quem você é.",
  ui_story_5046_50460301_29_dialog_content = "Bem, isso é verdade.",
  ui_story_5046_50460301_30_dialog_content = "Não fique nervoso. Não temos más intenções.",
  ui_story_5046_50460301_31_dialog_content = "Sou Grimme, o barman deste Firefly Bar.",
  ui_story_5046_50460301_32_dialog_content = "ela é Hati, atualmente trabalhando para o bar.",
  ui_story_5046_50460301_33_dialog_content = "Quanto ao que eu sou para ela... Você pode me chamar de guardião dela.",
  ui_story_5046_50460301_34_dialog_content = "Ela está sob meus cuidados desde que deixou o Shadowlord.",
  ui_story_5046_50460301_35_dialog_content = "Não se deixe enganar pela aparência dela. Ela pode parecer vinte e poucos anos, mas na verdade tem apenas dezoito anos!",
  ui_story_5046_50460301_36_dialog_content = "E ela só está no mundo real há dois meses, então sua mente está mais próxima de uma criança de sete ou oito anos.",
  ui_story_5046_50460301_37_dialog_content = "não tenho certeza porque Hati trouxe você de volta, mas acredite em mim, ela é uma boa criança.",
  ui_story_5046_50460301_38_dialog_content = "Você acha que sequestrar alguém é bom...?",
  ui_story_5046_50460301_39_dialog_content = "Ela é apenas direta e direta, mas não faz mal.",
  ui_story_5046_50460301_40_dialog_content = "Embora ela seja a culpada por isso, vou fazê-la se desculpar com você.",
  ui_story_5046_50460301_41_dialog_content = "Agora, por que eu deveria me desculpar com essa pessoa?",
  ui_story_5046_50460301_42_dialog_content = "Todos eles me trataram como um cara mau e continuaram me chamando de Dark Slayer...",
  ui_story_5046_50460301_43_dialog_content = "Apesar do que foi dito a você, você está errado em sequestrar alguém.",
  ui_story_5046_50460301_44_dialog_content = "Você tem que se desculpar quando faz algo errado.",
  ui_story_5046_50460301_45_dialog_content = "Tsc...",
  ui_story_5046_50460301_46_dialog_content = "Desculpe.",
  ui_story_5046_50460301_47_dialog_content = "(Eu não esperava que alguém tão feroz fosse ouvir Grimme...)",
  ui_story_5046_50460301_48_dialog_content = "Eu não deveria ter feito isso, PlayerName.",
  ui_story_5046_50460301_49_dialog_content = "(Isso soou sincero, e ela realmente não me fez nenhum mal...)",
  ui_story_5046_50460301_50_dialog_content = "S-Claro, dado o quão sincero você é, eu te perdôo.",
  ui_story_5046_50460301_51_dialog_content = "Então vocês dois apertam as mãos e recomeçamos do zero.",
  ui_story_5046_50460301_52_dialog_content = "...",
  ui_story_5046_50460301_53_dialog_content = "...",
  ui_story_5046_50460301_54_dialog_content = "Haha, vocês dois agem da mesma forma quando estão em desacordo.",
  ui_story_5046_50460301_55_dialog_content = "Não me misture com ela...",
  ui_story_5046_50460301_56_dialog_content = "Oh, ouvi dizer que os celestitas têm habilidades psíquicas e podem vislumbrar profundamente a memória dos outros.",
  ui_story_5046_50460301_57_dialog_content = "Talvez PlayerName pode ajudá-lo a lembrar o que aconteceu com sua mãe.",
  ui_story_5046_50460301_58_dialog_content = "(Hati parece muito triste quando sua mãe é mencionada.)",
  ui_story_5046_50460301_59_dialog_content = "Você não queria saber o que aconteceu, Hati?",
  ui_story_5046_50460301_60_dialog_content = "Você acha que esse cara pode ajudar?",
  ui_story_5046_50460301_61_dialog_content = "Você está olhando para mim? E por que eu deveria fazer isso?",
  ui_story_5046_50460301_62_dialog_content = "Hmm, parece que temos um dilema.",
  ui_story_5046_50460301_63_dialog_content = "Que tal isso, então? Se eu te ajudar com meus poderes, você terá que me aceitar de volta.",
  ui_story_5046_50460301_64_dialog_content = "Também, Hati tem que se entregar por todos os crimes que cometeu!",
  ui_story_5046_50460301_65_dialog_content = "Que é razoável. Podemos ir com isso.",
  ui_story_5046_50460301_66_dialog_content = "Mas Hati não fez todas essas coisas, posso atestar isso.",
  ui_story_5046_50460301_67_dialog_content = "Se você estiver interessado em solucionar os casos, poderá descobrir o culpado com Hati.",
  ui_story_5046_50460301_68_dialog_content = "Que tal uma pechincha pela sua ajuda?",
  ui_story_5046_50460301_69_dialog_content = "É um acordo!",
  ui_story_5046_50460301_70_dialog_content = "...",
  ui_story_5046_50460301_71_dialog_content = "Se você realmente pode recuperar essa memória para mim...",
  ui_story_5046_50460301_72_dialog_content = "Não me importo que você me entregue pelas recompensas de 200.000 Nightium.",
  ui_story_5046_50460301_73_dialog_content = "Relaxa, se não foi você não troco pelo dinheiro.",
  ui_story_5046_50460301_74_dialog_content = "Mesmo que 200.000 seja muito, eu nunca faria isso por ganância.",
  ui_story_5046_50460301_75_dialog_content = "Não importa para mim.",
  ui_story_5046_50460301_76_dialog_content = "A-Tudo bem, então apenas me ajude a descobrir o que fazer.",
  ui_story_5046_50460301_77_dialog_content = "Você tem que ser o mais detalhado possível com a história para que eu maximize o resultado.",
  ui_story_5046_50460301_78_dialog_content = "Eu quero encontrar minha mãe.",
  ui_story_5046_50460301_79_dialog_content = "Morei com ela quando era pequena. Ela não era boa nem má para mim.",
  ui_story_5046_50460301_80_dialog_content = "Até que um dia nos separamos por motivos desconhecidos.",
  ui_story_5046_50460301_81_dialog_content = "A próxima coisa que eu sabia, eu estava no orfanato.",
  ui_story_5046_50460301_82_dialog_content = "Então você está dizendo que falta uma parte em sua memória.",
  ui_story_5046_50460301_83_dialog_content = "Se conseguirmos recuperá-lo, é possível encontrar sua mãe.",
  ui_story_5046_50460301_84_dialog_content = "Isso mesmo.",
  ui_story_5046_50460301_85_dialog_content = "Isso é tudo que você tem para continuar?",
  ui_story_5046_50460301_86_dialog_content = "De uma vez só.",
  ui_story_5046_50460301_87_dialog_content = "OK. Eu posso entender que você não acredita em mim ou em minhas habilidades psíquicas.",
  ui_story_5046_50460301_88_dialog_content = "Mas vou tentar o meu melhor para fazer o que prometi.",
  ui_story_5046_50460301_89_dialog_content = "...",
  ui_story_5046_50460301_90_dialog_content = "Desculpe, PlayerName, o garoto é novo no mundo e não se abrirá facilmente.",
  ui_story_5046_50460301_91_dialog_content = "Tudo bem. Eu só espero que você faça o que foi prometido e depois me deixe ir.",
  ui_story_5046_50460301_92_dialog_content = "Hati, preciso que você se concentre em recordar a última coisa que viu antes de a memória ser interrompida.",
  ui_story_5046_50460301_93_dialog_content = "Avise-me quando estiver pronto.",
  ui_story_5046_50460301_94_dialog_content = "Tô pronta.",
  ui_story_5046_50460301_95_dialog_content = "Respire fundo, Hati, e relaxe.",
  ui_story_5046_50460301_96_dialog_content = "Vamos lá.",
  ui_story_5046_50460301_97_option_content = "Aumento de Força!",
  ui_story_5046_50460301_98_dialog_content = "...",
  ui_story_5046_50460301_99_dialog_content = "(Onde estou? Parece uma casa comum.)",
  ui_story_5046_50460301_100_dialog_content = "(É aqui que Hati vivido?)",
  ui_story_5046_50460301_101_dialog_content = "(PlayerName?)",
  ui_story_5046_50460301_102_dialog_content = "(Você pode ver em minha memória.)",
  ui_story_5046_50460301_103_dialog_content = "(Agora você acredita em mim?)",
  ui_story_5046_50460301_104_dialog_content = "<color=#e8d9bb>Patrão Pitter...</color>",
  ui_story_5046_50460301_105_dialog_content = "(Eu ouço passos e eles estão se aproximando.)",
  ui_story_5046_50460301_106_dialog_content = "Para onde você fugiu desta vez, Hati?",
  ui_story_5046_50460301_107_dialog_content = "(Quem é?)",
  ui_story_5046_50460301_108_dialog_content = "(Mãe...)",
  ui_story_5046_50460301_109_dialog_content = "Suspirar...",
  ui_story_5046_50460301_110_dialog_content = "Está ficando cada vez mais difícil controlar o poder daquela criança, e estou preocupada...",
  ui_story_5046_50460301_111_dialog_content = "Não só isso, ela está começando a ansiar pelo mundo exterior.",
  ui_story_5046_50460301_112_dialog_content = "Mas eu nunca devo deixá-la sair...",
  ui_story_5046_50460301_113_dialog_content = "(Por que ela não deixaria Hati fora?)",
  ui_story_5046_50460301_114_dialog_content = "(Porque ela teme meus poderes, teme meu... fogo.)",
  ui_story_5046_50460301_115_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5046_50460301_116_dialog_content = "*Rugido*",
  ui_story_5046_50460301_117_dialog_content = "(Uau-!)",
  ui_story_5046_50460301_118_dialog_content = "(Isso é um cachorro ou um lobo? É tão grande!!!)",
  ui_story_5046_50460301_119_dialog_content = "(E um tanto parecido Hati...)",
  ui_story_5046_50460301_120_dialog_content = "(É o meu demônio interior, a personificação dos medos e ódio pelo meu próprio poder.)",
  ui_story_5046_50460301_121_dialog_content = "(Está guardando a memória perdida e não me deixa chegar perto.)",
  ui_story_5046_50460301_122_dialog_content = "(Urgh-! Minha cabeça dói!)",
  ui_story_5046_50460301_123_dialog_content = "(O que há de errado? Você não parece bem.)",
  ui_story_5046_50460301_124_dialog_content = "Você me odeia...? Mas eu sou... você...",
  ui_story_5046_50460301_125_dialog_content = "(Isso não parece certo. Eu deveria terminar a sessão aqui!)",
  ui_story_5046_50460301_126_dialog_content = "Você pode ver minha memória, PlayerName, e até meu demônio interior...",
  ui_story_5046_50460301_127_dialog_content = "O poder de um celestita é verdadeiramente maravilhoso.",
  ui_story_5046_50460301_128_dialog_content = "Fizemos progressos com as habilidades psíquicas do celestita, pelo que vejo.",
  ui_story_5046_50460301_129_dialog_content = "Isso é maravilhoso, Hati.",
  ui_story_5046_50460301_130_dialog_content = "Hati fiquei extremamente emocionado quando o demônio interior apareceu, então encerrei a sessão.",
  ui_story_5046_50460301_131_dialog_content = "Não ganhamos mais nada com isso.",
  ui_story_5046_50460301_132_dialog_content = "Quanto mais você souber, mais fácil para você me ajudar a lembrar, certo?",
  ui_story_5046_50460301_133_dialog_content = "Hã?",
  ui_story_5046_50460301_134_dialog_content = "S-Sim, está certo...",
  ui_story_5046_50460301_135_dialog_content = "Então, se eu contar mais, você pode usar o poder novamente?",
  ui_story_5046_50460301_136_dialog_content = "Sim eu posso...",
  ui_story_5046_50460301_137_dialog_content = "Mas você tem que me deixar ir como você prometeu.",
  ui_story_5046_50460301_138_dialog_content = "Combinado.",
  ui_story_5046_50460401_1_dialog_content = "Este é o relatório sobre o incêndio do orfanato para sua leitura, Juiz Kristen.",
  ui_story_5046_50460401_2_dialog_content = "Obrigado. Eu sou apenas um estagiário agora, então me ligue Kristen.",
  ui_story_5046_50460401_3_dialog_content = "A fonte era combustível inflamável e estava armazenado no depósito junto com outros restos de materiais de construção.",
  ui_story_5046_50460401_4_dialog_content = "Todos estavam muito ocupados com a cerimônia para prestar atenção ao combustível extra armazenado.",
  ui_story_5046_50460401_5_dialog_content = "O combustível é idêntico ao encontrado em locais de incêndio criminoso nos últimos dois meses, então a mesma pessoa deve ser responsável.",
  ui_story_5046_50460401_6_dialog_content = "Sim, essa é uma conclusão lógica.",
  ui_story_5046_50460401_7_dialog_content = "Mas nunca houve um sequestro em nenhum dos casos anteriores, e o celestita foi pego desta vez...",
  ui_story_5046_50460401_8_dialog_content = "Isso não parece se encaixar no padrão. E qual é o motivo do suspeito?",
  ui_story_5046_50460401_9_dialog_content = "De acordo com relatos de testemunhas oculares, o suspeito é um auroriano demi-humano chamado Hati.",
  ui_story_5046_50460401_10_dialog_content = "Hati estava morando na mansão do Shadowlord até dois meses atrás. Este é o arquivo dela.",
  ui_story_5046_50460401_11_dialog_content = "Hum...",
  ui_story_5046_50460401_12_dialog_content = "\"Segundo testemunhas oculares, Hati liberou uma enorme chama de Lumina na noite do incêndio no orfanato e causou um grande incêndio.\"",
  ui_story_5046_50460401_13_dialog_content = "Todas as pistas atuais apontam para o semi-humano chamado Hati.",
  ui_story_5046_50460401_14_dialog_content = "E todos os incêndios criminosos aconteceram depois que ela deixou a mansão do Shadowlord. No entanto, qual seria o motivo dela?",
  ui_story_5046_50460401_15_dialog_content = "Ah, e a garotinha que acabamos de resgatar...",
  ui_story_5046_50460401_16_dialog_content = "Nós a colocamos no dormitório do orfanato sob a vigilância do zelador.",
  ui_story_5046_50460401_17_dialog_content = "Deixe-me ir perguntar a ela o que aconteceu.",
  ui_story_5046_50460401_18_dialog_content = "Olá eu sou Kristen, um juiz estagiário de Lumopolis.",
  ui_story_5046_50460401_19_dialog_content = "Eu gostaria de perguntar a esta criança sobre o incêndio.",
  ui_story_5046_50460401_20_dialog_content = "Uma nobre senhora de Lumópolis, pelo que vejo. Não posso recusar seu pedido, mas saiba que a criança finalmente se acalmou há apenas um momento.",
  ui_story_5046_50460401_21_dialog_content = "Você deve fazê-lo rápido, pois devo pedir-lhe para sair se a criança fizer outra birra.",
  ui_story_5046_50460401_22_dialog_content = "Obrigado pelo pensamento. Vou acabar com isso o mais rápido possível.",
  ui_story_5046_50460401_23_dialog_content = "Olá, pequenino.",
  ui_story_5046_50460401_24_dialog_content = "Ei, você é a senhora de antes!",
  ui_story_5046_50460401_25_dialog_content = "O cachorrão e o cara gentil que me salvou também estão aqui?",
  ui_story_5046_50460401_26_dialog_content = "Ah, eles não estão aqui. Você conhece os dois?",
  ui_story_5046_50460401_27_dialog_content = "Não. Mas o gentil me protegeu no fogo então ele é uma boa pessoa!",
  ui_story_5046_50460401_28_dialog_content = "E quando uma trave caiu, o grande cãozinho apareceu e nos salvou!",
  ui_story_5046_50460401_29_dialog_content = "(Hati os salvou?)",
  ui_story_5046_50460401_30_dialog_content = "Você pode me dizer por que você estava lá?",
  ui_story_5046_50460401_31_dialog_content = "Soluço...",
  ui_story_5046_50460401_32_dialog_content = "O que houve?",
  ui_story_5046_50460401_33_dialog_content = "Quer um doce, pequenino?",
  ui_story_5046_50460401_34_dialog_content = "Sim!",
  ui_story_5046_50460401_35_dialog_content = "*Chews* Então, eu estava brincando de esconde-esconde e me escondi dentro daquela casa.",
  ui_story_5046_50460401_36_dialog_content = "Havia muitos barris dentro e uma caixinha esquisita.",
  ui_story_5046_50460401_37_dialog_content = "Caixinha estranha?",
  ui_story_5046_50460401_38_dialog_content = "Eu o empurrei acidentalmente para o chão e ele começou a queimar!",
  ui_story_5046_50460401_39_dialog_content = "Tentei sair correndo, mas tinha fogo por toda parte, era assustador.",
  ui_story_5046_50460401_40_dialog_content = "Boo-hoo... Eu não queria queimar a casa...",
  ui_story_5046_50460401_41_dialog_content = "Uau!",
  ui_story_5046_50460401_42_dialog_content = "O fogo foi tão assustador!",
  ui_story_5046_50460401_43_dialog_content = "Tudo bem, você a fez chorar de novo. O tempo acabou, você tem que sair agora.",
  ui_story_5046_50460401_44_dialog_content = "Desculpe... Agora, pequenino, não vá a algum lugar desconhecido da próxima vez.",
  ui_story_5046_50460401_45_dialog_content = "Boo-hoo... entendi...",
  ui_story_5046_50460401_46_dialog_content = "<color=#e8d9bb>Firefly Bar em Umbraton</color>",
  ui_story_5046_50460401_47_dialog_content = "Não, ainda não me lembro...",
  ui_story_5046_50460401_48_dialog_content = "Mesmo com todos os detalhes, seu poder ainda não consegue recuperar a memória perdida para mim?",
  ui_story_5046_50460401_49_dialog_content = "Me desculpe por não poder ajudar...",
  ui_story_5046_50460401_50_dialog_content = "É muito gentil de sua parte não culpá-la por sequestrá-lo e até mesmo tentar ajudá-la com suas habilidades psíquicas.",
  ui_story_5046_50460401_51_dialog_content = "Tem que haver outra maneira!",
  ui_story_5046_50460401_52_dialog_content = "O pingente! Sim, o pingente!",
  ui_story_5046_50460401_53_dialog_content = "O pingente?",
  ui_story_5046_50460401_54_dialog_content = "Eu o sequestrei para negociar com o homem mascarado pelo pingente.",
  ui_story_5046_50460401_55_dialog_content = "Esse pingente é muito significativo para mim, assim como você é muito significativo para aquele homem mascarado.",
  ui_story_5046_50460401_56_dialog_content = "É um comércio justo.",
  ui_story_5046_50460401_57_dialog_content = "Trocar-me por um pingente? Que rude de sua parte propor isso!",
  ui_story_5046_50460401_58_dialog_content = "Nenhum conhecimento social!",
  ui_story_5046_50460401_59_dialog_content = "Você não tem nada a dizer como guardião dela, Grimme?",
  ui_story_5046_50460401_60_dialog_content = "Foi direto, mas não vi nada de errado no que ela disse.",
  ui_story_5046_50460401_61_dialog_content = "Você pode voltar e Hati consegue o que quer ao consumar a troca.",
  ui_story_5046_50460401_62_dialog_content = "Isso não é razoável?",
  ui_story_5046_50460401_63_dialog_content = "T-Isso faz sentido...",
  ui_story_5046_50460401_64_dialog_content = "Espere um minuto, você não prometeu me deixar ir se eu ajudasse?",
  ui_story_5046_50460401_65_dialog_content = "Por que eu sou uma moeda de troca agora?! Você está bem!",
  ui_story_5046_50460401_66_dialog_content = "Mas Hati não recuperou a memória.",
  ui_story_5046_50460401_67_dialog_content = "As pessoas em Umbraton são todas desonestas, eu vejo.",
  ui_story_5046_50460401_68_dialog_content = "(Não é bom ser tratado como um chip, embora eu não me machuque de outra forma...)",
  ui_story_5046_50460401_69_dialog_content = "(Talvez eu possa escapar quando eles não estiverem olhando, encontrar Bethel e deixe-a saber disso...)",
  ui_story_5046_50460401_70_dialog_content = "Só precisamos descobrir como fazer um acordo com o homem mascarado.",
  ui_story_5046_50460401_71_dialog_content = "Há cartazes de procurado por toda a cidade, Hati. Se você aparecer, será preso antes de chegar à mesa de negociações.",
  ui_story_5046_50460401_72_dialog_content = "Vamos fazer isso. Você escreve uma mensagem, Hati, e vou entregá-lo ao homem.",
  ui_story_5046_50460401_73_dialog_content = "Peça a ele para vir sozinho para algum lugar fora de Umbraton.",
  ui_story_5046_50460401_74_dialog_content = "Tá bom.",
  ui_story_5046_50460401_75_dialog_content = "Observe o cara de perto, Grimme, para que não haja escapatória.",
  ui_story_5046_50460401_76_dialog_content = "Tente correr, apague a luz, assim como arrastei o corpo para dentro.",
  ui_story_5046_50460401_77_dialog_content = "O quê?",
  ui_story_5046_50460401_78_dialog_content = "Quer algo para beber? Você pode voltar assim que o negócio estiver fechado.",
  ui_story_5046_50460401_79_dialog_content = "Então você não terá a chance de desfrutar de uma rodada.",
  ui_story_5046_50460401_80_dialog_content = "Qual é a história desse pingente?",
  ui_story_5046_50460401_81_dialog_content = "Porque Hati quer tanto?",
  ui_story_5046_50460401_82_dialog_content = "Bem, posso contar a história agora que Hati não está por perto.",
  ui_story_5046_50460401_83_dialog_content = "Lembro-me de um dia, Hati correu de volta e me disse que viu o pingente de sua mãe em um homem mascarado.",
  ui_story_5046_50460401_84_dialog_content = "Homem mascarado? Deve ser o capitão Zenas. Ele é o único que usa máscara.",
  ui_story_5046_50460401_85_dialog_content = "Ela se aproximou dele antes, mas ele parecia muito surpreso ao vê-la e não queria desistir do pingente por nada.",
  ui_story_5046_50460401_86_dialog_content = "Então ela está planejando obter o pingente dele desde então.",
  ui_story_5046_50460401_87_dialog_content = "Isso constitui um crime!",
  ui_story_5046_50460401_88_dialog_content = "E porque é Hati então tem certeza que o pingente de Zenas é o que ela está procurando?",
  ui_story_5046_50460401_89_dialog_content = "Ela disse que sentiu dor de cabeça na primeira vez que viu o pingente em Zenas.",
  ui_story_5046_50460401_90_dialog_content = "Ela disse que se lembrava muito claramente de que o padrão correspondia exatamente ao de sua mãe.",
  ui_story_5046_50460401_91_dialog_content = "Ela também disse que conseguir aquele pingente permitirá que ela recupere ainda mais memórias perdidas.",
  ui_story_5046_50460401_92_dialog_content = "Você quer dizer o padrão do pequeno pônei?",
  ui_story_5046_50460401_93_dialog_content = "Ouvi dizer que toda família nobre em Lumopolis tem seu próprio brasão, então as mães de Zenas e Hati vêm da mesma linhagem?",
  ui_story_5046_50460401_94_dialog_content = "Isso eu não sei.",
  ui_story_5046_50460401_95_dialog_content = "A mensagem está pronta.",
  ui_story_5046_50460401_96_dialog_content = "<color=#e8d9bb>Toc-toc, toc, toc-toc</color>",
  ui_story_5046_50460401_97_dialog_content = "Bem na hora. Entre.",
  ui_story_5046_50460401_98_dialog_content = "Chefe.",
  ui_story_5046_50460401_99_dialog_content = "Está tudo bem, Hati e PlayerName são legais.",
  ui_story_5046_50460401_100_dialog_content = "Nada com as facções de Umbraton até agora. O cavaleiro de Lumopolis está a caminho do bar com as pessoas agora.",
  ui_story_5046_50460401_101_dialog_content = "Eles devem estar aqui a qualquer momento.",
  ui_story_5046_50460401_102_dialog_content = "É assim mesmo? No momento ideal.",
  ui_story_5046_50460401_103_dialog_content = "Bom trabalho. Aqui está o seu pagamento.",
  ui_story_5046_50460401_104_dialog_content = "Obrigado, chefe!",
  ui_story_5046_50460401_105_dialog_content = "Eu vou embora agora.",
  ui_story_5046_50460401_106_dialog_content = "(Aquele garoto é o informante de Grimme? Quem é Grimme, realmente...?)",
  ui_story_5046_50460401_107_dialog_content = "Eu vou entregar a mensagem, Hati. Você se dirige ao ponto de encontro.",
  ui_story_5046_50460401_108_dialog_content = "OK. Vamos, PlayerName.",
  ui_story_5046_50460401_109_dialog_content = "É melhor vir em silêncio e não tentar pedir ajuda, ou...",
  ui_story_5046_50460401_110_dialog_content = "Ou você vai me nocautear, certo?",
  ui_story_5046_50460401_111_dialog_content = "Espero que você faça o que prometeu desta vez - deixe-me ir assim que tiver o pingente.",
  ui_story_5046_50460401_112_dialog_content = "Os guardas de Lumopolis estão por perto, então tome cuidado ao sair.",
  ui_story_5046_50460401_113_dialog_content = "Vou nocauteá-los silenciosamente.",
  ui_story_5046_50460402_1_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5046_50460402_2_dialog_content = "Bem-vindo. O que você gostaria de beber?",
  ui_story_5046_50460402_3_dialog_content = "Oh, são funcionários de Lumopolis. O que o traz ao meu pequeno bar Umbraton, posso perguntar?",
  ui_story_5046_50460402_4_dialog_content = "Não estamos aqui para bater papo, apenas para fazer algumas perguntas.",
  ui_story_5046_50460402_5_dialog_content = "Por que você não fica por aqui e toma uma bebida? Vou contar tudo o que sei.",
  ui_story_5046_50460402_6_dialog_content = "Não é necessário.",
  ui_story_5046_50460402_7_dialog_content = "Testemunhas afirmaram que o incendiário no ensaio era seu amigo Hati.",
  ui_story_5046_50460402_8_dialog_content = "A julgar pela rota de fuga, acreditamos que ela fugiu para este bar.",
  ui_story_5046_50460402_9_dialog_content = "Esperamos que coopere com nossa investigação.",
  ui_story_5046_50460402_10_dialog_content = "Eu adoraria, mas espero que você possa produzir evidências concretas de que Hati é o incendiário.",
  ui_story_5046_50460402_11_dialog_content = "Ou não posso te ajudar.",
  ui_story_5046_50460402_12_dialog_content = "Então teremos que procurar à força.",
  ui_story_5046_50460402_13_dialog_content = "Hati tem o celestita.",
  ui_story_5046_50460402_14_dialog_content = "!",
  ui_story_5046_50460402_15_dialog_content = "A segurança de Lumopolis veio a Umbraton apenas para perder um VIP.",
  ui_story_5046_50460402_16_dialog_content = "Perder Bethel não recorreu a nenhuma facção da Umbraton, mas permitiu que você investigasse secretamente.",
  ui_story_5046_50460402_17_dialog_content = "Meu palpite é que ela não queria que isso saísse em público.",
  ui_story_5046_50460402_18_dialog_content = "Você também não quer que eu espalhe por aí, não é?",
  ui_story_5046_50460402_19_dialog_content = "Humph, então você sabe onde Hati é? Desista dela e você pode conseguir algo tanto de Lumopolis quanto de Umbraton.",
  ui_story_5046_50460402_20_dialog_content = "Sim, podemos falar sobre isso quando estivermos sozinhos.",
  ui_story_5046_50460402_21_dialog_content = "Deixe-nos, todos vocês.",
  ui_story_5046_50460402_22_dialog_content = "Mas capitão—",
  ui_story_5046_50460402_23_dialog_content = "Espere por mim lá fora.",
  ui_story_5046_50460402_24_dialog_content = "Sim, senhor.",
  ui_story_5046_50460402_25_dialog_content = "Há uma razão pela qual você chegou onde está hoje.",
  ui_story_5046_50460402_26_dialog_content = "Agora então, esta é uma mensagem que Hati queria que eu entregasse.",
  ui_story_5046_50460402_27_dialog_content = "\"Para o homem mascarado:\"",
  ui_story_5046_50460402_28_dialog_content = "\"Traga o pingente e me encontre sob a árvore de bordo mais alta no lado leste de Umbraton antes do pôr do sol. Você está trocando-o pelo Caelestita.\"",
  ui_story_5046_50460402_29_dialog_content = "\"Certifique-se de vir sozinho e não conte a ninguém. Não tente nenhum truque também.\"",
  ui_story_5046_50460402_30_dialog_content = "\"Hati\"",
  ui_story_5046_50460402_31_dialog_content = "...",
  ui_story_5046_50460402_32_dialog_content = "Você pode garantir que o Caelestite é seguro?",
  ui_story_5046_50460402_33_dialog_content = "Tenha certeza. O Celestite é completamente seguro. Além disso, o tempo não está do seu lado e é sua única escolha.",
  ui_story_5046_50460402_34_dialog_content = "Ninguém me ameaça.",
  ui_story_5046_50460402_35_dialog_content = "Vá com calma. Fique para uma bebida na próxima vez.",
  ui_story_5046_50460402_36_dialog_content = "...",
  ui_story_5046_50460402_37_dialog_content = "Chefe.",
  ui_story_5046_50460402_38_dialog_content = "Observe a barra. Eu tenho que ir.",
  ui_story_5046_50460402_39_dialog_content = "Capitão!",
  ui_story_5046_50460402_40_dialog_content = "Eu tenho que verificar algo sozinho.",
  ui_story_5046_50460402_41_dialog_content = "Vocês ficam por aqui e vasculham cada centímetro do lugar.",
  ui_story_5046_50460402_42_dialog_content = "Se você avistar o suspeito e o celestita, traga-os de volta, desde que a segurança do último esteja garantida.",
  ui_story_5046_50460402_43_dialog_content = "Sim, senhor!",
  ui_story_5046_50460402_44_dialog_content = "<color=#e8d9bb>Arquivo Umbraton</color>",
  ui_story_5046_50460402_45_dialog_content = "Tudo sobre os incêndios nos últimos dois meses está aqui.",
  ui_story_5046_50460402_46_dialog_content = "Obrigado. Eu mesmo os examinarei.",
  ui_story_5046_50460402_47_dialog_content = "Os incêndios aconteceram com muita frequência no período, mas apenas três morreram.",
  ui_story_5046_50460402_48_dialog_content = "André, sexo masculino, 36 anos, vítima do primeiro incêndio, trabalhava meio período e era alcoólatra.",
  ui_story_5046_50460402_49_dialog_content = "Fairmont, homem, 42 anos, vítima do segundo incêndio, um comerciante com um negócio morno.",
  ui_story_5046_50460402_50_dialog_content = "Carlotta, sexo feminino, 31 anos, vítima do terceiro incêndio, lavadeira comum.",
  ui_story_5046_50460402_51_dialog_content = "Todos os três já trabalharam no orfanato. Andre era contador, Fairmont entregador e Carlotta faxineira.",
  ui_story_5046_50460402_52_dialog_content = "E o denominador comum que eles compartilharam com Hati é o orfanato.",
  ui_story_5046_50460402_53_dialog_content = "Então era Hati intimidado por eles no orfanato e os matou por despeito?",
  ui_story_5046_50460402_54_dialog_content = "Devo cavar mais fundo no antigo pessoal do orfanato.",
  ui_story_5046_50460402_55_dialog_content = "Cada um deles se espalhou após o incêndio, no entanto. É praticamente impossível encontrar alguém com quem conversar.",
  ui_story_5046_50460402_56_dialog_content = "O que eu vou fazer?",
  ui_story_5046_50460402_57_dialog_content = "\"O Sr. Hamell faz doações para o orfanato há muito tempo e organiza regularmente eventos de caridade para arrecadar fundos para as instalações...\"",
  ui_story_5046_50460402_58_dialog_content = "Sr Hamell?!",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>dentro do orfanato</color>",
  ui_story_5046_50460402_60_dialog_content = "Posso tomar alguns minutos do seu tempo, Sr. Hamell?",
  ui_story_5046_50460402_61_dialog_content = "Perder Kristen! Você encontrou o Celestita, certo? Que maravilha!",
  ui_story_5046_50460402_62_dialog_content = "Ainda não há sinal do Caelestite, infelizmente, mas tenho algumas perguntas sobre o Dark Slayer que gostaria de fazer a você.",
  ui_story_5046_50460402_63_dialog_content = "Aquele incendiário?",
  ui_story_5046_50460402_64_dialog_content = "Hati é a principal suspeita no caso, e ela pode ter ateado fogo em vingança contra trabalhadores do antigo orfanato de quem guardava rancor.",
  ui_story_5046_50460402_65_dialog_content = "Você financia e administra instituições de caridade para a instalação há muito tempo, então deve conhecer bem a situação.",
  ui_story_5046_50460402_66_dialog_content = "Então eu gostaria de pedir a sua opinião.",
  ui_story_5046_50460402_67_dialog_content = "Bem, é verdade que financiei e gerenciei instituições de caridade para o orfanato.",
  ui_story_5046_50460402_68_dialog_content = "Mas o diretor e o pessoal realmente lidaram com os detalhes. Eu só tinha que mostrar minha cara nos eventos.",
  ui_story_5046_50460402_69_dialog_content = "O orfanato me apresentava relatórios financeiros regularmente, mas, fora isso, não sei de mais nada.",
  ui_story_5046_50460402_70_dialog_content = "Mas você é o diretor do novo orfanato e tinha uma estreita ligação com a antiga instalação.",
  ui_story_5046_50460402_71_dialog_content = "Então, se o suspeito está realmente mirando em antigos funcionários do orfanato para se vingar, você pode ser o próximo alvo.",
  ui_story_5046_50460402_72_dialog_content = "Espero que você possa se lembrar de mais detalhes. Isso nos ajudará a prender o suspeito.",
  ui_story_5046_50460402_73_dialog_content = "Além disso, espero que você possa fixar residência temporária em um local protegido pela Lumo Guard.",
  ui_story_5046_50460402_74_dialog_content = "O suspeito pode atacar e ameaçar sua vida a qualquer momento, e o Lumo Guard pode mantê-lo seguro.",
  ui_story_5046_50460402_75_dialog_content = "Perder Kristen, tudo o que você disse é conjectura.",
  ui_story_5046_50460402_76_dialog_content = "Você deveria saber, o orfanato costumava ser o maior em Umbraton. Muitas pessoas tinham uma conexão com isso.",
  ui_story_5046_50460402_77_dialog_content = "Você pode perguntar a qualquer um aqui e eles provavelmente têm algo a ver com as instalações.",
  ui_story_5046_50460402_78_dialog_content = "Trabalhadores da construção civil, equipe de limpeza e até vendedores ambulantes fora do orfanato...",
  ui_story_5046_50460402_79_dialog_content = "Está a dizer-me que o suspeito também os quer matar?",
  ui_story_5046_50460402_80_dialog_content = "Hum...",
  ui_story_5046_50460402_81_dialog_content = "A especulação é provavelmente apenas coincidência.",
  ui_story_5046_50460402_82_dialog_content = "Em vez de perder tempo com coincidências, talvez seja melhor gastá-lo perseguindo o suspeito e fazendo com que todos respirem melhor.",
  ui_story_5046_50460402_83_dialog_content = "Está ficando tarde. É hora desses velhos ossos se transformarem.",
  ui_story_5046_50460402_84_dialog_content = "Desculpe incomodá-lo. Adeus.",
  ui_story_5046_50460402_85_dialog_content = "Perdoe-me por não te ver sair.",
  ui_story_5046_50460402_86_dialog_content = "Já faz muito tempo, velho amigo.",
  ui_story_5046_50460402_87_dialog_content = "É você.",
  ui_story_5046_50460402_88_dialog_content = "Não está feliz em ver seu velho amigo?",
  ui_story_5046_50460402_89_dialog_content = "Eu não acho que você está aqui para mim, mas <color=#FFB400>aquela coisa</color>, certo?",
  ui_story_5046_50460501_1_dialog_content = "O Sr. Hamell estava agindo de forma um pouco suspeita, como se estivesse escondendo alguma coisa.",
  ui_story_5046_50460501_2_dialog_content = "Mas ele não estava disposto a dar mais informações.",
  ui_story_5046_50460501_3_dialog_content = "Hati é um suspeito, o sequestro do celestita, os combustíveis e o detonador no local do ensaio...",
  ui_story_5046_50460501_4_dialog_content = "O antigo incêndio do orfanato, a relutância do Sr. Hamell...",
  ui_story_5046_50460501_5_dialog_content = "Tudo pode ser apenas uma grande coincidência?",
  ui_story_5046_50460501_6_dialog_content = "Suspiro ... Estou perdendo o juízo.",
  ui_story_5046_50460501_7_dialog_content = "Se ao menos o Sr. Zenas estiver aqui. Ele tem certeza de—",
  ui_story_5046_50460501_8_dialog_content = "Você está procurando por mim, minha senhora?",
  ui_story_5046_50460501_9_dialog_content = "Senhor?!",
  ui_story_5046_50460501_10_dialog_content = "À Quanto tempo você esteve aqui?",
  ui_story_5046_50460501_11_dialog_content = "Um tempo. Eu vi você murmurando para si mesmo como se estivesse pensando profundamente, então decidi não interromper.",
  ui_story_5046_50460501_12_dialog_content = "Desculpa, não tinha notado...",
  ui_story_5046_50460501_13_dialog_content = "Oh, fiz uma grande descoberta no caso, senhor!",
  ui_story_5046_50460501_14_dialog_content = "Realmente? O que você achou?",
  ui_story_5046_50460501_15_dialog_content = "A garotinha que salvamos no ensaio disse que o fogo começou porque ela acidentalmente bateu em uma caixa.",
  ui_story_5046_50460501_16_dialog_content = "Suponho que a caixa seja um detonador definido para incendiar os barris de combustível estocados no depósito em um horário específico.",
  ui_story_5046_50460501_17_dialog_content = "Quem armou certamente não contava com a garotinha para atrapalhar o plano.",
  ui_story_5046_50460501_18_dialog_content = "Ignição temporizada... Mas para quê?",
  ui_story_5046_50460501_19_dialog_content = "Com base em investigações anteriores, houve apenas três incêndios nos últimos dois meses com vítimas.",
  ui_story_5046_50460501_20_dialog_content = "E todos os três falecidos já trabalharam para o antigo orfanato.",
  ui_story_5046_50460501_21_dialog_content = "Hati, que apareceu no local hoje, permaneceu naquela instalação por um mês.",
  ui_story_5046_50460501_22_dialog_content = "Acredito que algo deve ter acontecido com ela no orfanato para fazê-la odiar as vítimas.",
  ui_story_5046_50460501_23_dialog_content = "Depois de perder o controle de seu poder e incendiar o orfanato, ela foi levada pelo Shadowlord para uma mansão, então ela foi forçada a abandonar seu plano de vingança.",
  ui_story_5046_50460501_24_dialog_content = "Até que ela foi libertada há dois meses, levando Hati para ir imediatamente atrás deles.",
  ui_story_5046_50460501_25_dialog_content = "O Sr. Hamell tem sido um financiador de longa data do orfanato e também apareceu no local hoje.",
  ui_story_5046_50460501_26_dialog_content = "Então você está pensando Hati tem como alvo o Sr. Hamell.",
  ui_story_5046_50460501_27_dialog_content = "Sim, mas é apenas uma teoria sem nada sólido para apoiá-la.",
  ui_story_5046_50460501_28_dialog_content = "Então você foi ver o Sr. Hamell na esperança de que ele cooperasse.",
  ui_story_5046_50460501_29_dialog_content = "Sim...",
  ui_story_5046_50460501_30_dialog_content = "O Sr. Hamell rejeitou minha teoria como uma coincidência, mas tive a sensação de que ele estava escondendo algo de mim.",
  ui_story_5046_50460501_31_dialog_content = "Seu corpo está sempre um passo à frente de sua mente, minha senhora.",
  ui_story_5046_50460501_32_dialog_content = "O que quer dizer com isso, senhor?",
  ui_story_5046_50460501_33_dialog_content = "Todo mundo que poderia alcançar riqueza e fama em um saco misto como Umbraton tem seus próprios segredos.",
  ui_story_5046_50460501_34_dialog_content = "E esses segredos são suas linhas de vida que eles não gostariam que mais ninguém soubesse, especialmente os de Lumopolis.",
  ui_story_5046_50460501_35_dialog_content = "Eu posso entender como você quer proteger o Sr. Hamell, minha senhora, mas você só está alarmando o suspeito.",
  ui_story_5046_50460501_36_dialog_content = "O Sr. Hamell nunca cooperaria ou aceitaria sua proteção, e o suspeito provavelmente perceberá o que você fez e se esconderá ainda mais.",
  ui_story_5046_50460501_37_dialog_content = "É falta de visão da minha parte... Desculpe, senhor.",
  ui_story_5046_50460501_38_dialog_content = "Acontece que eu não sou de nenhuma ajuda para você...",
  ui_story_5046_50460501_39_dialog_content = "Mas não acho que sua teoria seja infundada. Nem tudo é coincidência.",
  ui_story_5046_50460501_40_dialog_content = "Aprova minha teoria, então, senhor?",
  ui_story_5046_50460501_41_dialog_content = "Claro. Tendo testemunhado seu desenvolvimento ao longo de todos esses anos, sei melhor do que ninguém do que você é capaz.",
  ui_story_5046_50460501_42_dialog_content = "Você é a melhor em extrair pistas de registros e reuni-las em um corpo abrangente de provas, minha senhora.",
  ui_story_5046_50460501_43_dialog_content = "S-Senhor...",
  ui_story_5046_50460501_44_dialog_content = "É porque você é um ótimo instrutor!",
  ui_story_5046_50460501_45_dialog_content = "...",
  ui_story_5046_50460501_46_dialog_content = "Aham. Não estava investigando o suspeito e o paradeiro do celestita, senhor?",
  ui_story_5046_50460501_47_dialog_content = "Sim. Isso me levou ao Firefly Bar, cujo dono é amigo de Hati.",
  ui_story_5046_50460501_48_dialog_content = "Mas ela estava de boca fechada, então não consegui entender nada. Tenho pessoas vigiando o bar, espero conseguir alguma coisa.",
  ui_story_5046_50460501_49_dialog_content = "Ai...",
  ui_story_5046_50460501_50_dialog_content = "O que há de errado, senhor? A queimadura está te machucando?",
  ui_story_5046_50460501_51_dialog_content = "É tudo minha culpa que você se machucou...",
  ui_story_5046_50460501_52_dialog_content = "Estou bem. O pequeno ferimento não vai me incomodar.",
  ui_story_5046_50460501_53_dialog_content = "Já que você acredita que o Sr. Hamell é o próximo alvo de Hati, devo retornar e fazer planos...",
  ui_story_5046_50460501_54_dialog_content = "Estamos ficando sem tempo...",
  ui_story_5046_50460501_55_dialog_content = "Argh!",
  ui_story_5046_50460501_56_dialog_content = "Por favor, pare de se esforçar demais, senhor!",
  ui_story_5046_50460501_57_dialog_content = "Quando nos encontramos pela primeira vez, você investiu contra o fogo para me salvar, apesar de seus ferimentos.",
  ui_story_5046_50460501_58_dialog_content = "E hoje, você me protegeu quando corri imprudentemente para o fogo.",
  ui_story_5046_50460501_59_dialog_content = "É hora de eu fazer algo por você!",
  ui_story_5046_50460501_60_dialog_content = "Minha dama...",
  ui_story_5046_50460501_61_dialog_content = "Por favor, pare de me chamar assim.",
  ui_story_5046_50460501_62_dialog_content = "Não quero continuar sendo uma flor mimada por você, senhor.",
  ui_story_5046_50460501_63_dialog_content = "Quero ser um juiz que leve justiça a Lumopolis e alguém que seja tão confiável quanto o senhor.",
  ui_story_5046_50460501_64_dialog_content = "Sei que ainda tenho um longo caminho a percorrer, mas não irei a lugar nenhum se não der o primeiro passo.",
  ui_story_5046_50460501_65_dialog_content = "Mesmo que seja apenas um pequeno passo, ainda devo dar.",
  ui_story_5046_50460501_66_dialog_content = "Então, por favor, permita-me garantir a segurança do Sr. Hamell!",
  ui_story_5046_50460501_67_dialog_content = "He...",
  ui_story_5046_50460501_68_dialog_content = "Minha dama...",
  ui_story_5046_50460501_69_dialog_content = "Quero dizer, Kristen.",
  ui_story_5046_50460501_70_dialog_content = "É um sentimento comovente e estou profundamente comovido com a determinação.",
  ui_story_5046_50460501_71_dialog_content = "(Espere, por que ele está se inclinando mais perto...?)",
  ui_story_5046_50460501_72_dialog_content = "(Eu posso sentir sua respiração...)",
  ui_story_5046_50460501_73_dialog_content = "(Seu cabelo está fazendo meu rosto coçar...)",
  ui_story_5046_50460501_74_dialog_content = "E também posso sentir plenamente o carinho que você tem por mim...",
  ui_story_5046_50460501_75_dialog_content = "(Carinho? Do que ele está falando?)",
  ui_story_5046_50460501_76_dialog_content = "(Não, não me diga!)",
  ui_story_5046_50460501_77_dialog_content = "Kristen, eu...",
  ui_story_5046_50460501_78_dialog_content = "S-Senhor!",
  ui_story_5046_50460501_79_dialog_content = "Eu deveria estar indo para a casa do Sr. Hamell!",
  ui_story_5046_50460501_80_dialog_content = "Vou me esforçar para cumprir essa missão!",
  ui_story_5046_50460501_81_dialog_content = "Hehehe...",
  ui_story_5046_50460501_82_dialog_content = "Acredito que com sua inteligência e coragem, você enfrentará o desafio com louvor.",
  ui_story_5046_50460501_83_dialog_content = "Eu agradeço, senhor!",
  ui_story_5046_50460501_84_dialog_content = "Não vou decepcioná-lo e completar a missão!",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>Umbraton rural</color>",
  ui_story_5046_50460501_86_dialog_content = "Essa é a árvore de bordo mais alta da floresta.",
  ui_story_5046_50460501_87_dialog_content = "Estamos lá agora?",
  ui_story_5046_50460501_88_dialog_content = "As trilhas são acidentadas na floresta, então cuidado—",
  ui_story_5046_50460501_89_dialog_content = "Ai!",
  ui_story_5046_50460501_90_dialog_content = "- ou você vai tropeçar.",
  ui_story_5046_50460501_91_dialog_content = "Isso dói!",
  ui_story_5046_50460501_92_dialog_content = "Sentar-se.",
  ui_story_5046_50460501_93_dialog_content = "Isso não é sério. Você vai ficar bem.",
  ui_story_5046_50460501_94_dialog_content = "Sente-se, você.",
  ui_story_5046_50460501_95_dialog_content = "(Que intimidante... não consigo lutar contra isso...)",
  ui_story_5046_50460501_96_dialog_content = "Tudo bem, vou sentar um pouco.",
  ui_story_5046_50460501_97_dialog_content = "Enrole as pernas da calça.",
  ui_story_5046_50460501_98_dialog_content = "Pelo que?",
  ui_story_5046_50460501_99_dialog_content = "Vou fazer doer menos.",
  ui_story_5046_50460501_100_dialog_content = "Bem, não está doendo tanto... Nossa, não precisa enrolar pra mim, eu mesmo faço!",
  ui_story_5046_50460501_101_dialog_content = "I-Isto é bom o suficiente?",
  ui_story_5046_50460501_102_dialog_content = "Sim, deveria estar aqui. Isso dói quando eu pressiono?",
  ui_story_5046_50460501_103_dialog_content = "Tudo bem, mas sua mão está quente! Mesmo que seja muito frio na floresta.",
  ui_story_5046_50460501_104_dialog_content = "A temperatura do meu corpo está mais alta do que o normal. Aproxime-se se estiver com frio.",
  ui_story_5046_50460501_105_dialog_content = "(Hati pode parecer inacessível, mas suas orelhas fofas se animam quando ela se agacha.)",
  ui_story_5046_50460501_106_dialog_content = "(E ela é realmente muito legal, me lembrando de ter cuidado ao andar aqui e massagear meu tornozelo torcido...)",
  ui_story_5046_50460501_107_dialog_content = "O que houve?",
  ui_story_5046_50460501_108_dialog_content = "Nada, nada!",
  ui_story_5046_50460501_109_dialog_content = "Ainda temos tempo. Por que não fazemos uma pausa aqui?",
  ui_story_5046_50460501_110_dialog_content = "Tá bom.",
  ui_story_5046_50460501_111_dialog_content = "...",
  ui_story_5046_50460501_112_dialog_content = "...",
  ui_story_5046_50460501_113_dialog_content = "(Isso é estranho. Eu deveria dizer algo...)",
  ui_story_5046_50460501_114_dialog_content = "Você pode me contar sobre sua mãe?",
  ui_story_5046_50460501_115_dialog_content = "Eu não quis dizer nada de mal com isso!",
  ui_story_5046_50460501_116_dialog_content = "Minha mãe me deixou logo depois que eu nasci. Eu nem cheguei a ver como ela era...",
  ui_story_5046_50460501_117_dialog_content = "...",
  ui_story_5046_50460501_118_dialog_content = "Acho que você não quer me contar, tudo bem.",
  ui_story_5046_50460501_119_dialog_content = "...",
  ui_story_5046_50460501_120_dialog_content = "Francamente, entendo o quanto você deseja recuperar essas memórias.",
  ui_story_5046_50460501_121_dialog_content = "...",
  ui_story_5046_50460501_122_dialog_content = "Soroz é quem me criou por todos esses anos.",
  ui_story_5046_50460501_123_dialog_content = "Não é apenas um Colossus, mas meu amigo e professor também.",
  ui_story_5046_50460501_124_dialog_content = "Somos inseparáveis há muitos anos. Isso me ensinaria sobre o mundo lá fora e conversaria quando eu estivesse entediado.",
  ui_story_5046_50460501_125_dialog_content = "Pena que não se lembra de mim agora.",
  ui_story_5046_50460501_126_dialog_content = "Perdeu a memória também?",
  ui_story_5046_50460501_127_dialog_content = "Ele perdeu todas as memórias para salvar minha vida, então estou trabalhando para encontrar uma maneira de restaurá-lo.",
  ui_story_5046_50460501_128_dialog_content = "Grimme estava certo, nós temos algo em comum.",
  ui_story_5046_50460501_129_dialog_content = "E nós dois estamos trabalhando duro para recuperar as memórias.",
  ui_story_5046_50460501_130_dialog_content = "Portanto, entendo como você se sente e espero que possa se lembrar dos acontecimentos com sua mãe.",
  ui_story_5046_50460501_131_dialog_content = "...",
  ui_story_5046_50460501_132_dialog_content = "Sinta-se à vontade para me avisar se houver algo que eu possa ajudar com a memória de Soroz.",
  ui_story_5046_50460501_133_dialog_content = "Antes de ajudar, você precisa limpar seu status de suspeito!",
  ui_story_5046_50460501_134_dialog_content = "Prometa-me que vai confessar depois de pegarmos o pingente, ok?",
  ui_story_5046_50460501_135_dialog_content = "Tsk... Que problemático.",
  ui_story_5046_50460501_136_dialog_content = "Sim, mas você ainda tem que fazer isso!",
  ui_story_5046_50460501_137_dialog_content = "Está bem.",
  ui_story_5046_50460501_138_dialog_content = "Você promete!",
  ui_story_5046_50460501_139_dialog_content = "Graah—!",
  ui_story_5046_50460501_140_dialog_content = "Temos Eclipsites chegando, e muitos deles...",
  ui_story_5046_50460501_141_dialog_content = "Gaaaaaa!!!",
  ui_story_5046_50460501_142_dialog_content = "Cuidado.",
  ui_story_5046_50460501_143_dialog_content = "Vamos, PlayerName, por que você é tão fraco?",
  ui_story_5046_50460501_144_dialog_content = "Os celestitas nunca foram conhecidos por lutar!",
  ui_story_5046_50460501_145_dialog_content = "Impotente.",
  ui_story_5046_50460501_146_dialog_content = "Não olhe para mim. Eclipsites estão vindo à sua esquerda!",
  ui_story_5046_50460501_147_dialog_content = "Graah—!",
  ui_story_5046_50460501_148_dialog_content = "Coma meu machado!",
  ui_story_5046_50460501_149_dialog_content = "Como é isso? Posso não ser capaz de lutar, mas minha capacidade de coordenação tem o selo de aprovação de Carleen!",
  ui_story_5046_50460501_150_dialog_content = "Então se esconda atrás de mim e coordene!",
  ui_story_5046_50460502_1_dialog_content = "Isso é ruim, como pode haver tantos Eclipsites aqui...",
  ui_story_5046_50460502_2_dialog_content = "Suspiro... suspiro...",
  ui_story_5046_50460502_3_dialog_content = "Este não é o lugar nem a hora para eu descer...",
  ui_story_5046_50460502_4_dialog_content = "Graah...",
  ui_story_5046_50460502_5_dialog_content = "Mais Eclipsites estão chegando!",
  ui_story_5046_50460502_6_dialog_content = "Maldições! Devo fazer isso...",
  ui_story_5046_50460502_7_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5046_50460502_8_dialog_content = "Graah—!",
  ui_story_5046_50460502_9_dialog_content = "Uau, os Eclipsites... Eles estão todos queimados!",
  ui_story_5046_50460502_10_dialog_content = "Não sinto mais nenhum Eclipsite por perto.",
  ui_story_5046_50460502_11_dialog_content = "Aff... aff...",
  ui_story_5046_50460502_12_dialog_content = "Ugh!",
  ui_story_5046_50460502_13_dialog_content = "Você usou o poder...",
  ui_story_5046_50460502_14_dialog_content = "Tsk, tsk...",
  ui_story_5046_50460502_15_dialog_content = "Você... Você se transformou naquilo que odiava...",
  ui_story_5046_50460502_16_dialog_content = "Foi assim que... mamãe... nos deixou...",
  ui_story_5046_50460502_17_dialog_content = "Cale-se! Eu digo cale a boca!",
  ui_story_5046_50460502_18_dialog_content = "O que está errado, Hati?!",
  ui_story_5046_50460502_19_dialog_content = "(Hati está rolando no chão em agonia com os olhos fechados.)",
  ui_story_5046_50460502_20_dialog_content = "Eu digo, cale a boca!",
  ui_story_5046_50460502_21_dialog_content = "Mãe... eu não sou uma criança travessa... eu não sou...",
  ui_story_5046_50460502_22_dialog_content = "Mãe? Ela está imersa em memórias passadas?",
  ui_story_5046_50460502_23_dialog_content = "Isso não vai ser bom. Eu tenho que usar minha habilidade psíquica para libertá-la.",
  ui_story_5046_50460502_24_dialog_content = "Desculpe, Hati, mas não pretendo me intrometer em sua mente.",
  ui_story_5046_50460502_25_option_content = "Aumento de Força!",
  ui_story_5046_50460502_26_dialog_content = "(Onde estou?)",
  ui_story_5046_50460502_27_dialog_content = "Mãe, você tem cocklebur em você! Deixe-me tirá-los.",
  ui_story_5046_50460502_28_dialog_content = "Obrigado, Hati.",
  ui_story_5046_50460502_29_dialog_content = "Você é um menino tão bom.",
  ui_story_5046_50460502_30_dialog_content = "Hehe...",
  ui_story_5046_50460502_31_dialog_content = "Não é sempre que você me leva para brincar, mãe.",
  ui_story_5046_50460502_32_dialog_content = "(É um pouco Hati, e sua mãe também.)",
  ui_story_5046_50460502_33_dialog_content = "...",
  ui_story_5046_50460502_34_dialog_content = "Sinto muito, Hati.",
  ui_story_5046_50460502_35_dialog_content = "Por que você está se desculpando, mãe? Você não fez nada de errado.",
  ui_story_5046_50460502_36_dialog_content = "Bem, a culpa é minha.",
  ui_story_5046_50460502_37_dialog_content = "Não, você não fez nada de errado...",
  ui_story_5046_50460502_38_dialog_content = "Você deveria estar brincando lá fora como qualquer outra criança, mas...",
  ui_story_5046_50460502_39_dialog_content = "Estou certo em fazer isso, Fenrir...?",
  ui_story_5046_50460502_40_dialog_content = "Você está chorando por minha causa, mãe?",
  ui_story_5046_50460502_41_dialog_content = "Então não vou mais sair.",
  ui_story_5046_50460502_42_dialog_content = "Está tudo bem, estou bem... Vem, vamos jogar!",
  ui_story_5046_50460502_43_dialog_content = "Vou fechar os olhos, conto até três e venho te encontrar!",
  ui_story_5046_50460502_44_dialog_content = "Beleza!",
  ui_story_5046_50460502_45_dialog_content = "Três...",
  ui_story_5046_50460502_46_dialog_content = "Graah...",
  ui_story_5046_50460502_47_dialog_content = "Algo preto está se aproximando da mamãe...",
  ui_story_5046_50460502_48_dialog_content = "Dois...",
  ui_story_5046_50460502_49_dialog_content = "A coisa preta parece que vai machucá-la...",
  ui_story_5046_50460502_50_dialog_content = "Um...",
  ui_story_5046_50460502_51_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5046_50460502_52_dialog_content = "!!!",
  ui_story_5046_50460502_53_dialog_content = "Hati?!",
  ui_story_5046_50460502_54_dialog_content = "Mãe, esse bicho é muito ruim!",
  ui_story_5046_50460502_55_dialog_content = "Vou queimá-lo em uma bola de fogo!",
  ui_story_5046_50460502_56_dialog_content = "Rá!",
  ui_story_5046_50460502_57_dialog_content = "Por que você - eu não disse para você não usar fogo?!",
  ui_story_5046_50460502_58_dialog_content = "Por que você não ouve?",
  ui_story_5046_50460502_59_dialog_content = "Mas mãe...",
  ui_story_5046_50460502_60_dialog_content = "Vá para casa comigo agora!",
  ui_story_5046_50460502_61_dialog_content = "Boo-hoo... Por que...",
  ui_story_5046_50460502_62_dialog_content = "Mamãe me odeia... quando brinco com fogo...?",
  ui_story_5046_50460502_63_dialog_content = "(mamãe não gosta Hati... Não gosta de fogo...)",
  ui_story_5046_50460502_64_dialog_content = "(Hati é uma criança travessa...)",
  ui_story_5046_50460502_65_dialog_content = "(criança travessa...)",
  ui_story_5046_50460502_66_dialog_content = "(Hati é... uma criança travessa?)",
  ui_story_5046_50460502_67_dialog_content = "(Não, Hati não é uma criança travessa!)",
  ui_story_5046_50460502_68_dialog_content = "(Usar o poder que mamãe não aprovou para salvar entes queridos...)",
  ui_story_5046_50460502_69_dialog_content = "(Isso não significa Hati é uma criança travessa!)",
  ui_story_5046_50460502_70_dialog_content = "(Hati não é uma criança travessa...?)",
  ui_story_5046_50460502_71_dialog_content = "(Sua mãe deve ter tido uma razão não dita para ser má com Hati...)",
  ui_story_5046_50460502_72_dialog_content = "(E o jovem você parecia super legal usando fogo para proteger sua mãe!)",
  ui_story_5046_50460502_73_dialog_content = "(Assim como o legal Hati que usou o fogo para me proteger!)",
  ui_story_5046_50460502_74_dialog_content = "(Hati é um garoto ótimo e incrível!)",
  ui_story_5046_50460502_75_dialog_content = "(Hati é uma criança incrível?)",
  ui_story_5046_50460502_76_dialog_content = "(Isso mesmo, Hati é um garoto incrível! Agora fique calmo e acorde devagar...)",
  ui_story_5046_50460502_77_dialog_content = "...",
  ui_story_5046_50460502_78_dialog_content = "PlayerName?",
  ui_story_5046_50460502_79_dialog_content = "Sou eu. Sentindo-se bem, certo?",
  ui_story_5046_50460502_80_dialog_content = "Sim...",
  ui_story_5046_50460502_81_dialog_content = "Desculpe por causar problemas para você.",
  ui_story_5046_50460502_82_dialog_content = "Não, eu deveria estar me desculpando.",
  ui_story_5046_50460502_83_dialog_content = "Entrei em sua memória sem sua permissão...",
  ui_story_5046_50460502_84_dialog_content = "Espero que você não esteja com raiva de mim por isso!",
  ui_story_5046_50460502_85_dialog_content = "Se não fosse por você...",
  ui_story_5046_50460502_86_dialog_content = "Eu provavelmente teria enlouquecido.",
  ui_story_5046_50460502_87_dialog_content = "Obrigado.",
  ui_story_5046_50460502_88_dialog_content = "Certo, não estou acostumada com você ficando tão recatada de repente.",
  ui_story_5046_50460502_89_dialog_content = "Aham, está quase na hora. Temos que chegar àquela árvore.",
  ui_story_5046_50460502_90_dialog_content = "Se você ainda precisa de mim para recuperar memórias para você depois que tudo isso acabar...",
  ui_story_5046_50460502_91_dialog_content = "Apenas venha me ver no Colossus.",
  ui_story_5046_50460502_92_dialog_content = "Claro.",
  ui_story_5046_50460502_93_dialog_content = "Além disso, lembre-se que você prometeu explicar tudo e se esclarecer...",
  ui_story_5046_50460502_94_dialog_content = "Caso contrário, você receberá uma recompensa antes mesmo de me ver.",
  ui_story_5046_50460502_95_dialog_content = "Eu prometo.",
  ui_story_5046_50460502_96_dialog_content = "Você faz?",
  ui_story_5046_50460502_97_dialog_content = "Isso.",
  ui_story_5046_50460601_1_dialog_content = "(Um esquadrão de guardas de Lumopolis chegou ao orfanato esta manhã, mas o Sr. Hamell não os mandou embora.)",
  ui_story_5046_50460601_2_dialog_content = "(E ele até os conduziu para fora de Umbraton e para esta floresta...)",
  ui_story_5046_50460601_3_dialog_content = "(Agora, tanto o celestita quanto o Hati estão aqui, e os dois lados se chocam.)",
  ui_story_5046_50460601_4_dialog_content = "(Esses guardas não estão lutando no estilo Lumopolis, mas eles usavam uniformes Lumo Guard.)",
  ui_story_5046_50460601_5_dialog_content = "(O que está acontecendo aqui...?)",
  ui_story_5046_50460601_6_dialog_content = "(É inútil detê-los agora, então eu deveria apenas assistir daqui por enquanto.)",
  ui_story_5046_50460601_7_dialog_content = "Huff... huff... Mesmo isso não poderia te matar.",
  ui_story_5046_50460601_8_dialog_content = "Sr Hamell? O que você está dizendo? E o que você está fazendo aqui?",
  ui_story_5046_50460601_9_dialog_content = "Onde está o Sr. Zenas? A mensagem não chegou até ele?",
  ui_story_5046_50460601_10_dialog_content = "Ao invés de esperar que você venha me matar, prefiro um ataque preventivo.",
  ui_story_5046_50460601_11_dialog_content = "Você não matou Andre, Fairmont e Carlotta?",
  ui_story_5046_50460601_12_dialog_content = "Você guarda rancor pelo que aconteceu com você no orfanato e quer vingança contra nós?",
  ui_story_5046_50460601_13_dialog_content = "Você queria nos matar de uma só vez no ensaio, certo?",
  ui_story_5046_50460601_14_dialog_content = "Pena que esse plano falhou.",
  ui_story_5046_50460601_15_dialog_content = "Não tenho ideia de quem são essas pessoas e estava apenas passando pelo ensaio.",
  ui_story_5046_50460601_16_dialog_content = "Pare de se fazer de bobo! Você gostaria de nada mais do que para mim e - Argh!",
  ui_story_5046_50460601_17_dialog_content = "Cuidado!",
  ui_story_5046_50460601_18_dialog_content = "(Sr. Hamell caiu! Hati Mate ele?)",
  ui_story_5046_50460601_19_dialog_content = "Aguente firme, Sr. Hamell!",
  ui_story_5046_50460601_20_dialog_content = "Ele está morto.",
  ui_story_5046_50460601_21_dialog_content = "Hati Kelp, você é um suspeito de assassinato. Eu exijo que você venha comigo para Umbraton para uma investigação mais aprofundada!",
  ui_story_5046_50460601_22_dialog_content = "Perder Kristen? O que você está fazendo aqui?",
  ui_story_5046_50460601_23_dialog_content = "Eu não o matei.",
  ui_story_5046_50460601_24_dialog_content = "Claro, você diria isso.",
  ui_story_5046_50460601_25_dialog_content = "Posso atestar a inocência de Hati. O Sr. Hamell caiu intocado.",
  ui_story_5046_50460601_26_dialog_content = "Por que você está abrigando um assassino, PlayerName?",
  ui_story_5046_50460601_27_dialog_content = "Ela ainda está segurando uma arma letal em sua mão...",
  ui_story_5046_50460601_28_dialog_content = "Eu estou dizendo a verdade!",
  ui_story_5046_50460601_29_dialog_content = "Já que querem se defender, por que não vêm comigo ao Tribunal de Justiça?",
  ui_story_5046_50460601_30_dialog_content = "Embora eu seja apenas um juiz estagiário, devo garantir que a justiça seja feita e que nenhum crime fique impune.",
  ui_story_5046_50460601_31_dialog_content = "De jeito nenhum, eu não posso ir com você ainda.",
  ui_story_5046_50460601_32_dialog_content = "Resistir à prisão só vai piorar as coisas.",
  ui_story_5046_50460601_33_dialog_content = "Sim, tanto faz.",
  ui_story_5046_50460601_34_dialog_content = "Por favor, acalmem-se, vocês dois!",
  ui_story_5046_50460601_35_dialog_content = "Kristen! Você está bem?",
  ui_story_5046_50460601_36_dialog_content = "Você está atrasado, homem mascarado.",
  ui_story_5046_50460601_37_dialog_content = "Este é o Sr. Hamell?",
  ui_story_5046_50460601_38_dialog_content = "Hati? Você matou o Sr. Hamell, não foi? Prenda-a de uma vez, Kristen.",
  ui_story_5046_50460601_39_dialog_content = "Espere um minuto! Hati não fez nada disso!",
  ui_story_5046_50460601_40_dialog_content = "Queres lutar? Não é problema comigo!",
  ui_story_5046_50460601_41_dialog_content = "É perigoso lá, PlayerName, venha aqui!",
  ui_story_5046_50460601_42_dialog_content = "Toma essa!",
  ui_story_5046_50460601_43_dialog_content = "Você é devagar demais.",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5046_50460601_45_dialog_content = "Minha máscara...",
  ui_story_5046_50460601_46_dialog_content = "O rosto...!",
  ui_story_5046_50460601_47_dialog_content = "Quem é ele? Quem é ele?!",
  ui_story_5046_50460601_48_dialog_content = "Qual o problema, Hati?",
  ui_story_5046_50460601_49_dialog_content = "Eu... ah... ah...!",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>\"Aquele dia-\"</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>\"Eu vi esse rosto.\"</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>\"Aquele dia-\"</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>\"O que aconteceu... comigo... mãe?\"</color>",
  ui_story_5046_50460601_54_dialog_content = "Aghhhh!",
  ui_story_5046_50460601_55_dialog_content = "Hati? Hati?!",
  ui_story_5046_50460601_56_dialog_content = "Algo está errado com ela, senhor.",
  ui_story_5046_50460601_57_dialog_content = "Ahhhhhh!",
  ui_story_5046_50460601_58_dialog_content = "Hati! Hati! Você pode me ouvir?",
  ui_story_5046_50460601_59_dialog_content = "Sair dessa!",
  ui_story_5046_50460601_60_dialog_content = "Argh!",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>Chiar-</color>",
  ui_story_5046_50460601_62_dialog_content = "O visual dela acabou de mudar! E ela está pegando fogo?!",
  ui_story_5046_50460601_63_dialog_content = "Cuidadoso! Afaste-se, Kristen!",
  ui_story_5046_50460601_64_dialog_content = "Awooo!!!",
  ui_story_5046_50460601_65_dialog_content = "Hati!!!",
  ui_story_5046_50460601_66_dialog_content = "(A aparência dela agora se assemelha ao demônio interior que vi em sua memória...)",
  ui_story_5046_50460601_67_dialog_content = "(Isso a dominou? De jeito nenhum, eu tenho que tirá-la disso!)",
  ui_story_5046_50460601_68_dialog_content = "Venha aqui, PlayerName! Hati é uma ameaça perigosa agora!",
  ui_story_5046_50460601_69_dialog_content = "Está tudo bem, Hati não vai me machucar! Ela precisa de mim agora!",
  ui_story_5046_50460601_70_dialog_content = "Você deve se acalmar, Hati!",
  ui_story_5046_50460601_71_dialog_content = "Awuuu!",
  ui_story_5046_50460601_72_dialog_content = "Pare de desperdiçar seu tempo, ela não está ouvindo!",
  ui_story_5046_50460601_73_dialog_content = "Venha aqui rapidamente, PlayerName!",
  ui_story_5046_50460601_74_dialog_content = "PlayerName...",
  ui_story_5046_50460601_75_dialog_content = "Hati está chamando meu nome!",
  ui_story_5046_50460601_76_dialog_content = "Não, eu não posso simplesmente deixá-la sozinha!",
  ui_story_5046_50460601_77_dialog_content = "(Existe uma maneira de ela me ouvir...)",
  ui_story_5046_50460601_78_dialog_content = "(Entendi, posso fazer isso...)",
  ui_story_5046_50460601_79_option_content = "Aumento de Força!",
  ui_story_5046_50460601_80_dialog_content = "(Acalmar, Hati!)",
  ui_story_5046_50460601_81_dialog_content = "(PlayerName? Eu... eu simplesmente não consegui me controlar... quando vi o rosto daquele homem...)",
  ui_story_5046_50460601_82_dialog_content = "(Minha cabeça começou a doer tanto. Urgh-)",
  ui_story_5046_50460601_83_dialog_content = "(O que eu vou fazer...?)",
  ui_story_5046_50460601_84_dialog_content = "(De qualquer forma, temos que sair daqui e encontrar um lugar tranquilo para você relaxar.)",
  ui_story_5046_50460601_85_dialog_content = "(Nós vamos juntos...?)",
  ui_story_5046_50460601_86_dialog_content = "(Junto!)",
  ui_story_5046_50460601_87_dialog_content = "Não os deixe fugir! Eca!",
  ui_story_5046_50460601_88_dialog_content = "Fique parado, senhor, você está ferido!",
  ui_story_5046_50460601_89_dialog_content = "Onde está o celestita?",
  ui_story_5046_50460601_90_dialog_content = "Hati levou ele com ela...",
  ui_story_5046_50460601_91_dialog_content = "Ratos, ela fugiu de novo!",
  ui_story_5046_50460601_92_dialog_content = "Cadê minha máscara?",
  ui_story_5046_50460601_93_dialog_content = "Eu vou buscá-lo para você, apenas fique parado!",
  ui_story_5046_50460601_94_dialog_content = "(A ferida em seu rosto...)",
  ui_story_5046_50460601_95_dialog_content = "Oh não, fogo!",
  ui_story_5046_50460601_96_dialog_content = "A jovem senhorita ainda está lá dentro!",
  ui_story_5046_50460601_97_dialog_content = "Alguém ainda está aí?",
  ui_story_5046_50460601_98_dialog_content = "Por favor, senhor, eu imploro que salve a senhorita Kristen!",
  ui_story_5046_50460601_99_dialog_content = "*Cof Cof*",
  ui_story_5046_50460601_100_dialog_content = "Mãe... Pai... Cadê você...",
  ui_story_5046_50460601_101_dialog_content = "Perde!",
  ui_story_5046_50460601_102_dialog_content = "Quem... Quem é esse...",
  ui_story_5046_50460601_103_dialog_content = "Finalmente te encontrei. Não tenha medo, eu vou te tirar dessa.",
  ui_story_5046_50460601_104_dialog_content = "Você está bem, minha senhora?",
  ui_story_5046_50460601_105_dialog_content = "Estou bem, obrigada... Ah!",
  ui_story_5046_50460601_106_dialog_content = "Oh não! Seu rosto está gravemente ferido! Deve ser tratado imediatamente!",
  ui_story_5046_50460601_107_dialog_content = "Meu? Lamento assustar a jovem.",
  ui_story_5046_50460601_108_dialog_content = "Me desculpe. Você me salvou só para eu...",
  ui_story_5046_50460601_109_dialog_content = "Tudo bem. Estou feliz que você esteja bem.",
  ui_story_5046_50460601_110_dialog_content = "May Eu pergunto o seu nome...?",
  ui_story_5046_50460601_111_dialog_content = "Zenas.",
  ui_story_5046_50460601_112_dialog_content = "A partir de hoje, sou seu professor particular, minha senhora.",
  ui_story_5046_50460601_113_dialog_content = "Isso é ótimo, senhor!",
  ui_story_5046_50460601_114_dialog_content = "Sou grato por você aceitar um nobre humilde como eu, além de me recomendar a seu pai.",
  ui_story_5046_50460601_115_dialog_content = "Você é um nobre, senhor?",
  ui_story_5046_50460601_116_dialog_content = "Sim. Veja, este é o brasão da minha família.",
  ui_story_5046_50460601_117_dialog_content = "Que padrão único.",
  ui_story_5046_50460601_118_dialog_content = "A casa declinou e não vale mais a pena mencionar.",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>\"A partir de então, ele ficou e me ensinou.\"</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>\"Até que ele renunciou e foi servir a Lumópolis em caráter oficial.\"</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>\"Depois que me formei Dawn Academy, entrei para o Lumo Hall of Justice e continuei seguindo ele.\"</color>",
  ui_story_5046_50460601_122_dialog_content = "Sua máscara, senhor.",
  ui_story_5046_50460601_123_dialog_content = "Ufa...",
  ui_story_5046_50460601_124_dialog_content = "Hati matou o Sr. Hamell e sequestrou o Caelestite novamente.",
  ui_story_5046_50460601_125_dialog_content = "Devemos enviar guardas em perseguição e expandir nossa investigação.",
  ui_story_5046_50460601_126_dialog_content = "Sim, senhor!",
  ui_story_5046_50460601_127_dialog_content = "É aqui que você sai do caso, Kristen.",
  ui_story_5046_50460601_128_dialog_content = "O quê?",
  ui_story_5046_50460601_129_dialog_content = "Considerando que o caso só vai piorar, não quero colocar você em mais perigo.",
  ui_story_5046_50460601_130_dialog_content = "Além disso, com base no incidente com Hamell, acho que você ainda não tem experiência para lidar com o suspeito.",
  ui_story_5046_50460601_131_dialog_content = "Mas ninguém está mais envolvido nesses casos do que eu, exceto você, senhor. Por favor, permita-me continuar a ajudá-lo!",
  ui_story_5046_50460601_132_dialog_content = "Não diga mais. Eu mesmo cuido deles.",
  ui_story_5046_50460601_133_dialog_content = "Basta compilar todas as descobertas até agora em um arquivo e entregá-lo ao Tribunal de Justiça.",
  ui_story_5046_50460601_134_dialog_content = "Mas…",
  ui_story_5046_50460601_135_dialog_content = "Suficiente! Você pode ser minha jovem, mas eu sou seu superior.",
  ui_story_5046_50460601_136_dialog_content = "Por favor, siga o meu pedido!",
  ui_story_5046_50460601_137_dialog_content = "Sim...",
  ui_story_5046_50460601_138_dialog_content = "Provavelmente fui muito duro com minhas palavras, mas foi por preocupação com sua segurança.",
  ui_story_5046_50460601_139_dialog_content = "Você deveria voltar agora.",
  ui_story_5046_50460601_140_dialog_content = "Minha primeira vez mandou seguir o suspeito e estraguei tudo.",
  ui_story_5046_50460601_141_dialog_content = "Mesmo que ele não me deixe, vou chegar ao fundo disso.",
  ui_story_5046_50460601_142_dialog_content = "Sem falar que fiquei com minhas dúvidas sobre todos esses casos...",
  ui_story_5046_50460601_143_dialog_content = "Se Hati pretendia atear fogo, por que ela salvou PlayerName e a menininha?",
  ui_story_5046_50460601_144_dialog_content = "Além disso, por que PlayerName falar por Hati e ajudá-la a escapar quando ele é o refém?",
  ui_story_5046_50460601_145_dialog_content = "Antes de morrer, Hamell mencionou que Hati tinha outro alvo ao lado dele.",
  ui_story_5046_50460601_146_dialog_content = "Descubra quem é e eu vou encontrar Hati.",
  ui_story_5046_50460601_147_dialog_content = "Senhor Zenas, desta vez vou provar que não sou mais uma flor mimada!",
  ui_story_5046_50460601_148_dialog_content = "Com certeza serei uma ajuda inestimável por meio de minhas próprias habilidades!",
  ui_story_5046_50460701_1_dialog_content = "(Ugh, cobertor molhado é o pior.)",
  ui_story_5046_50460701_2_dialog_content = "(O telhado está vazando de novo? Nunca foi o caso da casa antiga.)",
  ui_story_5046_50460701_3_dialog_content = "Mãe mãe?",
  ui_story_5046_50460701_4_dialog_content = "(a mamãe está dormindo?)",
  ui_story_5046_50460701_5_dialog_content = "(Ela tem saído muito ultimamente e tinha que cozinhar e fazer tarefas domésticas quando chegava em casa, então deve estar muito cansada.)",
  ui_story_5046_50460701_6_dialog_content = "(Eu sou uma menina grande agora e não posso causar problemas para a mamãe!)",
  ui_story_5046_50460701_7_dialog_content = "(tenho que secar o cobertor sozinho!)",
  ui_story_5046_50460701_8_dialog_content = "(Ela vai ficar muito feliz quando me ver fazendo as tarefas depois que acordar!)",
  ui_story_5046_50460701_9_dialog_content = "(Ela vai me chamar de garoto legal!)",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>Tu-tum... Tu-tum...</color>",
  ui_story_5046_50460701_11_dialog_content = "(Ufa, isso deve servir. Por quanto tempo mamãe costuma pendurar o cobertor?)",
  ui_story_5046_50460701_12_dialog_content = "(Se ao menos estiver seco antes da mamãe acordar!)",
  ui_story_5046_50460701_13_dialog_content = "Seca, cobertorzinho!",
  ui_story_5046_50460701_14_dialog_content = "Vaquinha, vaquinha!",
  ui_story_5046_50460701_15_dialog_content = "Seque agora!",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>Chiar-</color>",
  ui_story_5046_50460701_17_dialog_content = "Nossa!",
  ui_story_5046_50460701_18_dialog_content = "De onde veio o fogo?!",
  ui_story_5046_50460701_19_dialog_content = "Mamãe vai ficar brava se ver isso!",
  ui_story_5046_50460701_20_dialog_content = "Tenho que apagar o fogo!",
  ui_story_5046_50460701_21_dialog_content = "Hati? O que você está fazendo?!",
  ui_story_5046_50460701_22_dialog_content = "Boo-hoo... Mãe!",
  ui_story_5046_50460701_23_dialog_content = "(Ela parecia muito assustada... Tenho que me desculpar agora!)",
  ui_story_5046_50460701_24_dialog_content = "Desculpa, só queria secar o cobertor...",
  ui_story_5046_50460701_25_dialog_content = "Eu-eu não queria incendiá-lo... apenas...",
  ui_story_5046_50460701_26_dialog_content = "Está ferida?",
  ui_story_5046_50460701_27_dialog_content = "Não... não fiz de propósito, mãe...",
  ui_story_5046_50460701_28_dialog_content = "E eu não queria fazer nada que você não quisesse que eu fizesse...",
  ui_story_5046_50460701_29_dialog_content = "Ok, lembre-se de nunca mais usar seu poder!",
  ui_story_5046_50460701_30_dialog_content = "Você me ouve!?",
  ui_story_5046_50460701_31_dialog_content = "(Mamãe é tão feroz...)",
  ui_story_5046_50460701_32_dialog_content = "Mas eu só estava... não fiz de propósito...",
  ui_story_5046_50460701_33_dialog_content = "Wahhhh—!",
  ui_story_5046_50460701_34_dialog_content = "Você ainda não pode controlar o poder agora...",
  ui_story_5046_50460701_35_dialog_content = "E é muito poderoso, o suficiente para te machucar se você for descuidado...",
  ui_story_5046_50460701_36_dialog_content = "Há também pessoas que gostariam do poder e isso pode te machucar também...",
  ui_story_5046_50460701_37_dialog_content = "Portanto, nunca mais use-o, você ouve, Hati?",
  ui_story_5046_50460701_38_dialog_content = "Boo-hoo... Entendi...",
  ui_story_5046_50460701_39_dialog_content = "(Mãe...)",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>\"Você tem tanto medo do meu poder, mãe?\"</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>\"Você tem tanto medo de mim, mãe?\"</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>\"Mas eu te amo mais, mãe!\"</color>",
  ui_story_5046_50460701_43_dialog_content = "Aghhhh!",
  ui_story_5046_50460701_44_dialog_content = "(mamãe não quer Hati não mais...)",
  ui_story_5046_50460701_45_dialog_content = "(Porque Hati não a ouvi...)",
  ui_story_5046_50460701_46_dialog_content = "Eu... Ugh... Mãe... Aghhh!",
  ui_story_5046_50460701_47_dialog_content = "Acorda, Hati!",
  ui_story_5046_50460701_48_dialog_content = "(Ela parece estar presa em sua memória.)",
  ui_story_5046_50460701_49_dialog_content = "(Eu posso sentir seu demônio interior sussurrando incansavelmente em seu ouvido...)",
  ui_story_5046_50460701_50_dialog_content = "Se Hati não pode enfrentar seu demônio interior de frente, ela permanecerá presa em suas memórias para sempre...",
  ui_story_5046_50460701_51_dialog_content = "Deixá-la à deriva inconscientemente no passado não é uma opção.",
  ui_story_5046_50460701_52_dialog_content = "Eu tenho que ajudá-la!",
  ui_story_5046_50460701_53_option_content = "Aumento de Força!",
  ui_story_5046_50460701_54_dialog_content = "(Esta deve ser a casa de Hati.)",
  ui_story_5046_50460701_55_dialog_content = "Hati! O que você está fazendo!?",
  ui_story_5046_50460701_56_dialog_content = "M-Mãe?",
  ui_story_5046_50460701_57_dialog_content = "Responda-me - o que você está fazendo!?",
  ui_story_5046_50460701_58_dialog_content = "Só queria ver o que as crianças lá fora estão brincando.",
  ui_story_5046_50460701_59_dialog_content = "Feche a janela! Agora mesmo!",
  ui_story_5046_50460701_60_dialog_content = "Mas eu quero sair e brincar também.",
  ui_story_5046_50460701_61_dialog_content = "Quantas vezes eu te disse? Você precisa que eu repita?",
  ui_story_5046_50460701_62_dialog_content = "Soluço...",
  ui_story_5046_50460701_63_dialog_content = "Por que você não me deixa sair para brincar!?",
  ui_story_5046_50460701_64_dialog_content = "Você sempre diz que é para minha própria proteção!",
  ui_story_5046_50460701_65_dialog_content = "Mas você nunca me diz por que isso acontece!",
  ui_story_5046_50460701_66_dialog_content = "...",
  ui_story_5046_50460701_67_dialog_content = "Este novo lugar para o qual nos mudamos é tão degradado e frio! Aqui é horrível!",
  ui_story_5046_50460701_68_dialog_content = "Você não tem aqueles livros ilustrados? Vá e leia sozinho.",
  ui_story_5046_50460701_69_dialog_content = "Mas já li todos esses livros tantas vezes!",
  ui_story_5046_50460701_70_dialog_content = "As crianças desses livros podem brincar juntas e visitar umas às outras...",
  ui_story_5046_50460701_71_dialog_content = "Você usou aqueles livros ilustrados para me ensinar a falar com as pessoas, comprar coisas e dizer obrigado...",
  ui_story_5046_50460701_72_dialog_content = "...",
  ui_story_5046_50460701_73_dialog_content = "Mas eu não tive a chance de usar nada disso!",
  ui_story_5046_50460701_74_dialog_content = "Porque você não me deixa sair!",
  ui_story_5046_50460701_75_dialog_content = "Eu te ensinei todas essas coisas porque...",
  ui_story_5046_50460701_76_dialog_content = "Espero que um dia você consiga se cuidar, quando eu não estiver mais por perto.",
  ui_story_5046_50460701_77_dialog_content = "Por que você não estaria mais por perto?",
  ui_story_5046_50460701_78_dialog_content = "...",
  ui_story_5046_50460701_79_dialog_content = "Por que você parece tão triste, mãe?",
  ui_story_5046_50460701_80_dialog_content = "Alguém foi mau com você?",
  ui_story_5046_50460701_81_dialog_content = "Já estou toda crescida!",
  ui_story_5046_50460701_82_dialog_content = "Se alguém estiver intimidando você, vou bater em todos até que fujam!",
  ui_story_5046_50460701_83_dialog_content = "E se não conseguir acertar todos, vou queimá-los!",
  ui_story_5046_50460701_84_dialog_content = "!!!",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>Tapa!</color>",
  ui_story_5046_50460701_86_dialog_content = "M... mãe?",
  ui_story_5046_50460701_87_dialog_content = "Eu não disse que você não pode fazer isso!?",
  ui_story_5046_50460701_88_dialog_content = "Mãe... você me bateu...",
  ui_story_5046_50460701_89_dialog_content = "Diga-me! Por que não posso!?",
  ui_story_5046_50460701_90_dialog_content = "Porque porque porque!?",
  ui_story_5046_50460701_91_dialog_content = "(Diga-me... Por que não posso...)",
  ui_story_5046_50460701_92_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5046_50460701_93_dialog_content = "?!",
  ui_story_5046_50460701_94_dialog_content = "Uau!",
  ui_story_5046_50460701_95_dialog_content = "Hati, você...!",
  ui_story_5046_50460701_96_dialog_content = "M-Mãe? Meu corpo... está em chamas...",
  ui_story_5046_50460701_97_dialog_content = "Mamãe tem um pingente igual ao meu.",
  ui_story_5046_50460701_98_dialog_content = "Para que serve este pingente?",
  ui_story_5046_50460701_99_dialog_content = "Este pingente é muito importante.",
  ui_story_5046_50460701_100_dialog_content = "Portanto, cuide bem dele.",
  ui_story_5046_50460701_101_dialog_content = "Oh!",
  ui_story_5046_50460701_102_dialog_content = "Mas por que esse pingente é tão importante?",
  ui_story_5046_50460701_103_dialog_content = "... O pingente... importante...",
  ui_story_5046_50460701_104_dialog_content = "... pingente... em...",
  ui_story_5046_50460701_105_dialog_content = "(Esta parte de sua memória é tão vaga...)",
  ui_story_5046_50460701_106_dialog_content = "Mae o que voce esta fazendo? Você parece estressado.",
  ui_story_5046_50460701_107_dialog_content = "Hoje é meu aniversário! Eu quero comer bolo de morango!",
  ui_story_5046_50460701_108_dialog_content = "... Hati... escute-me.",
  ui_story_5046_50460701_109_dialog_content = "É tarde demais... É tarde demais para tal conversa. Não há tempo.",
  ui_story_5046_50460701_110_dialog_content = "Pegue este pingente, guarde-o e nunca o perca!",
  ui_story_5046_50460701_111_dialog_content = "Mãe, o que você está dizendo? Eu não entendo.",
  ui_story_5046_50460701_112_dialog_content = "Uma pessoa má... Uma pessoa muito má está vindo atrás de você.",
  ui_story_5046_50460701_113_dialog_content = "Uma pessoa má? Quem?",
  ui_story_5046_50460701_114_dialog_content = "Mãe, quem é essa pessoa má?",
  ui_story_5046_50460701_115_dialog_content = "Mãe, o que você vai fazer? Mãe?",
  ui_story_5046_50460701_116_dialog_content = "Ah—!",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>\"Mãe, quem é essa pessoa má?\"</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>\"Por que a pessoa má veio e fez isso conosco...?\"</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>\"A mamãe acha... que eu sou uma pessoa ruim?\"</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>\"É por isso que ela me incendiou...?\"</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>\"Estou certo, mãe?\"</color>",
  ui_story_5046_50460701_122_dialog_content = "(Finalmente entendi... Hati...)",
  ui_story_5046_50460701_123_dialog_content = "(A pessoa ruim de quem mamãe estava falando... É você...)",
  ui_story_5046_50460701_124_dialog_content = "(Eu odeio esse poder... Esse poder... ele nos engole por inteiro...)",
  ui_story_5046_50460701_125_dialog_content = "Nós...?",
  ui_story_5046_50460701_126_dialog_content = "Hati! Hati!",
  ui_story_5046_50460701_127_dialog_content = "Quem é aquele...?",
  ui_story_5046_50460701_128_dialog_content = "Sou eu! PlayerName!",
  ui_story_5046_50460701_129_dialog_content = "PlayerName? Você quer... me abandonar também?",
  ui_story_5046_50460701_130_dialog_content = "(PlayerName... Seu amado PlayerName...)",
  ui_story_5046_50460701_131_dialog_content = "(Ele vai deixar você para trás também...)",
  ui_story_5046_50460701_132_dialog_content = "(Quem gostaria de alguém que está sempre colocando fogo em tudo...? Alguém que não consegue controlar suas próprias chamas...)",
  ui_story_5046_50460701_133_dialog_content = "(Alguém que sempre deixou sua mãe com raiva... Até que ela finalmente a abandonou... Hati...)",
  ui_story_5046_50460701_134_dialog_content = "Mamãe não me ama... ninguém vai...",
  ui_story_5046_50460701_135_dialog_content = "Não é desse jeito!",
  ui_story_5046_50460701_136_dialog_content = "Toda vez que você usa seu poder, é para pessoas importantes para você!",
  ui_story_5046_50460701_137_dialog_content = "Para impedir que os Eclipsitas machuquem sua mãe... Secando sua colcha você mesma, para que sua mãe possa descansar mais...",
  ui_story_5046_50460701_138_dialog_content = "Salvando-me de uma horda de Eclipsites quando eu estava impotente para lutar contra eles...",
  ui_story_5046_50460701_139_dialog_content = "Usando seu poder proibido para o bem daqueles de quem você gosta...",
  ui_story_5046_50460701_140_dialog_content = "Você não pode ver, Hati? Você é uma garota muito gentil e atenciosa!",
  ui_story_5046_50460701_141_dialog_content = "É isso que eu gosto em você!",
  ui_story_5046_50460701_142_dialog_content = "E eu sei que sua mãe deve sentir o mesmo!",
  ui_story_5046_50460701_143_dialog_content = "Como sua mãe poderia não amar uma criança tão bondosa e compassiva quanto você?",
  ui_story_5046_50460701_144_dialog_content = "Mamãe... me ama?",
  ui_story_5046_50460701_145_dialog_content = "(Ele está mentindo para você...)",
  ui_story_5046_50460701_146_dialog_content = "Tudo o que eu disse é verdade!",
  ui_story_5046_50460701_147_dialog_content = "Você é o mentiroso! Tudo o que você fez foi rasgar Hati abaixo! Você é a pessoa má!",
  ui_story_5046_50460701_148_dialog_content = "Hati, vamos vencer essa pessoa má juntos!",
  ui_story_5046_50460702_1_dialog_content = "Eu venci?",
  ui_story_5046_50460702_2_dialog_content = "(Você ganhou...?)",
  ui_story_5046_50460702_3_dialog_content = "(Não... Você ainda está aqui... Eu ainda estou aqui...)",
  ui_story_5046_50460702_4_dialog_content = "(Você ainda não consegue... verdadeiramente... se aceitar...)",
  ui_story_5046_50460702_5_dialog_content = "O que você está?",
  ui_story_5046_50460702_6_dialog_content = "(Nós nos encontraremos novamente...)",
  ui_story_5046_50460702_7_dialog_content = "Hati!",
  ui_story_5046_50460702_8_dialog_content = "Urgh... huff...",
  ui_story_5046_50460702_9_dialog_content = "Hum? PlayerName...?",
  ui_story_5046_50460702_10_dialog_content = "Brilhante, você finalmente acordou.",
  ui_story_5046_50460702_11_dialog_content = "...",
  ui_story_5046_50460702_12_dialog_content = "Obrigado. Você acabou de me salvar de novo.",
  ui_story_5046_50460702_13_dialog_content = "Você não precisa me agradecer. Você me salvou dos Eclipsites agora há pouco!",
  ui_story_5046_50460702_14_dialog_content = "...",
  ui_story_5046_50460702_15_dialog_content = "Quero recuperar meu pingente daquele homem mascarado porque era da minha mãe.",
  ui_story_5046_50460702_16_dialog_content = "Desde criança sempre fui diferente de todo mundo. Eu só podia observá-los de longe pela janela e nunca tinha permissão para sair.",
  ui_story_5046_50460702_17_dialog_content = "No meu mundo, só havia minha mãe.",
  ui_story_5046_50460702_18_dialog_content = "Ela brincava comigo, me ensinava a ler, lia histórias para mim... Minha mãe era tudo para mim.",
  ui_story_5046_50460702_19_dialog_content = "Eu a amava tanto, mas minha mãe... Talvez ela não me amasse tanto quanto eu a amava.",
  ui_story_5046_50460702_20_dialog_content = "Como você pode dizer aquilo...?",
  ui_story_5046_50460702_21_dialog_content = "Tanto quanto me lembro, estávamos sempre em movimento e nunca ficávamos no mesmo lugar por muito tempo.",
  ui_story_5046_50460702_22_dialog_content = "Minha mãe sempre me olhava com uma pitada de medo nos olhos e nunca me deixava sair.",
  ui_story_5046_50460702_23_dialog_content = "Nossa última casa foi a que ficamos mais tempo. Foi também o lugar onde minha infância chegou ao fim...",
  ui_story_5046_50460702_24_dialog_content = "Hati...",
  ui_story_5046_50460702_25_dialog_content = "Eu sempre tento fugir, para não ter que me lembrar daquele dia. Mas como posso esquecer?",
  ui_story_5046_50460702_26_dialog_content = "26 de agosto. Aquele dia... era meu aniversário.",
  ui_story_5046_50460702_27_dialog_content = "?!",
  ui_story_5046_50460702_28_dialog_content = "Hati...",
  ui_story_5046_50460702_29_dialog_content = "Embora minha mãe pudesse ser rigorosa às vezes, ela era muito boa para mim.",
  ui_story_5046_50460702_30_dialog_content = "Ela sempre se lembrava do meu aniversário e preparava tudo com um dia de antecedência. Ela até fez um bolo de creme de morango comigo...",
  ui_story_5046_50460702_31_dialog_content = "Naquele dia, mamãe acordou cedo como sempre, mas parecia estar com um humor estranho.",
  ui_story_5046_50460702_32_dialog_content = "Ela simplesmente me desejou um feliz aniversário e então começou a se ocupar com a casa como se estivesse preparando algo.",
  ui_story_5046_50460702_33_dialog_content = "Fiquei perguntando se podia comer o bolo, mas minha mãe não atendia.",
  ui_story_5046_50460702_34_dialog_content = "Então ela me jogou na lareira. Ela tentou me queimar vivo.",
  ui_story_5046_50460702_35_dialog_content = "Por que ela faria isso!?",
  ui_story_5046_50460702_36_dialog_content = "Não consigo me lembrar direito do que aconteceu depois que ela me jogou no fogo. Quando acordei, estava no orfanato.",
  ui_story_5046_50460702_37_dialog_content = "Essa foi a primeira vez que saí com tantas crianças...",
  ui_story_5046_50460702_38_dialog_content = "Sempre quis sair e brincar com outras crianças, mas nunca imaginei que fosse assim.",
  ui_story_5046_50460702_39_dialog_content = "Aprendi a me dar bem com as outras crianças e adultos do orfanato, mas eles não eram muito amigáveis.",
  ui_story_5046_50460702_40_dialog_content = "As crianças viviam brigando umas com as outras, e os adultos eram muito malvados conosco.",
  ui_story_5046_50460702_41_dialog_content = "Era horrível lá, e eu só queria reclamar com minha mãe, mas não sabia onde ela estava.",
  ui_story_5046_50460702_42_dialog_content = "Foi quando percebi... que ela havia me abandonado.",
  ui_story_5046_50460702_43_dialog_content = "Uma noite, as pessoas do orfanato tentaram fazer algo comigo enquanto eu dormia. Tentei me libertar com todas as minhas forças e alguém cortou minha orelha.",
  ui_story_5046_50460702_44_dialog_content = "Um pedaço da minha orelha caiu, assim. Eu nunca tinha sentido tanta dor antes.",
  ui_story_5046_50460702_45_dialog_content = "Eu não conseguia controlar minhas emoções - deixei escapar minha raiva e queimei todo o orfanato.",
  ui_story_5046_50460702_46_dialog_content = "Como você sabe, fui enviado ao Shadowlord depois disso e ele me liberou há apenas dois meses.",
  ui_story_5046_50460702_47_dialog_content = "Hati...",
  ui_story_5046_50460702_48_dialog_content = "Não existe mãe que não ame seu filho.",
  ui_story_5046_50460702_49_dialog_content = "Tenho certeza que ela quer que você viva uma vida boa, não importa o que aconteça.",
  ui_story_5046_50460702_50_dialog_content = "Você não precisa tentar me fazer sentir melhor, PlayerName.",
  ui_story_5046_50460702_51_dialog_content = "Se minha mãe me amasse, por que ela teria me jogado naquela lareira?",
  ui_story_5046_50460702_52_dialog_content = "Eu sei que não é isso que você realmente pensa no fundo do seu coração, certo, Hati?",
  ui_story_5046_50460702_53_dialog_content = "Caso contrário, por que você se esforçaria tanto para encontrar essa memória perdida?",
  ui_story_5046_50460702_54_dialog_content = "Você deve acreditar que sua mãe ainda te ama, em algum lugar do seu coração.",
  ui_story_5046_50460702_55_dialog_content = "...",
  ui_story_5046_50460702_56_dialog_content = "... Hum.",
  ui_story_5046_50460702_57_dialog_content = "Quando perdi o controle de mim mesmo agora, por que você não saiu com os outros em meio a todo o caos?",
  ui_story_5046_50460702_58_dialog_content = "Porque... Achei que você poderia precisar da minha ajuda.",
  ui_story_5046_50460702_59_dialog_content = "Além de Grimme, ninguém se esforçaria tanto para me ajudar.",
  ui_story_5046_50460702_60_dialog_content = "É justo que os amigos se apoiem.",
  ui_story_5046_50460702_61_dialog_content = "Amigos? Eu não tenho nenhum amigo.",
  ui_story_5046_50460702_62_dialog_content = "De agora em diante, você pode me chamar de seu amigo.",
  ui_story_5046_50460702_63_dialog_content = "Você tem procurado por suas memórias por dois meses inteiros desde que deixou o Shadowlord.",
  ui_story_5046_50460702_64_dialog_content = "Mas ainda existe um mundo enorme lá fora, esperando que você o explore.",
  ui_story_5046_50460702_65_dialog_content = "Quando recuperar sua memória, fique à vontade para passar um tempo comigo no Colossus!",
  ui_story_5046_50460702_66_dialog_content = "Podemos viajar pelo mundo e compensar o tempo que você não tinha permissão para sair no passado!",
  ui_story_5046_50460702_67_dialog_content = "...",
  ui_story_5046_50460702_68_dialog_content = "Então, o que você acha?",
  ui_story_5046_50460702_69_dialog_content = "...",
  ui_story_5046_50460702_70_dialog_content = "Claro.",
  ui_story_5046_50460801_1_dialog_content = "(As últimas palavras do Sr. Hamell e o único sobrevivente que ele mencionou - tudo está relacionado ao orfanato.)",
  ui_story_5046_50460801_2_dialog_content = "(Não há outras pistas disponíveis no momento. Os suspeitos Hati e PlayerName também fugiram.)",
  ui_story_5046_50460801_3_dialog_content = "(Do jeito que as coisas estão, minha única opção é continuar investigando o orfanato.)",
  ui_story_5046_50460801_4_dialog_content = "(Quase nenhum vestígio do passado permanece após a reconstrução do orfanato. Agora, apenas as crianças remanescentes daquele ano ainda precisam ser investigadas.)",
  ui_story_5046_50460801_5_dialog_content = "Você é um juiz? Tem certeza que você tem a pessoa certa? Eu sou apenas um servo...",
  ui_story_5046_50460801_6_dialog_content = "(Havia apenas duas pessoas que eu poderia encontrar registros nos arquivos. Parece que essa garota é dois anos mais velha que Hati.)",
  ui_story_5046_50460801_7_dialog_content = "(Depois do incêndio, ela foi enviada para morar com uma família adotiva próxima. Agora, ela é empregada doméstica de uma família nobre em Lumopolis.)",
  ui_story_5046_50460801_8_dialog_content = "Por favor, não precisa ficar nervoso. Só quero saber sobre o incêndio no Orfanato Umbraton.",
  ui_story_5046_50460801_9_dialog_content = "Pelo que eu sei, você ficou lá por um bom tempo.",
  ui_story_5046_50460801_10_dialog_content = "Eles me fizeram todas essas perguntas tantas vezes antes... Por que isso está acontecendo de novo?",
  ui_story_5046_50460801_11_dialog_content = "Eu estava dormindo profundamente naquela noite... até que fui acordado pelos gritos das outras crianças. Quando acordei, o lugar todo já estava em chamas.",
  ui_story_5046_50460801_12_dialog_content = "Aquela nova garota, a demi-humana – todo o seu corpo estava em chamas. O menino na cama ao meu lado disse que foi ela quem começou tudo.",
  ui_story_5046_50460801_13_dialog_content = "Eu me esforcei para sair de lá, eu realmente não conseguia prestar atenção em muito mais.",
  ui_story_5046_50460801_14_dialog_content = "(Hmm ... É exatamente o mesmo que sua declaração anterior. Todas essas informações são conhecidas.)",
  ui_story_5046_50460801_15_dialog_content = "Você notou na época se esse semi-humano chamado Hati tinha discutido com alguém no orfanato?",
  ui_story_5046_50460801_16_dialog_content = "Ou ela guardava alguma queixa contra os professores, administradores ou outras pessoas do orfanato?",
  ui_story_5046_50460801_17_dialog_content = "Não tenho certeza, não tinha ouvido nada.",
  ui_story_5046_50460801_18_dialog_content = "Mas vingança...? Quantos anos ela tinha naquela época? Ela nem é tão velha quanto eu.",
  ui_story_5046_50460801_19_dialog_content = "E ela estava no orfanato há apenas um mês. Quem ela poderia ter feito inimigos em tão pouco tempo?",
  ui_story_5046_50460801_20_dialog_content = "Se você realmente acha que pode ser possível, algumas crianças eram maiores que as outras e gostavam de jogar seu peso para intimidar as pessoas para que fizessem o que queriam.",
  ui_story_5046_50460801_21_dialog_content = "Aquela garota semi-humana era muito pequena para lutar contra aqueles garotos grandes...",
  ui_story_5046_50460801_22_dialog_content = "E os professores de lá não se importavam com nenhuma das brigas entre as crianças, não eram nem pacientes nem gentis...",
  ui_story_5046_50460801_23_dialog_content = "Acho que nenhum de nós gostou do pessoal de lá?",
  ui_story_5046_50460801_24_dialog_content = "A propósito, há mais uma coisa que quero perguntar.",
  ui_story_5046_50460801_25_dialog_content = "Você manteve contato com alguma das crianças que foram adotadas no orfanato?",
  ui_story_5046_50460801_26_dialog_content = "A taxa de adoção no orfanato era muito alta, mas não há registros de nenhum adotado e nenhuma prova de visitas de retorno...",
  ui_story_5046_50460801_27_dialog_content = "Não tenho mantido contato com ninguém.",
  ui_story_5046_50460801_28_dialog_content = "Naquela época, costumávamos brincar que quando eles vinham levar oito ou nove crianças todos os meses, eles estavam sendo alimentados em Eclipsites.",
  ui_story_5046_50460801_29_dialog_content = "Oito ou nove crianças eram adotadas todos os meses...",
  ui_story_5046_50460801_30_dialog_content = "(Esta é realmente uma situação anormal...)",
  ui_story_5046_50460801_31_dialog_content = "Desculpe por tomar seu tempo. Muito obrigado.",
  ui_story_5046_50460801_32_dialog_content = "(O próximo sobrevivente é um menino da mesma idade que Hati.)",
  ui_story_5046_50460801_33_dialog_content = "(De acordo com os registros, ele administrou a padaria com seus pais adotivos depois que foi adotado.)",
  ui_story_5046_50460801_34_dialog_content = "Você é um juiz? Eu não fiz nada!",
  ui_story_5046_50460801_35_dialog_content = "Por favor, não precisa ficar tão nervoso. Quero entender o que aconteceu com relação ao incêndio no Orfanato Umbraton.",
  ui_story_5046_50460801_36_dialog_content = "Huh? Isso tudo aconteceu há muito tempo, mas você ainda está investigando, hein?",
  ui_story_5046_50460801_37_dialog_content = "Mas temo que você esteja sem sorte - não posso lhe contar nada de novo. Tudo o que eu conseguia lembrar já foi anotado em meu depoimento.",
  ui_story_5046_50460801_38_dialog_content = "Então, se possível, espero que evite assustar meus clientes.",
  ui_story_5046_50460801_39_dialog_content = "Hum...",
  ui_story_5046_50460801_40_dialog_content = "Se você puder me ajudar lembrando mais do que aconteceu, comprarei todo o pão da sua padaria.",
  ui_story_5046_50460801_41_dialog_content = "Uhum!?",
  ui_story_5046_50460801_42_dialog_content = "Bem, agora que você mencionou isso, talvez eu consiga me lembrar de mais alguns detalhes.",
  ui_story_5046_50460801_43_dialog_content = "Obrigado por sua cooperação. Você disse aquilo Hati definir o fogo. Você pode descrever o que aconteceu com mais detalhes?",
  ui_story_5046_50460801_44_dialog_content = "Naquela noite... Sempre tive o sono muito leve desde pequeno, então acordei assim que ouvi aquele demi-humano começar a gritar.",
  ui_story_5046_50460801_45_dialog_content = "Minha cama era bem longe da dela. Eu não vi o que tinha acontecido, mas ela começou a ficar brava depois da gritaria.",
  ui_story_5046_50460801_46_dialog_content = "Então as chamas por todo o corpo dela incendiaram a cortina. O fogo começou a ficar cada vez maior e as outras crianças acabaram acordando.",
  ui_story_5046_50460801_47_dialog_content = "Corri, junto com todas as outras crianças, mas minha perna estava queimada. Eu disse tudo isso antes, quando eles me perguntaram pela primeira vez.",
  ui_story_5046_50460801_48_dialog_content = "Então, você sabe se Hati, o demi-humano, fez algum inimigo no orfanato?",
  ui_story_5046_50460801_49_dialog_content = "As vítimas dos recentes ataques incendiários foram todas relacionadas ao orfanato. Eu quero saber se eles guardaram algum rancor contra Hati.",
  ui_story_5046_50460801_50_dialog_content = "Sempre apareciam novas crianças no orfanato, mas a maioria acabava sendo mandada embora antes de realmente conhecer alguém.",
  ui_story_5046_50460801_51_dialog_content = "Se não fosse pelo fato de ela ser uma demi-humana, eu nem teria me lembrado de quem ela era, muito menos com quem ela não se dava bem.",
  ui_story_5046_50460801_52_dialog_content = "Quanto às pessoas que dirigiam o orfanato...",
  ui_story_5046_50460801_53_dialog_content = "Eles tinham que lidar com um grande grupo de pirralhos barulhentos todos os dias, e nenhum deles era deles.",
  ui_story_5046_50460801_54_dialog_content = "Mesmo que parecessem amigáveis o suficiente na superfície, quem sabia como eles realmente eram atrás de portas fechadas?",
  ui_story_5046_50460801_55_dialog_content = "(Parece que todo mundo tem uma má impressão do pessoal do orfanato...)",
  ui_story_5046_50460801_56_dialog_content = "Você teve contato com alguma das outras crianças adotadas no orfanato?",
  ui_story_5046_50460801_57_dialog_content = "Ou você tem os detalhes de contato de alguma das famílias adotivas?",
  ui_story_5046_50460801_58_dialog_content = "Perdi contato com todos depois que foram adotados.",
  ui_story_5046_50460801_59_dialog_content = "Quanto aos detalhes de contato das famílias adotivas...",
  ui_story_5046_50460801_60_dialog_content = "Isso não é algo que o diretor deveria ter anotado?",
  ui_story_5046_50460801_61_dialog_content = "Sabe, eu via as professoras do orfanato olhando para certas crianças, escrevendo e desenhando em seus cadernos.",
  ui_story_5046_50460801_62_dialog_content = "E quando chegou a hora da adoção, essas foram as crianças que foram mandadas embora.",
  ui_story_5046_50460801_63_dialog_content = "Agora que penso nisso, esses cadernos devem conter bastante informação sobre os filhos adotivos, não? Não sei, você é um juiz, deveria ter autoridade para dar uma olhada neles, certo?",
  ui_story_5046_50460801_64_dialog_content = "Infelizmente, parece que tudo foi destruído no incêndio.",
  ui_story_5046_50460801_65_dialog_content = "De qualquer forma, obrigado por sua cooperação. Vou pegar todo o pão que você tem.",
  ui_story_5046_50460801_66_dialog_content = "(Ufa, consegui lidar com aquela quantidade ridiculamente grande de pão. Mas agora...)",
  ui_story_5046_50460801_67_dialog_content = "(Ainda tem a questão daqueles filhos adotivos que sumiram, e Hati, que foi acusada de ser uma assassina quando era apenas uma criança.)",
  ui_story_5046_50460801_68_dialog_content = "(Que tipo de orfanato consegue ter tantas crianças adotadas todos os meses e depois desaparecem todas sem deixar vestígios?)",
  ui_story_5046_50460801_69_dialog_content = "(O pior cenário é que eles os usaram para alguma coisa...)",
  ui_story_5046_50460801_70_dialog_content = "(É um pensamento horrível... mas se for verdade, Hati tinha justo motivo para iniciar o incêndio e matar o Sr. Hamell.)",
  ui_story_5046_50460801_71_dialog_content = "(O próprio pensamento disso me faz estremecer. Quantos segredos estão escondidos naquele velho orfanato?)",
  ui_story_5046_50460801_72_dialog_content = "Ai...",
  ui_story_5046_50460801_73_dialog_content = "Preste atenção onde pisa, senhorita.",
  ui_story_5046_50460801_74_dialog_content = "Obrigada...",
  ui_story_5046_50460801_75_dialog_content = "Grimme é o nome. Sou o dono do Firefly Bar, logo ali na esquina.",
  ui_story_5046_50460801_76_dialog_content = "Grime? Você não é amigo de Hati? O Sr. Zenas mencionou você.",
  ui_story_5046_50460801_77_dialog_content = "Oh, então você já ouviu falar de mim? Ouça, você se importa se deixarmos a conversa fiada para mais tarde? Na verdade, há algo que eu queria saber se você poderia me ajudar.",
  ui_story_5046_50460801_78_dialog_content = "O que é isso...?",
  ui_story_5046_50460801_79_dialog_content = "Graaahh—!",
  ui_story_5046_50460801_80_dialog_content = "!!!",
  ui_story_5046_50460801_81_dialog_content = "Acabei de lidar com algumas coisas imundas nos subúrbios.",
  ui_story_5046_50460801_82_dialog_content = "Eclipsos!? Cuidado atrás de você!",
  ui_story_5046_50460802_1_dialog_content = "Obrigado, jovem. Se você não estivesse aqui para ajudar agora, aqueles Eclipsitas teriam acabado comigo.",
  ui_story_5046_50460802_2_dialog_content = "Não foi nada. A propósito, quero perguntar-lhe algo sobre Hati.",
  ui_story_5046_50460802_3_dialog_content = "Certamente. O Firefly Bar fica na esquina à frente. Vamos sentar e conversar enquanto tomamos uma bebida.",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>Ding—!</color>",
  ui_story_5046_50460802_5_dialog_content = "Desculpe pela inconveniência.",
  ui_story_5046_50460802_6_dialog_content = "Você acabou de me fazer um favor, senhorita. Isso é o mínimo que posso fazer.",
  ui_story_5046_50460802_7_dialog_content = "Por favor, sente-se. Ainda não é horário comercial. Você gostaria de algo para beber?",
  ui_story_5046_50460802_8_dialog_content = "Estou de plantão e não bebo.",
  ui_story_5046_50460802_9_dialog_content = "Além do álcool, também temos uma variedade de refrigerantes muito bons aqui.",
  ui_story_5046_50460802_10_dialog_content = "Tem Blue Storm, Umbraton Delight, White Night Iced Tea...",
  ui_story_5046_50460802_11_dialog_content = "Não, obrigado. Vamos direto ao ponto.",
  ui_story_5046_50460802_12_dialog_content = "Como você e Hati encontrar?",
  ui_story_5046_50460802_13_dialog_content = "Bem, ela trabalha aqui comigo, não é?",
  ui_story_5046_50460802_14_dialog_content = "Ela geralmente cuida de trazer os ingredientes, limpar a cozinha... muitos trabalhos diferentes, na verdade. Ela não fala muito, mas é uma trabalhadora e tanto.",
  ui_story_5046_50460802_15_dialog_content = "onde estava Hati quando ocorreram os incêndios recentes?",
  ui_story_5046_50460802_16_dialog_content = "Agora, esses não eram tão recentes, não consigo me lembrar direito.",
  ui_story_5046_50460802_17_dialog_content = "No entanto, eu me lembro desse dia com muita clareza. Era dia de compra.",
  ui_story_5046_50460802_18_dialog_content = "Hati passava o dia todo ocupada na cozinha, contando o estoque e verificando o frescor dos ingredientes. Ela não teve chance de descansar até a noite.",
  ui_story_5046_50460802_19_dialog_content = "(Este foi o dia em que Fairmont foi morto. De acordo com o testemunho de Grimme, Hati não teve a oportunidade de cometer assassinato.)",
  ui_story_5046_50460802_20_dialog_content = "(No entanto, Grimme pode estar tentando proteger Hati.)",
  ui_story_5046_50460802_21_dialog_content = "Senhorita, por favor, acredite em mim. Eu estou te dizendo a verdade.",
  ui_story_5046_50460802_22_dialog_content = "Você pode me ligar Kristen.",
  ui_story_5046_50460802_23_dialog_content = "De volta a Hati— você tem alguma outra informação sobre ela que possa compartilhar comigo?",
  ui_story_5046_50460802_24_dialog_content = "Por exemplo, ela já mencionou guardar rancor de alguém? Ela já mencionou vingança ou algo parecido?",
  ui_story_5046_50460802_25_dialog_content = "Como eu disse, Hati não fala muito. Não nos conhecemos há muito tempo, mas não a ouvi mencionar nada parecido desde que a conheço.",
  ui_story_5046_50460802_26_dialog_content = "(Isso não parece estar me levando a lugar nenhum.)",
  ui_story_5046_50460802_27_dialog_content = "Nesse caso, não vou incomodá-lo mais. Bom dia.",
  ui_story_5046_50460802_28_dialog_content = "Vai embora sem provar o suco caseiro que fiz só para você?",
  ui_story_5046_50460802_29_dialog_content = "Você não parecia interessado em nenhuma das bebidas que mencionei antes, então preparei uma bebida especial para você agora.",
  ui_story_5046_50460802_30_dialog_content = "Você deve saber, eu sou o melhor mixologista em Umbraton.",
  ui_story_5046_50460802_31_dialog_content = "Não será necessário.",
  ui_story_5046_50460802_32_dialog_content = "Não seja assim. Uma bebida para uma história que mistura verdade e mentira – é assim que as coisas são feitas em Umbraton.",
  ui_story_5046_50460802_33_dialog_content = "Qual é o mal em tentar, hein?",
  ui_story_5046_50460802_34_dialog_content = "(Parece que Grimme está tentando insinuar algo... e por que de repente está tão perto de mim!?)",
  ui_story_5046_50460802_35_dialog_content = "Ainda tenho deveres oficiais a cumprir e o culpado ainda não foi pego. Não posso...",
  ui_story_5046_50460802_36_dialog_content = "Você parecia tão triste quando te vi lá na rua. O caso atingiu uma parede de tijolos?",
  ui_story_5046_50460802_37_dialog_content = "É nessas horas que devemos sentar para tomar uma bebida e ouvir um ou dois contos para relaxar. Você pode até encontrar alguma nova inspiração.",
  ui_story_5046_50460802_38_dialog_content = "(Isso parece certo.)",
  ui_story_5046_50460802_39_dialog_content = "(Não há outras pistas por enquanto. Eu deveria apenas sentar e ouvir.)",
  ui_story_5046_50460802_40_dialog_content = "Tudo bem, mas apenas um.",
  ui_story_5046_50460802_41_dialog_content = "Hehe, então eu vou começar a história.",
  ui_story_5046_50460802_42_dialog_content = "Dez anos atrás, Umbraton não tinha um Shadowlord, e ninguém se importava com a luta e matança acontecendo nas ruas, muito menos um certo orfanato nos arredores da cidade.",
  ui_story_5046_50460802_43_dialog_content = "Mas este orfanato na periferia ainda conseguiu se manter aberto para negócios...",
  ui_story_5046_50460802_44_dialog_content = "Qual você acha que foi a razão para isso?",
  ui_story_5046_50460802_45_dialog_content = "Nesta sociedade turbulenta, o orfanato conseguiu se manter operacional... Suponho que foi por causa do apoio de uma pessoa caridosa.",
  ui_story_5046_50460802_46_dialog_content = "Está correto. O orfanato de fato recebeu apoio, mas não houve caridade.",
  ui_story_5046_50460802_47_dialog_content = "O orfanato tinha apenas cinco funcionários e um diretor, e não havia o menor rumor de algum tipo de figurão da Umbraton mantendo aquele lugar à tona.",
  ui_story_5046_50460802_48_dialog_content = "E de vez em quando, algumas crianças eram adotadas, enquanto outras eram enviadas para o orfanato...",
  ui_story_5046_50460802_49_dialog_content = "Era como comprar e vender bebidas atrás do bar.",
  ui_story_5046_50460802_50_dialog_content = "D-Você quer dizer que este orfanato estava comandando uma operação de tráfico de crianças?",
  ui_story_5046_50460802_51_dialog_content = "Não se precipite, esta história ainda não acabou.",
  ui_story_5046_50460802_52_dialog_content = "Eles dizem que as crianças adotadas foram enviadas para certos nobres de Lumópolis - nobres cuja linhagem está quase extinta.",
  ui_story_5046_50460802_53_dialog_content = "No entanto, ouvi dizer que há algum tempo, um funcionário chamado Pittman começou a investigar esses nobres novamente.",
  ui_story_5046_50460802_54_dialog_content = "<color=#FFB400>O caso</color> Pittman está investigando!",
  ui_story_5046_50460802_55_dialog_content = "Cinco funcionários e um diretor... Isso corresponde exatamente às informações que tenho sobre o antigo orfanato!",
  ui_story_5046_50460802_56_dialog_content = "O diretor do antigo orfanato foi morto no incêndio, e três dos funcionários morreram em incêndios ocorridos nos últimos dois meses...",
  ui_story_5046_50460802_57_dialog_content = "O Sr. Hamell também estava ligado ao antigo orfanato, mais a pessoa que ele mencionou...",
  ui_story_5046_50460802_58_dialog_content = "Isso dá cinco!",
  ui_story_5046_50460802_59_dialog_content = "Combinado com as declarações previamente investigadas das duas crianças que sobreviveram ao incêndio...",
  ui_story_5046_50460802_60_dialog_content = "O orfanato nesta história é o antigo orfanato, não é?",
  ui_story_5046_50460802_61_dialog_content = "Bem... Estou apenas contando uma história, nada mais.",
  ui_story_5046_50460802_62_dialog_content = "Se você pode obter alguma inspiração disso, bom para você.",
  ui_story_5046_50460802_63_dialog_content = "Aprendi muito com essa história. Eu aprecio sua ajuda.",
  ui_story_5046_50460802_64_dialog_content = "Mas estou curioso... Onde você ouviu essa história?",
  ui_story_5046_50460802_65_dialog_content = "O caso Sr. Pittman investigado está relacionado com os nobres de Lumópolis.",
  ui_story_5046_50460802_66_dialog_content = "Quem lhe contou esta história conhece tantos detalhes precisos. Não pode ter sido um cidadão comum.",
  ui_story_5046_50460802_67_dialog_content = "As pessoas que contam histórias aqui nem sempre deixam seus nomes. Quanto menos eu sei, mais interessante é a história.",
  ui_story_5046_50460802_68_dialog_content = "As sombras conhecem todos os segredos.",
  ui_story_5046_50460802_69_dialog_content = "(Grimme parece pouco confiável, mas fala com perfeita precisão.)",
  ui_story_5046_50460802_70_dialog_content = "(Nosso encontro nas ruas hoje não foi um acidente. Fui trazido aqui de propósito para ouvir tudo isso.)",
  ui_story_5046_50460802_71_dialog_content = "Tudo o que acontece no continente está conectado. Uma borboleta em Umbraton pode causar uma tempestade em Lumopolis.",
  ui_story_5046_50460802_72_dialog_content = "Hum?",
  ui_story_5046_50460802_73_dialog_content = "(O que há com esse olhar e o súbito ditado?)",
  ui_story_5046_50460802_74_dialog_content = "Hehe... Certo, certo, acabou a hora da história.",
  ui_story_5046_50460802_75_dialog_content = "Olha, a visão noturna é incrível. Você raramente consegue ver o céu noturno de Umbraton, certo?",
  ui_story_5046_50460802_76_dialog_content = "À noite, muitos pequenos vendedores aparecem em Umbraton, suas lâmpadas se estendendo como um rio de estrelas. É uma visão inesquecível.",
  ui_story_5046_50460802_77_dialog_content = "Obrigado pela sua história. A bebida era boa também.",
  ui_story_5046_50460802_78_dialog_content = "Hehe, este mocktail especial é realmente algo que eu nunca havia experimentado antes. Só pensei em fazer esse tipo de combinação depois de te ver.",
  ui_story_5046_50460802_79_dialog_content = "Essa bebida tem nome?",
  ui_story_5046_50460802_80_dialog_content = "Ainda não, mas vou chamá-lo de—",
  ui_story_5046_50460802_81_dialog_content = "Lírio de Lumópolis.",
  ui_story_5046_50460901_1_dialog_content = "Hati, você se lembra onde você morava?",
  ui_story_5046_50460901_2_dialog_content = "Se você quiser recuperar suas memórias do passado, vá para o lugar onde você morava e veja o que você consegue lembrar.",
  ui_story_5046_50460901_3_dialog_content = "Minha mãe e eu mudamos de casa várias vezes. Não consigo me lembrar do meu antigo endereço.",
  ui_story_5046_50460901_4_dialog_content = "Mas ainda me lembro da casa que coloquei fogo. Era perto de Umbraton.",
  ui_story_5046_50460901_5_dialog_content = "Você não queimou. Você definitivamente entendeu errado essa parte.",
  ui_story_5046_50460901_6_dialog_content = "Vamos lá dar uma olhada. Talvez você se lembre de algo.",
  ui_story_5046_50460901_7_dialog_content = "É isso.",
  ui_story_5046_50460901_8_dialog_content = "Todas as casas pelas quais passamos no caminho estavam desertas. Parece que ninguém mora aqui há muito tempo.",
  ui_story_5046_50460901_9_dialog_content = "Esta é a única casa que foi totalmente queimada. Basta um olhar para ver isso.",
  ui_story_5046_50460901_10_option_content = "Por que esse lugar foi abandonado?",
  ui_story_5046_50460901_11_dialog_content = "Não sei.",
  ui_story_5046_50460901_12_dialog_content = "Só me lembro que, quando acordei depois do incêndio, já estava no orfanato.",
  ui_story_5046_50460901_13_dialog_content = "Em pouco tempo, o orfanato pegou fogo e fui enviado para o Shadowlord.",
  ui_story_5046_50460901_14_dialog_content = "Hoje é a primeira vez que venho aqui há tanto tempo.",
  ui_story_5046_50460901_15_dialog_content = "Mostre-me sua casa.",
  ui_story_5046_50460901_16_option_content = "Por que você e sua mãe se mudavam com tanta frequência?",
  ui_story_5046_50460901_17_dialog_content = "Porque pessoas más estavam nos perseguindo o tempo todo.",
  ui_story_5046_50460901_18_dialog_content = "Minha mãe uma vez me disse que meu pai era muito poderoso e que alguém queria levá-lo embora e fazer experimentos com ele.",
  ui_story_5046_50460901_19_dialog_content = "Então, um dia, uma pessoa má invadiu nossa casa e tentou pegar meu pai. Depois disso, meu pai ficou para trás para proteger minha mãe.",
  ui_story_5046_50460901_20_dialog_content = "Mamãe fugiu e me deu à luz.",
  ui_story_5046_50460901_21_dialog_content = "Lembro-me de perguntar à minha mãe por que nunca pude ver meu pai. Mamãe me disse que meu pai estava em algum lugar distante.",
  ui_story_5046_50460901_22_dialog_content = "Quando eu cresci, minha mãe me disse que uma organização assustadora queria pegar meu pai para usá-lo em seus experimentos.",
  ui_story_5046_50460901_23_dialog_content = "Essa organização não desistia de nos perseguir, então minha mãe sempre me arrastava para novos lugares.",
  ui_story_5046_50460901_24_dialog_content = "Mostre-me sua casa.",
  ui_story_5046_50460901_25_option_content = "Mostre-me sua casa.",
  ui_story_5046_50460901_26_dialog_content = "Eu sei que está tudo queimado agora, mas você ainda deve se lembrar de como era a vida lá.",
  ui_story_5046_50460901_27_dialog_content = "Isso pode deixá-lo triste, mas qualquer pequeno detalhe pode desencadear suas memórias perdidas.",
  ui_story_5046_50460901_28_dialog_content = "Na verdade, eu estava com medo de voltar aqui... Com medo de lembrar os pequenos fragmentos das minhas memórias vivendo com mamãe.",
  ui_story_5046_50460901_29_dialog_content = "Também tenho medo de lembrar daquela outra memória que faltava...",
  ui_story_5046_50460901_30_dialog_content = "Se eu descobrir que mamãe me jogou na lareira porque temia meu poder...",
  ui_story_5046_50460901_31_dialog_content = "Sem chance. Sua mãe deve ter feito isso por algum outro motivo.",
  ui_story_5046_50460901_32_dialog_content = "O fogo não pode te machucar. Sua mãe devia saber disso.",
  ui_story_5046_50460901_33_dialog_content = "Talvez você estivesse em perigo naquele momento e sua mãe queria protegê-lo, então ela o colocou na lareira.",
  ui_story_5046_50460901_34_dialog_content = "Assim como seu pai ficou para trás para protegê-la.",
  ui_story_5046_50460901_35_dialog_content = "...",
  ui_story_5046_50460901_36_dialog_content = "Vamos. Vou te mostrar onde eu morava.",
  ui_story_5046_50460901_37_dialog_content = "Beleza!",
  ui_story_5046_50460901_38_dialog_content = "Você pode ver a sala daqui assim que passar pela porta. Minha mãe costumava me trazer comida saborosa e livros ilustrados.",
  ui_story_5046_50460901_39_dialog_content = "Havia uma janela aqui, sempre coberta por cortinas grossas. A luz não conseguia passar por ela e eu não conseguia ver o lado de fora.",
  ui_story_5046_50460901_40_dialog_content = "Mas eu podia ouvir as crianças brincando lá fora.",
  ui_story_5046_50460901_41_dialog_content = "Lembro que uma vez quis abrir a janela para ver o que as crianças estavam brincando, mas minha mãe me impediu na hora.",
  ui_story_5046_50460901_42_dialog_content = "\"Feche a janela! Agora mesmo!\"",
  ui_story_5046_50460901_43_dialog_content = "A sala devia estar sempre escura se a luz não conseguia entrar.",
  ui_story_5046_50460901_44_dialog_content = "Mamãe acendeu um monte de velas pela casa. Isso é o que usamos para a luz.",
  ui_story_5046_50460901_45_dialog_content = "Que estranho...",
  ui_story_5046_50460901_46_dialog_content = "Eu nasci com a poderosa chama Lumina. Mamãe disse que herdei do meu pai.",
  ui_story_5046_50460901_47_dialog_content = "Quando eu era pequeno, muitas vezes acidentalmente colocava fogo em colchas e livros ilustrados, e minha mãe também me disse que eu não tinha permissão para usar minhas chamas.",
  ui_story_5046_50460901_48_dialog_content = "Acho que minha mãe tinha medo do meu poder, então ela não me deixava sair para brincar com outras crianças... e aí ela me jogou na lareira.",
  ui_story_5046_50460901_49_dialog_content = "(A mãe de Hati não a deixava sair e ela lacrou a casa com segurança para que as pessoas não pudessem ver o interior...)",
  ui_story_5046_50460901_50_dialog_content = "(Além disso, as pessoas os estavam caçando. Talvez a mãe de Hati estivesse tentando esconder algo do mundo lá fora.)",
  ui_story_5046_50460901_51_dialog_content = "Olha, esta é a lareira.",
  ui_story_5046_50460901_52_dialog_content = "...",
  ui_story_5046_50460901_53_dialog_content = "PlayerName, eu... eu quero ir para a lareira.",
  ui_story_5046_50460901_54_dialog_content = "Hã?",
  ui_story_5046_50460901_55_dialog_content = "Da mesma forma que você me fez relembrar minha vida nesta casa, eu quero lembrar como foi ser jogado lá dentro.",
  ui_story_5046_50460901_56_dialog_content = "Talvez eu me lembre de algo.",
  ui_story_5046_50460901_57_dialog_content = "Parece uma ideia razoável...",
  ui_story_5046_50460901_58_dialog_content = "Beleza!",
  ui_story_5046_50460901_59_dialog_content = "Se você tiver algum problema lá, usarei minhas habilidades psíquicas para entrar em suas memórias e ajudá-lo!",
  ui_story_5046_50460901_60_dialog_content = "Obrigado... mas quero tentar lembrar sozinho.",
  ui_story_5046_50460901_61_dialog_content = "Ok, mas só me diga se precisar de ajuda!",
  ui_story_5046_50460901_62_dialog_content = "<color=#e8d9bb>Umbraton rural</color>",
  ui_story_5046_50460901_63_dialog_content = "O lugar Hati costumava viver é logo à frente.",
  ui_story_5046_50460901_64_dialog_content = "A mansão de férias de meu pai em Umbraton também fica perto.",
  ui_story_5046_50460901_65_dialog_content = "À esquerda neste cruzamento, e um pouco mais longe, devo conseguir ver os portões.",
  ui_story_5046_50460901_66_dialog_content = "A última vez que vim a esta mansão, estava de férias com meus pais. O lugar onde o Sr. Zenas me resgatou também é por aqui...",
  ui_story_5046_50460901_67_dialog_content = "Isso é... PlayerName!",
  ui_story_5046_50460901_68_dialog_content = "Você se lembrou de algo?",
  ui_story_5046_50460901_69_dialog_content = "Ainda não.",
  ui_story_5046_50460901_70_dialog_content = "Posso realmente... não me lembrar?",
  ui_story_5046_50460901_71_dialog_content = "PlayerName! Hati!",
  ui_story_5046_50460901_72_dialog_content = "Kristen!?",
  ui_story_5046_50460901_73_dialog_content = "Hati, de acordo com a lei, você está preso por suspeita de vários crimes graves, incluindo homicídio doloso e incêndio criminoso!",
  ui_story_5046_50460901_74_dialog_content = "E-Espere!",
  ui_story_5046_50460901_75_dialog_content = "Ela não fez nenhuma dessas coisas! Por que você está tentando prendê-la!?",
  ui_story_5046_50460901_76_dialog_content = "Que criminoso estaria disposto a admitir sua culpa?",
  ui_story_5046_50460901_77_dialog_content = "B-Bem, se você quer prender alguém, você não precisa de provas?",
  ui_story_5046_50460901_78_dialog_content = "... Evidência?",
  ui_story_5046_50460901_79_dialog_content = "PlayerName, você também não viu? Hati matou Hamell diante de nossos olhos.",
  ui_story_5046_50460901_80_dialog_content = "Kristen, acredite em mim, Hati não matou Hamell!",
  ui_story_5046_50460901_81_dialog_content = "Alguém deve ter matado Hamell das sombras.",
  ui_story_5046_50460901_82_dialog_content = "Em todo o caso, Hati estava lá quando Hamell morreu.",
  ui_story_5046_50460901_83_dialog_content = "Mesmo que ela não o tenha matado, ela é obrigada a cooperar com a investigação.",
  ui_story_5046_50460901_84_dialog_content = "Venha comigo.",
  ui_story_5046_50460901_85_dialog_content = "Preciso encontrar minhas memórias perdidas com minha mãe.",
  ui_story_5046_50460901_86_dialog_content = "Isso é tudo que me importa agora.",
  ui_story_5046_50460901_87_dialog_content = "Então, você está resistindo à prisão?",
  ui_story_5046_50460901_88_dialog_content = "Chame como quiser.",
  ui_story_5046_50460901_89_dialog_content = "Parece que vou ter que recorrer ao uso da força.",
  ui_story_5046_50460901_90_dialog_content = "Kristen, você pode deixar Hati tentar recuperar a memória dela antes de levá-la embora?",
  ui_story_5046_50460901_91_dialog_content = "Afaste-se, PlayerName.",
  ui_story_5046_50460901_92_dialog_content = "Terei que prendê-lo como cúmplice se você ficar no caminho do suspeito novamente.",
  ui_story_5046_50460901_93_dialog_content = "As memórias da mãe... são muito importantes.",
  ui_story_5046_50460901_94_dialog_content = "Eu posso entender a importância dessas memórias para Hati.",
  ui_story_5046_50460901_95_dialog_content = "E eu prometi a ela que ajudaria a encontrar essas memórias perdidas...",
  ui_story_5046_50460901_96_dialog_content = "Então, não... Não vou a lugar nenhum.",
  ui_story_5046_50460901_97_dialog_content = "eu vou proteger Hati até que ela encontra suas memórias perdidas.",
  ui_story_5046_50460901_98_dialog_content = "Você deseja proteger Hati... mas também desejo proteger o Capitão Zenas!",
  ui_story_5046_50460901_99_dialog_content = "Hati incendiaram o orfanato e fizeram você refém...",
  ui_story_5046_50460901_100_dialog_content = "É você quem lança uma sombra sobre o título de cavaleiro do Sr. Zenas!",
  ui_story_5046_50460901_101_dialog_content = "Ele suportou tanto para encontrar você e Hati!",
  ui_story_5046_50460901_102_dialog_content = "Se eu apenas levar você de volta e explicar tudo para o Shadowlord e para todo Umbraton...",
  ui_story_5046_50460901_103_dialog_content = "Se eu apenas fizer isso, o Sr. Zenas ficará bem!",
  ui_story_5046_50460901_104_dialog_content = "Vou dizer mais uma vez!",
  ui_story_5046_50460901_105_dialog_content = "Afaste-se, PlayerName!",
  ui_story_5046_50460901_106_dialog_content = "Não! Eu nunca vou me afastar!",
  ui_story_5046_50460901_107_dialog_content = "Hati... proteger... o pingente...",
  ui_story_5046_50460901_108_dialog_content = "Mãe... O que minha mãe queria que eu protegesse...?",
  ui_story_5046_50460901_109_dialog_content = "Diga-me, mãe...",
  ui_story_5046_50460901_110_dialog_content = "O que aconteceu naquele dia? Você me empurrou para a lareira tão impiedosamente...",
  ui_story_5046_50460901_111_dialog_content = "Vou dizer de novo, pela última vez! Afaste-se, PlayerName!",
  ui_story_5046_50460901_112_dialog_content = "Me dê... morra...",
  ui_story_5046_50460901_113_dialog_content = "Ugh! Minha cabeça dói! É como se algo estivesse se enterrando em meu cérebro!",
  ui_story_5046_50460901_114_dialog_content = "Ele está aqui.",
  ui_story_5046_50460901_115_dialog_content = "Este dia... Finalmente chegou.",
  ui_story_5046_50460901_116_dialog_content = "Mãmãe?",
  ui_story_5046_50460901_117_dialog_content = "Hati, não importa o que aconteça, se a mamãe está com você ou não, mamãe sempre vai te amar.",
  ui_story_5046_50460901_118_dialog_content = "Por que você não estaria comigo, mãe?",
  ui_story_5046_50460901_119_dialog_content = "Não entendo.",
  ui_story_5046_50460901_120_dialog_content = "É tarde demais...",
  ui_story_5046_50460901_121_dialog_content = "Hati, certifique-se de proteger esta metade do pingente.",
  ui_story_5046_50460901_122_dialog_content = "Este pingente simboliza o quanto seu pai e eu amamos você. Nós sempre protegeremos você, Hati.",
  ui_story_5046_50460901_123_dialog_content = "Viva uma boa vida. Mamãe te ama...",
  ui_story_5046_50460901_124_dialog_content = "Mãe!?",
  ui_story_5046_50460901_125_dialog_content = "Ugh!",
  ui_story_5046_50460901_126_dialog_content = "(Por que mamãe me empurrou para a lareira!?)",
  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5046_50460901_128_dialog_content = "(Tem alguém aqui!? Quem é? Ninguém nunca entrou na casa antes!)",
  ui_story_5046_50460901_129_dialog_content = "Não foi fácil localizá-la, Catherine Kelp. Você realmente acha que pode escapar?",
  ui_story_5046_50460901_130_dialog_content = "...Zenas.",
  ui_story_5046_50460901_131_dialog_content = "Tsk, esta casa é tão escura. Por que não há luz aqui?",
  ui_story_5046_50460901_132_dialog_content = "Uma senhora de luxo morando em uma casa como esta? Parece que a vida não tem sido muito boa para você ultimamente.",
  ui_story_5046_50460901_133_dialog_content = "Por mais miserável que seja a casa em que moro, enquanto você estiver morto, viverei muito bem.",
  ui_story_5046_50460901_134_dialog_content = "Shh, uma dama refinada nunca fala coisas tão horríveis.",
  ui_story_5046_50460901_135_dialog_content = "Chega de bobagens.",
  ui_story_5046_50460901_136_dialog_content = "Devo matá-lo hoje... para vingar Fenrir.",
  ui_story_5046_50460901_137_dialog_content = "(Fenrir? Esse é o nome do meu pai! Esse homem matou meu pai!?)",
  ui_story_5046_50460901_138_dialog_content = "Você superestima sua capacidade.",
  ui_story_5046_50460901_139_dialog_content = "Suspiro... suspiro...",
  ui_story_5046_50460901_140_dialog_content = "Catherine, apenas entregue o pingente e pouparei sua vida.",
  ui_story_5046_50460901_141_dialog_content = "Sobre o meu cadáver...",
  ui_story_5046_50460901_142_dialog_content = "Que teimoso. Se você realmente deseja morrer, eu o obrigarei.",
  ui_story_5046_50460901_143_dialog_content = "(Mãe!)",
  ui_story_5046_50460901_144_dialog_content = "Hyaa—!",
  ui_story_5046_50460901_145_dialog_content = "(O incêndio!? Foi a mamãe quem começou?)",
  ui_story_5046_50460901_146_dialog_content = "Argh! Como esse fogo se espalhou tão rapidamente?",
  ui_story_5046_50460901_147_dialog_content = "Este era o seu plano, Catherine?",
  ui_story_5046_50460901_148_dialog_content = "Você não vai sair daqui vivo...",
  ui_story_5046_50460901_149_dialog_content = "Me deixar ir! Você quer que eu seja queimado aqui com você!?",
  ui_story_5046_50460901_150_dialog_content = "Contanto que eu vingue Fenrir...",
  ui_story_5046_50460901_151_dialog_content = "Aaaaah!",
  ui_story_5046_50460901_152_dialog_content = "(Mãe! Mamãe ainda está olhando para mim...)",
  ui_story_5046_50460901_153_dialog_content = "...",
  ui_story_5046_50460901_154_dialog_content = "(Mamãe está dizendo... não saia?)",
  ui_story_5046_50460901_155_dialog_content = "(Mãe!? A mãe não está se mexendo!?)",
  ui_story_5046_50460901_156_dialog_content = "(Mãe-!)",
  ui_story_5046_50460901_157_dialog_content = "Hmph, nem suei.",
  ui_story_5046_50460901_158_dialog_content = "(Waaaah... Mãe...)",
  ui_story_5046_50460901_159_dialog_content = "(O homem está procurando alguma coisa pela mamãe...)",
  ui_story_5046_50460901_160_dialog_content = "(eu preciso ir lá e matá-lo... para vingar minha mãe!)",
  ui_story_5046_50460901_161_dialog_content = "(Não, mamãe só me disse para não sair...)",
  ui_story_5046_50460901_162_dialog_content = "Está tão quente aqui... Onde ela escondeu isso!?",
  ui_story_5046_50460901_163_dialog_content = "...",
  ui_story_5046_50460901_164_dialog_content = "Finalmente encontrei. Meu rosto arde, está queimado?",
  ui_story_5046_50460901_165_dialog_content = "Fogo! Fogo!",
  ui_story_5046_50460901_166_dialog_content = "Não posso deixar ninguém me ver.",
  ui_story_5046_50460901_167_dialog_content = "(Ele se foi... Mamãe não se mexe mais...)",
  ui_story_5046_50460901_168_dialog_content = "(Mãe...)",
  ui_story_5046_50460901_169_dialog_content = "Aquele incêndio estava fora de controle, mas finalmente conseguimos apagá-lo...",
  ui_story_5046_50460901_170_dialog_content = "Eles encontraram Catherine, mas ela já havia parado de respirar...",
  ui_story_5046_50460901_171_dialog_content = "Um fogo como esse vai te sufocar até a morte, mesmo que as chamas nunca te toquem...",
  ui_story_5046_50460901_172_dialog_content = "Se você não tem nada de bom para dizer, simplesmente não diga nada.",
  ui_story_5046_50460901_173_dialog_content = "Hunf.",
  ui_story_5046_50460901_174_dialog_content = "Ajude a limpar este lugar se não tiver nada para fazer.",
  ui_story_5046_50460901_175_dialog_content = "Sim, eu sei.",
  ui_story_5046_50460901_176_dialog_content = "Venha pra cá! Tem uma criança na lareira!",
  ui_story_5046_50460901_177_dialog_content = "Eu nunca ouvi Catherine mencionar que ela tinha um filho...",
  ui_story_5046_50460901_178_dialog_content = "E o garoto não está nem um pouco ferido, apesar daquelas chamas furiosas...",
  ui_story_5046_50460901_179_dialog_content = "Suspiro... Ela bloqueou as janelas e acendeu velas no quarto durante o dia.",
  ui_story_5046_50460901_180_dialog_content = "Era apenas uma questão de tempo até que isso acontecesse. Ver?",
  ui_story_5046_50460901_181_dialog_content = "Vamos, pare de ser tão mórbido. A questão mais importante agora é: o que fazemos com esse garoto?",
  ui_story_5046_50460901_182_dialog_content = "Levá-la para o orfanato?",
  ui_story_5046_50460901_183_dialog_content = "Acho que é tudo o que podemos fazer.",
  ui_story_5046_50460901_184_dialog_content = "Eu tenho outras perguntas.",
  ui_story_5046_50461001_1_dialog_content = "Ela parece estar se acalmando.",
  ui_story_5046_50461001_2_dialog_content = "Obrigado, Kristen.",
  ui_story_5046_50461001_3_dialog_content = "Para que?",
  ui_story_5046_50461001_4_dialog_content = "Obrigado, que você espere por Hati para recuperar sua memória.",
  ui_story_5046_50461001_5_dialog_content = "você não acha Hati é o culpado também, não é?",
  ui_story_5046_50461001_6_dialog_content = "Depois de conduzir uma investigação completa, eu certamente suspeito Hati menos.",
  ui_story_5046_50461001_7_dialog_content = "Embora esses casos estejam todos relacionados Hati, e todas as pistas apontam para ela.",
  ui_story_5046_50461001_8_dialog_content = "Mas ainda há muitas contradições a serem resolvidas.",
  ui_story_5046_50461001_9_dialog_content = "Você está realmente colocando tudo neste caso, Kristen.",
  ui_story_5046_50461001_10_dialog_content = "O Sr. Zenas me ensinou que devemos levar todos os casos a sério e nunca deixar uma única pista para trás.",
  ui_story_5046_50461001_11_dialog_content = "Mas ele ainda não estava disposto a me deixar assumir este caso...",
  ui_story_5046_50461001_12_dialog_content = "Então, Kristen, você está investigando este caso em segredo?",
  ui_story_5046_50461001_13_dialog_content = "Sim...",
  ui_story_5046_50461001_14_dialog_content = "Falando nisso, PlayerName, por que você fugiu com Hati? Ela está segurando você contra sua vontade.",
  ui_story_5046_50461001_15_dialog_content = "Acredito que ela seja inocente e, com tudo o que aconteceu, suas emoções estão muito instáveis.",
  ui_story_5046_50461001_16_dialog_content = "Ela precisava da minha ajuda, então pedi que me levasse com ela.",
  ui_story_5046_50461001_17_dialog_content = "Vocês estabeleceram um vínculo tão forte de confiança um com o outro em tão pouco tempo...?",
  ui_story_5046_50461001_18_dialog_content = "<size=30>Se ao menos o Sr. Zenas pudesse confiar tanto em mim...</size>",
  ui_story_5046_50461001_19_dialog_content = "Como você encontrou este lugar?",
  ui_story_5046_50461001_20_dialog_content = "Um local me mostrou o caminho.",
  ui_story_5046_50461001_21_dialog_content = "Não fica longe do orfanato, mas ainda faz parte de Umbraton. Muitos, muitos anos atrás, os habitantes daqui viviam vidas muito difíceis.",
  ui_story_5046_50461001_22_dialog_content = "O ano do incêndio do orfanato, Istvan conquistou o coração de muitas pessoas depois que ele assumiu a responsabilidade de melhorar a situação.",
  ui_story_5046_50461001_23_dialog_content = "Depois de se tornar o Shadowlord, Istvan pediu às pessoas daqui que se mudassem para Umbraton.",
  ui_story_5046_50461001_24_dialog_content = "Na verdade, foi o mesmo homem que entregou Hati ao orfanato, que me trouxe até aqui.",
  ui_story_5046_50461001_25_dialog_content = "Ele disse que um incêndio começou nesta cidade antes, e Hati foi encontrado nos escombros depois que o fogo foi extinto.",
  ui_story_5046_50461001_26_dialog_content = "A mulher que morava aqui morreu.",
  ui_story_5046_50461001_27_dialog_content = "Mas os moradores nunca ouviram a mulher mencionar que ela tinha um filho, então eles não sabiam o que fazer.",
  ui_story_5046_50461001_28_dialog_content = "Por fim, decidiram mandar a criança para o orfanato. Essa criança era Hati.",
  ui_story_5046_50461001_29_dialog_content = "Então é isso...",
  ui_story_5046_50461001_30_dialog_content = "Ótimo trabalho, Kristen. Você descobriu muito com apenas algumas pistas para continuar.",
  ui_story_5046_50461001_31_dialog_content = "Aham! Realmente não importa o quanto você me elogie, eu o trarei de volta comigo para cooperar com a investigação.",
  ui_story_5046_50461001_32_dialog_content = "Eu acredito do fundo do meu coração que você é realmente incrível! Eu sei que você será um ótimo juiz no futuro!",
  ui_story_5046_50461001_33_dialog_content = "Se ele pensasse o mesmo...",
  ui_story_5046_50461001_34_dialog_content = "Sr. Zenas?",
  ui_story_5046_50461001_35_dialog_content = "Sim... Sr. Zenas foi ferido usando Luminatics para apagar o fogo, mas mesmo depois disso, Sr. Hamell foi morto...",
  ui_story_5046_50461001_36_dialog_content = "Ele não tem mais fé em mim.",
  ui_story_5046_50461001_37_dialog_content = "Acho que você se saiu muito bem, Kristen.",
  ui_story_5046_50461001_38_dialog_content = "Embora só tenhamos tido a chance de nos encontrar algumas vezes, posso sentir que você é um juiz consciencioso, paciente e gentil.",
  ui_story_5046_50461001_39_dialog_content = "D-Não pense que suas palavras doces podem me transformar...",
  ui_story_5046_50461001_40_dialog_content = "Recebi ampla formação profissional do Lumo Hall of Justice! Minha crença na justiça nunca será abalada por gente como você!",
  ui_story_5046_50461001_41_dialog_content = "Eu só disse o que queria dizer! Eu não quis dizer mais nada com isso!",
  ui_story_5046_50461001_42_dialog_content = "Se Hati realmente tivesse feito essas coisas, eu a teria feito confessar.",
  ui_story_5046_50461001_43_dialog_content = "Mas se ela não fez nada, você não pode simplesmente incriminá-la!",
  ui_story_5046_50461001_44_dialog_content = "R-Certo! Esse é o significado de justiça!",
  ui_story_5046_50461001_45_dialog_content = "Você deve tentar acreditar em si mesmo e parar de se preocupar com o que as outras pessoas pensam.",
  ui_story_5046_50461001_46_dialog_content = "Especialmente considerando o quão incrível você é!",
  ui_story_5046_50461001_47_dialog_content = "...",
  ui_story_5046_50461001_48_dialog_content = "Alguém já lhe disse que você é muito bom em fazer as garotas felizes?",
  ui_story_5046_50461001_49_dialog_content = "Huh? Eu faço garotas felizes?",
  ui_story_5046_50461001_50_dialog_content = "Vice está sempre me odiando por gastar dinheiro e fazê-la se preocupar com as despesas do Colosso todos os dias.",
  ui_story_5046_50461001_51_dialog_content = "Seria melhor dizer que sempre causo problemas para as meninas.",
  ui_story_5046_50461001_52_dialog_content = "<size=45>Graaaaaah—</size>",
  ui_story_5046_50461001_53_dialog_content = "Isso foi um eclipse? Parece que há mais de um.",
  ui_story_5046_50461001_54_dialog_content = "Este lugar está deserto há tanto tempo. É de se esperar que os Eclipsites assombrem esta área.",
  ui_story_5046_50461001_55_dialog_content = "Mas Hati ainda não acordou. Receio que seja perigoso trazê-la aqui agora.",
  ui_story_5046_50461001_56_dialog_content = "Não se preocupe, são apenas alguns Eclipsites. Eu os julgarei na hora!",
  ui_story_5046_50461002_1_dialog_content = "Ufa—",
  ui_story_5046_50461002_2_dialog_content = "A aura do Eclipsite por aqui finalmente se dissipou.",
  ui_story_5046_50461002_3_dialog_content = "Obrigado, Kristen.",
  ui_story_5046_50461002_4_dialog_content = "Vejo agora o quão poderosos são os celestitas.",
  ui_story_5046_50461002_5_dialog_content = "Se não fosse por você, os ataques furtivos desses Eclipsites poderiam ter sido bem-sucedidos.",
  ui_story_5046_50461002_6_dialog_content = "PlayerName...",
  ui_story_5046_50461002_7_dialog_content = "Hati! Hati acordou!",
  ui_story_5046_50461002_8_dialog_content = "Agora que você está acordado, você deve voltar comigo para interrogatório. Antes que os resultados da investigação saiam...",
  ui_story_5046_50461002_9_dialog_content = "Foi o Zenas...",
  ui_story_5046_50461002_10_dialog_content = "Meu mentor?",
  ui_story_5046_50461002_11_dialog_content = "PlayerName... Lembro-me de tudo.",
  ui_story_5046_50461002_12_dialog_content = "Naquela noite, minha mãe me empurrou para a lareira para me proteger.",
  ui_story_5046_50461002_13_dialog_content = "Ela enfrentou Zenas sozinha... Sim, o nome daquele homem era Zenas.",
  ui_story_5046_50461002_14_dialog_content = "Ele matou minha mãe e roubou o pingente dela.",
  ui_story_5046_50461002_15_dialog_content = "Devo recuperar o pingente.",
  ui_story_5046_50461002_16_dialog_content = "Meu mentor? O que isso tem a ver com meu mentor?",
  ui_story_5046_50461002_17_dialog_content = "Zenas é o assassino.",
  ui_story_5046_50461002_18_dialog_content = "Baboseira!",
  ui_story_5046_50461002_19_dialog_content = "Se você ousar desrespeitar o Sr. Zenas novamente, não me culpe pelo que eu fizer a seguir!",
  ui_story_5046_50461002_20_dialog_content = "Um assassino é um assassino, e ele é o único.",
  ui_story_5046_50461002_21_dialog_content = "Zenas invadiu minha casa naquela noite, matou minha mãe e roubou meu pingente.",
  ui_story_5046_50461002_22_dialog_content = "Eu vi tudo com meus próprios olhos! Preciso matá-lo para vingar minha mãe!",
  ui_story_5046_50461002_23_dialog_content = "Como você pode dizer que meu mentor assassinou sua mãe!?",
  ui_story_5046_50461002_24_dialog_content = "Você acabou de se lembrar desse incidente, e já faz tanto tempo.",
  ui_story_5046_50461002_25_dialog_content = "Como você pode ter certeza de que sua memória não está errada? E como eu sei que você não está mentindo?",
  ui_story_5046_50461002_26_dialog_content = "Eu sei que não estou errado...",
  ui_story_5046_50461002_27_dialog_content = "Com as queimaduras no rosto e o pingente da minha mãe...",
  ui_story_5046_50461002_28_dialog_content = "Tenho certeza que ele é o assassino!",
  ui_story_5046_50461002_29_dialog_content = "Sinto muito, mas meu mentor sofreu uma queimadura no rosto quando estava me salvando.",
  ui_story_5046_50461002_30_dialog_content = "Naquela noite, meus pais saíram para um banquete.",
  ui_story_5046_50461002_31_dialog_content = "Lembro que escureceu bem cedo naquele dia... Assim que despedi meus pais, escureceu.",
  ui_story_5046_50461002_32_dialog_content = "Voltei para o meu quarto para ler sozinho.",
  ui_story_5046_50461002_33_dialog_content = "De repente, um grande incêndio começou em algum lugar. Meus pais não estavam em casa, e a fumaça ficou mais densa, eu só fiquei lá chorando alto.",
  ui_story_5046_50461002_34_dialog_content = "Felizmente, o Sr. Zenas gritou meu nome e seguiu meus soluços para me encontrar...",
  ui_story_5046_50461002_35_dialog_content = "Enquanto estávamos fugindo, o Sr. Zenas me segurou com força em seus braços, e eu não sofri nenhum ferimento, exceto por ser sufocado pela fumaça pesada.",
  ui_story_5046_50461002_36_dialog_content = "Mas o Sr. Zenas... Metade de seu rosto foi queimado.",
  ui_story_5046_50461002_37_dialog_content = "Então, o rosto de Zenas foi queimado durante o resgate Kristen.",
  ui_story_5046_50461002_38_dialog_content = "...",
  ui_story_5046_50461002_39_dialog_content = "Hati, você se lembra do dia em que Zenas atacou?",
  ui_story_5046_50461002_40_dialog_content = "26 de agosto. Era... meu aniversário.",
  ui_story_5046_50461002_41_dialog_content = "26 de agosto!?",
  ui_story_5046_50461002_42_dialog_content = "O dia em que o Sr. Zenas me salvou também foi 26 de agosto.",
  ui_story_5046_50461002_43_dialog_content = "Naquele dia... eu me lembro muito claramente.",
  ui_story_5046_50461002_44_dialog_content = "Parece que esses dois eventos aconteceram no mesmo dia...",
  ui_story_5046_50461002_45_dialog_content = "Agora mesmo, Kristen disse que sua mansão pegou fogo naquela noite, o que significa que Zenas apareceu na casa de Kristen durante a noite.",
  ui_story_5046_50461002_46_dialog_content = "Mas Hati também disse que Zenas atacou à noite.",
  ui_story_5046_50461002_47_dialog_content = "Em outras palavras, Zenas apareceu em dois lugares diferentes ao mesmo tempo no mesmo dia.",
  ui_story_5046_50461002_48_dialog_content = "Quando você olha dessa maneira, é impossível. Você deve estar enganado, Hati.",
  ui_story_5046_50461002_49_dialog_content = "Como você explica o pingente?",
  ui_story_5046_50461002_50_dialog_content = "Por que o pingente que minha mãe me pediria para cuidar nas mãos dele?",
  ui_story_5046_50461002_51_dialog_content = "Foi justamente por causa desse pingente que eu o reconheci.",
  ui_story_5046_50461002_52_dialog_content = "O pingente que você mencionou é herança de família do meu mentor.",
  ui_story_5046_50461002_53_dialog_content = "O padrão no pingente é o brasão da família nobre de Lumopolis que infelizmente caiu há mais de uma década.",
  ui_story_5046_50461002_54_dialog_content = "No dia em que meu mentor me resgatou do incêndio, meu pai desejou expressar sua gratidão por salvar minha vida e perguntou-lhe sobre seu passado.",
  ui_story_5046_50461002_55_dialog_content = "Meu mentor pegou aquele pingente e disse que originalmente era um nobre, mas teve que vagar sem esperança porque sua família declinou.",
  ui_story_5046_50461002_56_dialog_content = "Meu pai simpatizou com ele, sendo um nobre companheiro, e pediu ao meu mentor para ficar e servir a nossa família.",
  ui_story_5046_50461002_57_dialog_content = "Lembro-me claramente que o pingente era da minha mãe.",
  ui_story_5046_50461002_58_dialog_content = "Ele deve ter pegado o pingente da minha mãe e passado como se fosse dele!",
  ui_story_5046_50461002_59_dialog_content = "Você! Suas inferências não podem ser consideradas verdadeiras até que você tenha evidências.",
  ui_story_5046_50461002_60_dialog_content = "(Hati mencionou anteriormente que sua mãe mantinha a casa bem protegida contra a luz do dia e a acendia com velas.)",
  ui_story_5046_50461002_61_dialog_content = "(Então talvez Hati não tem certeza se era dia ou noite quando o incidente ocorreu!)",
  ui_story_5046_50461002_62_dialog_content = "Hati, você pode ter certeza de que o assassino invadiu sua casa à noite?",
  ui_story_5046_50461002_63_dialog_content = "Eu me lembro de velas iluminando o quarto. Deveria ser noite.",
  ui_story_5046_50461002_64_dialog_content = "Essa e a coisa.",
  ui_story_5046_50461002_65_dialog_content = "Como as velas costumam iluminar sua casa, é claro que você pensaria...",
  ui_story_5046_50461002_66_dialog_content = "\"Como vi velas acesas, o incidente ocorreu à noite.\"",
  ui_story_5046_50461002_67_dialog_content = "Mas, na verdade, as velas eram acesas em sua casa dia e noite, então seria errado usar velas acesas para julgar as horas.",
  ui_story_5046_50461002_68_dialog_content = "Suponho que a hora em que a casa de Hati foi atacada era de dia.",
  ui_story_5046_50461002_69_dialog_content = "Então é isso...",
  ui_story_5046_50461002_70_dialog_content = "Kristen pode se lembrar com precisão de seus pais participando de um banquete à noite e lembra que escureceu cedo naquele dia.",
  ui_story_5046_50461002_71_dialog_content = "Então o incêndio na casa de Kristen realmente aconteceu à noite.",
  ui_story_5046_50461002_72_dialog_content = "De acordo com esta dedução, o suspeito atacou a casa de Hati durante o dia e correu para a casa de Kristen à noite para apagar o fogo.",
  ui_story_5046_50461002_73_dialog_content = "Portanto, não há instância de uma pessoa aparecendo em dois lugares diferentes ao mesmo tempo.",
  ui_story_5046_50461002_74_dialog_content = "Brilhante raciocínio...",
  ui_story_5046_50461002_75_dialog_content = "Mas ainda precisamos de mais algumas informações. Quanto tempo leva para ir daqui até sua mansão de férias?",
  ui_story_5046_50461002_76_dialog_content = "Eu tomei nota disso no meu caminho para cá. Não é longe da minha mansão.",
  ui_story_5046_50461002_77_dialog_content = "Foi realmente... meu mentor? Não, é impossível...",
  ui_story_5046_50461002_78_dialog_content = "Se você deseja determinar se Zenas era o atacante, apenas peça a ele para mostrar seu pingente.",
  ui_story_5046_50461002_79_dialog_content = "Hati disse que esses dois pingentes eram um par correspondente.",
  ui_story_5046_50461002_80_dialog_content = "Se Zenas não atacou a família de Hati e, como ele disse, ele é de fato um nobre caído...",
  ui_story_5046_50461002_81_dialog_content = "Então o pingente dele não combinará com o da mão de Hati.",
  ui_story_5046_50461002_82_dialog_content = "Mas se esses dois pingentes se encaixarem perfeitamente...",
  ui_story_5046_50461002_83_dialog_content = "Então ele deve ser o culpado.",
  ui_story_5046_50461002_84_dialog_content = "Não, meu mentor não pode ser um assassino!",
  ui_story_5046_50461002_85_dialog_content = "Ah sim, isso mesmo! Motivo!",
  ui_story_5046_50461002_86_dialog_content = "Nenhuma inimizade existia entre sua família e meu mentor, então por que ele caçaria e mataria seus pais?",
  ui_story_5046_50461002_87_dialog_content = "Minha mãe me disse que uma organização misteriosa queria o poder do meu pai e queria pegá-lo para usá-lo em seus experimentos.",
  ui_story_5046_50461002_88_dialog_content = "Em minha memória, minha mãe queria vingar meu pai e perdeu a vida tentando matar Zenas...",
  ui_story_5046_50461002_89_dialog_content = "Então, Zenas é membro dessa misteriosa organização.",
  ui_story_5046_50461002_90_dialog_content = "Não acredito!",
  ui_story_5046_50461002_91_dialog_content = "Não, não tem jeito!",
  ui_story_5046_50461002_92_dialog_content = "Kristen, acalmar.",
  ui_story_5046_50461002_93_dialog_content = "Se Zenas é o culpado ou não, pode ser determinado simplesmente colocando seu pingente e o de Hati juntos.",
  ui_story_5046_50461002_94_dialog_content = "Peça a ele para entregar seu pingente.",
  ui_story_5046_50461002_95_dialog_content = "Se ele se recusar a entregá-lo, vou espancá-lo e arrancá-lo dele.",
  ui_story_5046_50461002_96_dialog_content = "Não podemos usar violência! Umbraton está cheio de soldados procurando por você. Será difícil para nós confrontar Zenas e discutir isso com ele.",
  ui_story_5046_50461002_97_dialog_content = "...",
  ui_story_5046_50461002_98_dialog_content = "Posso te ajudar.",
  ui_story_5046_50461002_99_dialog_content = "Como PlayerName disse, confirmando se os pingentes se encaixam é a maneira mais fácil de provar a inocência do meu mentor.",
  ui_story_5046_50461002_100_dialog_content = "Então, vou ajudá-lo a encontrar meu mentor sem nenhum outro soldado.",
  ui_story_5046_50461002_101_dialog_content = "No entanto, você também deve me prometer que, se os pingentes não se encaixarem, você cooperará totalmente com a investigação.",
  ui_story_5046_50461002_102_dialog_content = "Então, você acredita em nós?",
  ui_story_5046_50461002_103_dialog_content = "Eu não disse isso.",
  ui_story_5046_50461002_104_dialog_content = "Mas aprendi muito com a atitude de investigação séria PlayerName tem em relação a este incidente.",
  ui_story_5046_50461002_105_dialog_content = "Quero reexaminar este caso com mais cuidado.",
  ui_story_5046_50461002_106_dialog_content = "Está ficando tarde. Vamos voltar rápido para Umbraton.",
  ui_story_5046_50461101_1_dialog_content = "Perder Kristen, você voltou.",
  ui_story_5046_50461101_2_dialog_content = "Apenas me ligue Kristen.",
  ui_story_5046_50461101_3_dialog_content = "Onde está o capitão Zenas? Por que não consigo encontrá-lo?",
  ui_story_5046_50461101_4_dialog_content = "O capitão Zenas levou várias pessoas ao orfanato.",
  ui_story_5046_50461101_5_dialog_content = "O orfanato? O que o capitão está fazendo aí?",
  ui_story_5046_50461101_6_dialog_content = "Erm... Ele não disse.",
  ui_story_5046_50461101_7_dialog_content = "Tudo bem, continue.",
  ui_story_5046_50461101_8_dialog_content = "Não encontramos nada, senhor.",
  ui_story_5046_50461101_9_dialog_content = "Continue olhando. Qualquer coisa que você encontrar, você me passa direto, entendeu?",
  ui_story_5046_50461101_10_dialog_content = "Reportando!",
  ui_story_5046_50461101_11_dialog_content = "Você encontrou algo?",
  ui_story_5046_50461101_12_dialog_content = "Não, mas senhorita Kristen é aqui. Ela quer ver você.",
  ui_story_5046_50461101_13_dialog_content = "O que ela está fazendo aqui?",
  ui_story_5046_50461101_14_dialog_content = "Senhor.",
  ui_story_5046_50461101_15_dialog_content = "Vamos lá fora. Eu quero falar com você a sós.",
  ui_story_5046_50461101_16_dialog_content = "Tá bom.",
  ui_story_5046_50461101_17_dialog_content = "Kristen? O que faz aqui?",
  ui_story_5046_50461101_18_dialog_content = "Você não deveria estar apresentando o caso no Lumo Hall of Justice?",
  ui_story_5046_50461101_19_dialog_content = "Antes de voltar para Lumopolis, queria te perguntar uma coisa.",
  ui_story_5046_50461101_20_dialog_content = "Posso pegar seu pingente emprestado?",
  ui_story_5046_50461101_21_dialog_content = "Meu pingente?",
  ui_story_5046_50461101_22_dialog_content = "Uma vez você me mostrou um pingente com o emblema de sua família.",
  ui_story_5046_50461101_23_dialog_content = "Por que você quer ver?",
  ui_story_5046_50461101_24_dialog_content = "Hum...",
  ui_story_5046_50461101_25_dialog_content = "Eu vi um padrão semelhante ao emblema de sua família enquanto examinava meus arquivos, então queria dar outra olhada em seu pingente, só para ter certeza.",
  ui_story_5046_50461101_26_dialog_content = "...",
  ui_story_5046_50461101_27_dialog_content = "Kristen, Eu vi você crescer. Eu posso dizer em um instante quando você está mentindo.",
  ui_story_5046_50461101_28_dialog_content = "Senhor...",
  ui_story_5046_50461101_29_dialog_content = "Vamos, qual é o motivo?",
  ui_story_5046_50461101_30_dialog_content = "Bem, na verdade... Na verdade, quero provar sua inocência com esse pingente.",
  ui_story_5046_50461101_31_dialog_content = "Provar minha inocência?",
  ui_story_5046_50461101_32_dialog_content = "Soube que você pode estar relacionado a um caso de incêndio criminoso há muitos anos.",
  ui_story_5046_50461101_33_dialog_content = "O pingente que você sempre usa é a chave para eliminar todas as suspeitas que o cercam.",
  ui_story_5046_50461101_34_dialog_content = "Qual é a relação entre o meu pingente e este caso de incêndio criminoso?",
  ui_story_5046_50461101_35_dialog_content = "Disseram-me que seu pingente faz parte de um par e combina com o pingente que tenho aqui na mão.",
  ui_story_5046_50461101_36_dialog_content = "Tudo que eu preciso é que você me empreste o pingente e deixe-me confirmar se os dois pingentes podem ser combinados...",
  ui_story_5046_50461101_37_dialog_content = "Se você está segurando algo relacionado ao caso, você deve entregá-lo ao pessoal responsável para exame detalhado.",
  ui_story_5046_50461101_38_dialog_content = "Questionar diretamente seu superior com evidências... Kristen, não te ensinei nada todos esses anos?",
  ui_story_5046_50461101_39_dialog_content = "Se você não quiser entregá-lo, temos outras maneiras de fazer você cooperar.",
  ui_story_5046_50461101_40_dialog_content = "Hati?",
  ui_story_5046_50461101_41_dialog_content = "Kristen, já que você pegou a suspeita, por que você simplesmente não a coloca na cadeia onde ela pertence?",
  ui_story_5046_50461101_42_dialog_content = "Porque Hati não é suspeita, os casos de incêndio criminoso em Umbraton e a morte do Sr. Hamell não têm nada a ver com ela.",
  ui_story_5046_50461101_43_dialog_content = "Entendo... Então é isso.",
  ui_story_5046_50461101_44_dialog_content = "Kristen, você realmente abrigou uma suspeita e conspirou com ela para enganar seu superior!?",
  ui_story_5046_50461101_45_dialog_content = "eu... eu não...",
  ui_story_5046_50461101_46_dialog_content = "Ela só queria pegar seu pingente emprestado... Você não acha que sua reação parece um pouco exagerada?",
  ui_story_5046_50461101_47_dialog_content = "Poderia ser porque... você é culpado?",
  ui_story_5046_50461101_48_dialog_content = "Você aproveitou o fato de que as velas eram acesas na casa de Hati dia e noite para criar um álibi para si mesmo e usou Kristen como sua testemunha!",
  ui_story_5046_50461101_49_dialog_content = "Depois de cometer um assassinato na casa de Hati, você incendiou a mansão de Kristen não muito longe.",
  ui_story_5046_50461101_50_dialog_content = "Você fingiu estar passando e correu para salvar quem estava lá dentro, criando a ilusão de que a queimadura em seu rosto era resultado de seu heroísmo!",
  ui_story_5046_50461101_51_dialog_content = "Mas, na verdade, a terrível verdade é que a queimadura em seu rosto resultou da briga com a mãe de Hati, que iniciou um incêndio na tentativa de garantir que você morresse com ela!",
  ui_story_5046_50461101_52_dialog_content = "Hmph. Essa é a história que você inventou para me incriminar? É muito emocionante.",
  ui_story_5046_50461101_53_dialog_content = "Esta é a minha opinião sobre o caso com base nas informações disponíveis.",
  ui_story_5046_50461101_54_dialog_content = "Kristen, é nisso que você também acredita?",
  ui_story_5046_50461101_55_dialog_content = "Senhor... eu...",
  ui_story_5046_50461101_56_dialog_content = "PlayerNamededução...",
  ui_story_5046_50461101_57_dialog_content = "Eu...",
  ui_story_5046_50461101_58_dialog_content = "...",
  ui_story_5046_50461101_59_dialog_content = "Hahahahahaha!",
  ui_story_5046_50461101_60_dialog_content = "Kristen, minha senhora ... você realmente é outra coisa.",
  ui_story_5046_50461101_61_dialog_content = "Você prefere acreditar em um celestita que conheceu há apenas um dia do que em seu próprio mentor.",
  ui_story_5046_50461101_62_dialog_content = "Por que você não nos deixa ver o pingente...?",
  ui_story_5046_50461101_63_dialog_content = "Claramente, tudo que você precisa fazer é mostrá-lo para dissipar minhas dúvidas...",
  ui_story_5046_50461101_64_dialog_content = "Já que as sementes da dúvida já foram semeadas em seu coração, qual é o sentido?",
  ui_story_5046_50461101_65_dialog_content = "Quer eu dê a você ou não, você já chegou a um veredicto.",
  ui_story_5046_50461101_66_dialog_content = "Não, isso não é verdade! Todas as deduções requerem evidências para provar sua veracidade...",
  ui_story_5046_50461101_67_dialog_content = "Ok, não diga mais nada.",
  ui_story_5046_50461101_68_dialog_content = "No futuro, não se refira a mim como seu mentor.",
  ui_story_5046_50461101_69_dialog_content = "Já que você escolheu se associar com esse suspeito, a ponta da minha espada agora aponta para você.",
  ui_story_5046_50461101_70_dialog_content = "Senhor... Qual é o significado disso?",
  ui_story_5046_50461101_71_dialog_content = "Kristen, você tem que confiar em seu próprio julgamento!",
  ui_story_5046_50461101_72_dialog_content = "Ele está tentando chantageá-lo emocionalmente! Não importa se ele é seu mentor ou não - você deve manter o senso de justiça em seu coração!",
  ui_story_5046_50461101_73_dialog_content = "Este é quem você é, Kristen— um juiz estagiário de Lumopolis!",
  ui_story_5046_50461101_74_dialog_content = "Eu...",
  ui_story_5046_50461101_75_dialog_content = "Guardas! Kristen conspirou com o celestita para abrigar o suspeito, Hati. Prenda todos eles!",
  ui_story_5046_50461101_76_dialog_content = "Senhor!",
  ui_story_5046_50461102_1_dialog_content = "Suspiro... suspiro...",
  ui_story_5046_50461102_2_dialog_content = "Não acredito que você derrotou todos os meus guardas...",
  ui_story_5046_50461102_3_dialog_content = "De acordo com as leis do Tribunal de Justiça, o que fazemos com aqueles que resistem à prisão e atacam os Guardas Lumo?",
  ui_story_5046_50461102_4_dialog_content = "Bem, Kristen?",
  ui_story_5046_50461102_5_dialog_content = "Senhor, por favor, coopere com a investigação...",
  ui_story_5046_50461102_6_dialog_content = "Concluída a investigação, sua inocência será provada e tudo poderá voltar a ser como era...",
  ui_story_5046_50461102_7_dialog_content = "Tá bom.",
  ui_story_5046_50461102_8_dialog_content = "Huh!? Você concorda!?",
  ui_story_5046_50461102_9_dialog_content = "(Ele estava tão inflexível em não ceder um momento atrás... Por que ele concordou de repente?)",
  ui_story_5046_50461102_10_dialog_content = "Entregue o pingente, rápido!",
  ui_story_5046_50461102_11_dialog_content = "Ele matou minha mãe... Ele tem que pagar pelo que fez!",
  ui_story_5046_50461102_12_dialog_content = "Vou vingar meus pais! Eu vou matá-lo!",
  ui_story_5046_50461102_13_dialog_content = "Acalmar, Hati!",
  ui_story_5046_50461102_14_dialog_content = "você pode contar com Kristen para investigar todo este assunto.",
  ui_story_5046_50461102_15_dialog_content = "Se você usasse a violência para resolver as coisas, você se tornaria um assassino de verdade!",
  ui_story_5046_50461102_16_dialog_content = "O Hati Eu sei que é uma criança gentil e amável cujos pais a amam!",
  ui_story_5046_50461102_17_dialog_content = "Seus pais não gostariam que você os vingasse dessa maneira!",
  ui_story_5046_50461102_18_dialog_content = "Sério... mamãe e papai não iriam querer que eu...?",
  ui_story_5046_50461102_19_dialog_content = "... Hum.",
  ui_story_5046_50461102_20_dialog_content = "Posso entregar o pingente, mas preciso voltar para Umbraton primeiro e provar minha inocência na frente de todos.",
  ui_story_5046_50461102_21_dialog_content = "Vamos lá, Kristen.",
  ui_story_5046_50461102_22_dialog_content = "Quando retornarmos a Umbraton, provarei minha inocência, e então poderemos voltar a como as coisas eram...",
  ui_story_5046_50461102_23_dialog_content = "Hum...",
  ui_story_5046_50461102_24_dialog_content = "Nenhum de vocês se mova, ou eu vou quebrar o pescoço dela.",
  ui_story_5046_50461102_25_dialog_content = "Senhor!? Por que...",
  ui_story_5046_50461102_26_dialog_content = "O que você pensa que está fazendo? Deixa ir Kristen!",
  ui_story_5046_50461102_27_dialog_content = "Durante a perseguição ao suspeito Hati, o suspeito resistiu à prisão e Kristen, infelizmente, morreu no cumprimento do dever...",
  ui_story_5046_50461102_28_dialog_content = "Você é Insano!",
  ui_story_5046_50461102_29_dialog_content = "Desde que Kristen morrer, eu serei o único que sabe o que realmente aconteceu aqui hoje.",
  ui_story_5046_50461102_30_dialog_content = "Vou apresentar um relatório ao Tribunal de Justiça, e Hati será marcado como um assassino implacável e incendiário!",
  ui_story_5046_50461102_31_dialog_content = "E você, celestita, você se tornará cúmplice dela!",
  ui_story_5046_50461102_32_dialog_content = "A essa altura, ninguém acreditará em nada do que você disser.",
  ui_story_5046_50461102_33_dialog_content = "Você realmente acha que pode encobrir a verdade!?",
  ui_story_5046_50461102_34_dialog_content = "Você realmente acha que só você pode nos incriminar com suas mentiras!?",
  ui_story_5046_50461102_35_dialog_content = "Verdades, mentiras... O que importa no final?",
  ui_story_5046_50461102_36_dialog_content = "O importante é que continuo minha vida de cavaleiro, seguro em Lumópolis, sem maiores incidentes...",
  ui_story_5046_50461102_37_dialog_content = "Quanto à verdade... ela será enterrada com seus ossos, nas profundezas da terra para sempre!",
  ui_story_5046_50461102_38_dialog_content = "Senhor... Como pode dizer isso?",
  ui_story_5046_50461102_39_dialog_content = "Você não me ensinou sempre a defender a justiça e lutar pela verdade? Por que? Por que você diria tal coisa...?",
  ui_story_5046_50461102_40_dialog_content = "Kristen, você me considera uma pessoa importante em seu coração?",
  ui_story_5046_50461102_41_dialog_content = "Ahh!",
  ui_story_5046_50461102_42_dialog_content = "Já que eu significo tanto para você, você não faria qualquer coisa para manter minha reputação e posição, mesmo que isso significasse morrer por mim?",
  ui_story_5046_50461102_43_dialog_content = "Senhor... Senhor, o que está dizendo...?",
  ui_story_5046_50461102_44_dialog_content = "Você arriscou sua vida para salvar Kristen todos aqueles anos atrás! Como você pode ser tão cruel a ponto de ameaçar matá-la?!",
  ui_story_5046_50461102_45_dialog_content = "(Hati! Estou falando com você usando minha habilidade psíquica! Precisamos encontrar uma maneira de salvar Kristen!)",
  ui_story_5046_50461102_46_dialog_content = "PlayerName?",
  ui_story_5046_50461102_47_dialog_content = "(Vou distrair Zenas, você encontra uma oportunidade de se aproximar dele!)",
  ui_story_5046_50461102_48_dialog_content = "Entendido.",
  ui_story_5046_50461102_49_dialog_content = "Eu a salvei? Você quer dizer aquele fogo? Suponho que ela me deve ainda mais, então. Agora ela tem uma chance de me retribuir.",
  ui_story_5046_50461102_50_dialog_content = "A menos que minha dedução anterior estivesse totalmente errada, você arriscou sua vida para correr para as chamas e salvar Kristen...",
  ui_story_5046_50461102_51_dialog_content = "Então, como você pode pensar em machucá-la agora!?",
  ui_story_5046_50461102_52_dialog_content = "Sim, a garotinha que sacrifiquei minha vida para salvar e ensinei por tantos anos...",
  ui_story_5046_50461102_53_dialog_content = "Como eu poderia me forçar a machucá-la?",
  ui_story_5046_50461102_54_dialog_content = "Senhor...",
  ui_story_5046_50461102_55_dialog_content = "Mas Kristen, minha jovem...",
  ui_story_5046_50461102_56_dialog_content = "Desde o começo, você era apenas um peão para mim.",
  ui_story_5046_50461102_57_dialog_content = "E isso inclui o fogo. Tudo fazia parte do meu plano.",
  ui_story_5046_50461102_58_dialog_content = "Quê?!",
  ui_story_5046_50461102_59_dialog_content = "Há muito tempo eu queria subir nas costas de um nobre poderoso e entrar na sociedade de Lumópolis. Sua mansão estava por perto.",
  ui_story_5046_50461102_60_dialog_content = "Eu aprendi rapidamente que todos que trabalhavam na mansão naquele dia eram um idiota fraco, então eu subornei a ajuda e ateei fogo ao local.",
  ui_story_5046_50461102_61_dialog_content = "Fingi estar passando e fingi que estava desesperadamente arriscando a vida e os membros para resgatar essa pobre e nobre senhora de Lumópolis.",
  ui_story_5046_50461102_62_dialog_content = "Com certeza, sua família ficou muito grata a mim, permitindo que eu entrasse tranquilamente na sociedade de Lumopolis e vivesse a vida que sempre sonhei.",
  ui_story_5046_50461102_63_dialog_content = "Foi tudo graças a você, meu... não, Kristen.",
  ui_story_5046_50461102_X63_dialog_content = "Olha, queimei meu rosto para te salvar!",
  ui_story_5046_50461102_64_dialog_content = "Você... Você é abominável! Eu não vou poupar você!",
  ui_story_5046_50461102_65_dialog_content = "Valeu a pena desfigurar-se apenas para cair nas boas graças da nobreza de Lumópolis?",
  ui_story_5046_50461102_66_dialog_content = "Você já experimentou o poder, Caelestita?",
  ui_story_5046_50461102_67_dialog_content = "Poder pode ser trocado por dinheiro, mas dinheiro não necessariamente compra poder.",
  ui_story_5046_50461102_68_dialog_content = "Enquanto você tiver poder, nada estará além do seu alcance e ninguém poderá ficar no seu caminho!",
  ui_story_5046_50461102_69_dialog_content = "Não é mesmo, Kristen?",
  ui_story_5046_50461102_70_dialog_content = "Você nasceu um nobre de Lumopolis. Deve ser uma sensação maravilhosa, não?",
  ui_story_5046_50461102_71_dialog_content = "Inquieta jaz a cabeça que usa uma coroa...",
  ui_story_5046_50461102_72_dialog_content = "Os nobres devem possuir um caráter nobre.",
  ui_story_5046_50461102_73_dialog_content = "Aqueles que usam seu status nobre para ganho pessoal não são dignos de serem chamados de nobres.",
  ui_story_5046_50461102_74_dialog_content = "Hahahahaha!",
  ui_story_5046_50461102_75_dialog_content = "Kristen, você realmente acreditou em cada clichê vazio que eu te ensinei, não é?",
  ui_story_5046_50461102_76_dialog_content = "Você realmente acredita que todos os nobres são como você, tão puros e nobres quanto o lírio?",
  ui_story_5046_50461102_77_dialog_content = "Bom, chega de conversa.",
  ui_story_5046_50461102_78_dialog_content = "Hum? Onde está a Hati!?",
  ui_story_5046_50461102_79_dialog_content = "...",
  ui_story_5046_50461102_80_dialog_content = "(Agora, Hati!)",
  ui_story_5046_50461102_81_dialog_content = "Hyaa—!",
  ui_story_5046_50461102_82_dialog_content = "Ahh!",
  ui_story_5046_50461102_83_dialog_content = "De onde você veio!?",
  ui_story_5046_50461102_84_dialog_content = "Ugh...",
  ui_story_5046_50461102_85_dialog_content = "Kristen, você está bem!?",
  ui_story_5046_50461102_86_dialog_content = "Deixe-me ajudá-lo... Você ainda consegue ficar de pé?",
  ui_story_5046_50461102_87_dialog_content = "PlayerName... Boo-hoo...",
  ui_story_5046_50461102_88_dialog_content = "Venha aqui.",
  ui_story_5046_50461102_89_dialog_content = "Não há mais reféns. Basta entregar o pingente.",
  ui_story_5046_50461102_90_dialog_content = "Ou eu tenho que bater um pouco de honestidade em você?",
  ui_story_5046_50461102_91_dialog_content = "Tudo bem... Aqui, aqui está você.",
  ui_story_5046_50461102_92_dialog_content = "Você quer o pingente...",
  ui_story_5046_50461102_93_dialog_content = "Você pode trocá-lo por sua vida!",
  ui_story_5046_50461102_94_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5046_50461102_95_dialog_content = "!!!",
  ui_story_5046_50461102_96_dialog_content = "Ahh!",
  ui_story_5046_50461102_97_dialog_content = "Fingindo entregar o pingente e lançando um ataque furtivo... Hmph!",
  ui_story_5046_50461102_98_dialog_content = "Agora que estamos sem nossas armas, quem sabe quem vai ganhar?",
  ui_story_5046_50461102_99_dialog_content = "Kristen e os celestitas têm pouco poder de combate, então agora...",
  ui_story_5046_50461102_100_dialog_content = "É só você e eu.",
  ui_story_5046_50461102_101_dialog_content = "Depois que eu lidar com você, eu vou cuidar daqueles dois...",
  ui_story_5046_50461102_102_dialog_content = "Hahahahaha!",
  ui_story_5046_50461102_103_dialog_content = "...",
  ui_story_5046_50461102_104_dialog_content = "Minha espada!",
  ui_story_5046_50461102_105_dialog_content = "Hmph! Não importa, este machado serve.",
  ui_story_5046_50461102_106_dialog_content = "Você não é digno dessa espada com todo o sangue em suas mãos.",
  ui_story_5046_50461102_X106_dialog_content = "Uma espada representa a justiça, mas você é mau.",
  ui_story_5046_50461102_107_dialog_content = "Você acha que a justiça sempre prevalecerá contra o mal?",
  ui_story_5046_50461102_108_dialog_content = "De nada.",
  ui_story_5046_50461102_109_dialog_content = "Não tenha tanta certeza de que vai me vencer.",
  ui_story_5046_50461102_110_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_5046_50461102_111_dialog_content = "Vá para o inferno!!!",
  ui_story_5046_50461102_112_dialog_content = "Hyaaa!",
  ui_story_5046_50461102_113_dialog_content = "Aaaaah!",
  ui_story_5046_50461102_114_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5046_50461102_115_dialog_content = "...",
  ui_story_5046_50461102_116_dialog_content = "Sente isso? Essa é a sua espada pressionada contra o seu pescoço.",
  ui_story_5046_50461102_117_dialog_content = "Eu poderia cortar sua garganta em uma fração de segundo e vingar minha mãe.",
  ui_story_5046_50461102_118_dialog_content = "!!!",
  ui_story_5046_50461102_119_dialog_content = "Mas não vou.",
  ui_story_5046_50461102_120_dialog_content = "Porque PlayerName não quer que eu.",
  ui_story_5046_50461102_121_dialog_content = "Mamãe e papai também não iriam querer seu sangue em minhas mãos.",
  ui_story_5046_50461102_122_dialog_content = "Ei você. Isso é Kristen, certo?",
  ui_story_5046_50461102_123_dialog_content = "Ugh...",
  ui_story_5046_50461102_124_dialog_content = "Pare de chorar já. Antes de levá-lo embora, posso pegar o pingente?",
  ui_story_5046_50461102_125_dialog_content = "Pingente? Que pingente? Você está planejando me roubar?",
  ui_story_5046_50461102_126_dialog_content = "Por que você ainda não quer confessar seus crimes!?",
  ui_story_5046_50461102_127_dialog_content = "Eu não entendo o que você está falando.",
  ui_story_5046_50461102_128_dialog_content = "Senhor... Não, Zenas.",
  ui_story_5046_50461102_129_dialog_content = "De acordo com os resultados desta investigação, você está ligado a um caso de homicídio e dois incêndios criminosos ocorridos há muitos anos. Por favor, coopere comigo.",
  ui_story_5046_50461102_130_dialog_content = "(Kristen recuperado tão rapidamente. Ela estava chorando agora há pouco...)",
  ui_story_5046_50461102_131_dialog_content = "Hunf...",
  ui_story_5046_50461102_132_dialog_content = "Você ainda é a garota teimosa e forte que sempre foi...",
  ui_story_5046_50461102_133_dialog_content = "Não quero ouvir mais nada de você agora. Se você tem algo a dizer, guarde para o Tribunal de Justiça.",
  ui_story_5046_50461102_134_dialog_content = "Se você quer saber, eu realmente não queria matá-lo agora. Eu resgatei você naquela época, e você me acompanhou por tantos anos.",
  ui_story_5046_50461102_135_dialog_content = "Como eu poderia te matar?",
  ui_story_5046_50461102_136_dialog_content = "Por que você ainda está tentando me enganar?",
  ui_story_5046_50461102_137_dialog_content = "Com tudo o que eu lhe disse, você pode dizer o que é verdadeiro e o que é falso?",
  ui_story_5046_50461102_138_dialog_content = "Para!",
  ui_story_5046_50461102_139_dialog_content = "Mentiroso! Você não tem mais o direito de me repreender!",
  ui_story_5046_50461102_140_dialog_content = "De agora em diante, julgarei em quem confiar e em quem não confiar.",
  ui_story_5046_50461102_141_dialog_content = "Eu cresci. Não sou mais a garotinha protegida que precisa de sua orientação.",
  ui_story_5046_50461102_142_dialog_content = "Quanto ao seu crime, o Tribunal de Justiça chegará a um veredicto justo.",
  ui_story_5046_50461102_143_dialog_content = "Desculpe, PlayerName. Desculpe por perder a compostura na sua frente...",
  ui_story_5046_50461102_144_dialog_content = "Vou escoltar Zenas de volta a Lumopolis imediatamente e informá-lo sobre o resultado do julgamento no devido tempo.",
  ui_story_5046_50461102_145_dialog_content = "Meu pingente.",
  ui_story_5046_50461102_146_dialog_content = "Fique tranquilo, quando eu encontrar o pingente, eu o entregarei pessoalmente.",
  ui_story_5046_50461201_1_dialog_content = "<color=#e8d9bb>Vários dias depois...</color>",
  ui_story_5046_50461201_2_dialog_content = "Kristen!",
  ui_story_5046_50461201_3_dialog_content = "Bom dia, PlayerName.",
  ui_story_5046_50461201_4_dialog_content = "Já faz muito tempo, PlayerName.",
  ui_story_5046_50461201_5_dialog_content = "Oh, Pittman!",
  ui_story_5046_50461201_6_dialog_content = "A propósito, é Hati aqui? Ouvi dizer que ela veio visitar o Colosso.",
  ui_story_5046_50461201_7_dialog_content = "Kristen.",
  ui_story_5046_50461201_8_dialog_content = "Aqui você vai. Este é o pingente.",
  ui_story_5046_50461201_9_dialog_content = "Pingente da mamãe...",
  ui_story_5046_50461201_10_dialog_content = "Zenas agora foi entregue a mim para mais interrogatório.",
  ui_story_5046_50461201_11_dialog_content = "Graças à você, PlayerName, também encontramos outras pistas vitais para <color=#FFB400>esse outro caso</color>.",
  ui_story_5046_50461201_12_dialog_content = "Haha... Fico feliz em poder ajudar.",
  ui_story_5046_50461201_13_dialog_content = "Quem teria pensado que meu sequestro causaria tanto drama?",
  ui_story_5046_50461201_14_dialog_content = "Aham…",
  ui_story_5046_50461201_15_dialog_content = "Oh sim. Tenho algumas perguntas a fazer...",
  ui_story_5046_50461201_16_option_content = "Quem foi o verdadeiro culpado naqueles casos de incêndio criminoso nos últimos dois meses?",
  ui_story_5046_50461201_17_dialog_content = "Nossa investigação mostrou que os casos de incêndio criminoso em Umbraton nos últimos dois meses usaram o mesmo combustível, incluindo o ensaio no orfanato.",
  ui_story_5046_50461201_18_dialog_content = "Enviei alguém para investigar este combustível e parece que existem apenas algumas lojas que o vendem.",
  ui_story_5046_50461201_19_dialog_content = "O dono da loja identificou a Zenas como tendo adquirido grandes quantidades deste combustível há dois meses.",
  ui_story_5046_50461201_20_dialog_content = "Zenas também admitiu que iniciou todos esses incêndios com a intenção de silenciar as vítimas.",
  ui_story_5046_50461201_21_dialog_content = "Mas por que ele matou aquelas pessoas?",
  ui_story_5046_50461201_22_dialog_content = "Está relacionado com <color=#FFB400>Aquele caso</color>.",
  ui_story_5046_50461201_23_dialog_content = "Naquela época, cinco funcionários, incluindo Hamell, usaram o orfanato como disfarce para enviar crianças para experimentos.",
  ui_story_5046_50461201_24_dialog_content = "Com exceção de Zenas e Hamell, os outros três órfãos que sobreviveram ao incêndio no orfanato não estavam muito bem.",
  ui_story_5046_50461201_25_dialog_content = "Então os três usaram seu passado compartilhado para chantagear Zenas, e Zenas foi forçado a pagar por seu silêncio.",
  ui_story_5046_50461201_26_dialog_content = "Mas eles exigiam cada vez mais...",
  ui_story_5046_50461201_27_dialog_content = "E então Zenas os silenciou permanentemente.",
  ui_story_5046_50461201_28_dialog_content = "Correto.",
  ui_story_5046_50461201_29_dialog_content = "Quem matou o Sr. Hamell?",
  ui_story_5046_50461201_30_dialog_content = "Zenas admitiu ter iniciado os incêndios e matado os três ex-funcionários do orfanato.",
  ui_story_5046_50461201_31_dialog_content = "Cinco pessoas trabalhavam no orfanato envolvidas no caso, incluindo Zenas.",
  ui_story_5046_50461201_32_dialog_content = "Então, Zenas matou o Sr. Hamell?",
  ui_story_5046_50461201_33_dialog_content = "É altamente suspeito, mas atualmente não há evidências e ele não admitiu isso.",
  ui_story_5046_50461201_34_dialog_content = "Ele é realmente responsável por tantos assassinatos...?",
  ui_story_5046_50461201_35_dialog_content = "(Kristen não parece que ela está levando isso bem...)",
  ui_story_5046_50461201_36_dialog_content = "Kristen, você está bem?",
  ui_story_5046_50461201_37_dialog_content = "Você realmente me vê como sendo tão fraco, PlayerName?",
  ui_story_5046_50461201_38_dialog_content = "N-Não, não foi isso que eu quis dizer! Eu acabei de...",
  ui_story_5046_50461201_39_dialog_content = "Tô bem.",
  ui_story_5046_50461201_40_dialog_content = "Eu me lembro de tudo que você me disse naquele dia, PlayerName.",
  ui_story_5046_50461201_41_dialog_content = "PlayerName disse que eu seria um ótimo juiz no futuro.",
  ui_story_5046_50461201_42_dialog_content = "Com tantas pessoas ao meu redor, me incentivando e apoiando o tempo todo, não há como eu me sentir triste por estar sozinho.",
  ui_story_5046_50461201_43_dialog_content = "Embora eu ainda tenha um longo caminho a percorrer antes de atingir meu objetivo, farei o possível para seguir em frente.",
  ui_story_5046_50461201_44_dialog_content = "Porque eu realmente sou ótimo! não sou eu, PlayerName?",
  ui_story_5046_50461201_45_dialog_content = "estamos falando sobre Kristen aqui, certo? Claro que você é!",
  ui_story_5046_50461201_46_dialog_content = "Concordo.",
  ui_story_5046_50461201_47_dialog_content = "Eu concordo.",
  ui_story_5046_50461201_48_dialog_content = "Oh! Eu esqueci o Sr. Pittman ainda estava aqui...",
  ui_story_5046_50461201_49_dialog_content = "aham... dei Hati seu pingente, então, a menos que você tenha algo mais para discutir comigo, permita-me ir embora.",
  ui_story_5046_50461201_50_dialog_content = "Adeus.",
  ui_story_5046_50461201_51_dialog_content = "...",
  ui_story_5046_50461201_52_dialog_content = "Sentindo nervoso, Hati?",
  ui_story_5046_50461201_53_dialog_content = "Uhum.",
  ui_story_5046_50461201_54_dialog_content = "Esses dois pingentes são um par. Minha mãe me deu a metade na época.",
  ui_story_5046_50461201_55_dialog_content = "Mamãe disse que enquanto eu juntar essas duas metades, nossa família estará sempre unida...",
  ui_story_5046_50461201_56_dialog_content = "Mas mamãe e eu estamos separados há tanto tempo... boo-hoo...",
  ui_story_5046_50461201_57_dialog_content = "Mãe... *soluço*",
  ui_story_5046_50461201_58_dialog_content = "Pronto, pronto, não chore...",
  ui_story_5046_50461201_59_dialog_content = "(Está tudo bem Hati, não chore.)",
  ui_story_5046_50461201_60_dialog_content = "(Deixe a mamãe cantar para você dormir...)",
  ui_story_5046_50461201_61_dialog_content = "(Lalala ♪ Lalala ♪)",
  ui_story_5046_50461201_62_dialog_content = "(Hati, vendo você dormir tão profundamente, eu gostaria que este momento durasse por toda a eternidade.)",
  ui_story_5046_50461201_63_dialog_content = "(Mas também quero ver você crescer. Aposto que você acaba se parecendo cada vez mais com Fenrir.)",
  ui_story_5046_50461201_64_dialog_content = "(Você era apenas uma bolinha fofa quando nasceu, mas agora está quase no meu joelho.)",
  ui_story_5046_50461201_65_dialog_content = "(Você pode estar mais velho agora, mas ainda gosta que eu o segure em meus braços e o coloque na cama, e quando você acorda, ainda me pede para carregá-lo à mesa para jantar...)",
  ui_story_5046_50461201_66_dialog_content = "(Eu mal posso levantá-lo agora, muito menos andar com você!)",
  ui_story_5046_50461201_67_dialog_content = "(Quando eu estiver velho e não puder mais andar, você vai me carregar para a cama e me colocar no banquinho...)",
  ui_story_5046_50461201_68_dialog_content = "(Hati... Há tanto que eu quero dizer a você ...)",
  ui_story_5046_50461201_69_dialog_content = "(Espero poder te assistir e crescer com você, sempre...)",
  ui_story_5046_50461201_70_dialog_content = "(...)",
  ui_story_5046_50461201_71_dialog_content = "(...)",
  ui_story_5046_50461201_72_dialog_content = "(...)",
  ui_story_5046_50461201_73_dialog_content = "...",
  ui_story_5046_50461201_74_dialog_content = "Não tenho mais medo de você, nem terei medo... desse poder.",
  ui_story_5046_50461201_75_dialog_content = "Eu posso me aceitar completamente agora.",
  ui_story_5046_50461201_76_dialog_content = "Quer seja o Hati que costumava temer seu poder e se odiar.",
  ui_story_5046_50461201_77_dialog_content = "Ou o Hati que usa suas chamas para proteger as pessoas importantes para ela.",
  ui_story_5046_50461201_78_dialog_content = "Não importa qual Hati é, eles são todos eu.",
  ui_story_5046_50461201_79_dialog_content = "(Estou... pronto para me aceitar...?)",
  ui_story_5046_50461201_80_dialog_content = "Tô pronta.",
  ui_story_5046_50461202_1_dialog_content = "Eu venci?",
  ui_story_5046_50461202_2_dialog_content = "Você é...?",
  ui_story_5046_50461202_3_dialog_content = "(Você pode se aceitar inteiramente agora.)",
  ui_story_5046_50461202_4_dialog_content = "(Você alcançou uma reconciliação consigo mesmo.)",
  ui_story_5046_50461202_5_dialog_content = "(Estou muito feliz em ver que você pode usar seu poder tão bem.)",
  ui_story_5046_50461202_6_dialog_content = "(Eu deveria sair agora.)",
  ui_story_5046_50461202_7_dialog_content = "Eu posso sentir o poder das chamas...",
  ui_story_5046_50461202_8_dialog_content = "Este poder está constantemente inundando meu corpo...",
  ui_story_5046_50461202_9_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5046_50461202_10_dialog_content = "Uma chama... Uma chama criada pelos meus pensamentos...",
  ui_story_5046_50461202_11_dialog_content = "É quentinho.",
  ui_story_5046_50461202_12_dialog_content = "PlayerName?",
  ui_story_5046_50461202_13_dialog_content = "Você está acordado? Eu estava cantarolando uma música quando você adormeceu.",
  ui_story_5046_50461202_14_dialog_content = "Você parecia tão tranquilo, eu não queria acordá-lo.",
  ui_story_5046_50461202_15_dialog_content = "Sonhei com quando era criança. Eu acidentalmente queimei algo com minhas chamas e minha mãe me repreendeu.",
  ui_story_5046_50461202_16_dialog_content = "Ela me abraçou e cantou uma canção de ninar enquanto me embalava para dormir.",
  ui_story_5046_50461202_17_dialog_content = "Depois que adormeci, vi...",
  ui_story_5046_50461202_18_dialog_content = "Meu demônio interior.",
  ui_story_5046_50461202_19_dialog_content = "Eu disse que não tinha mais medo disso.",
  ui_story_5046_50461202_20_dialog_content = "E depois?",
  ui_story_5046_50461202_21_dialog_content = "Eu... o derrotei.",
  ui_story_5046_50461202_22_dialog_content = "Não tenho mais medo das chamas. Eu posso sentir o calor deles me envolvendo.",
  ui_story_5046_50461202_23_dialog_content = "É como ser abraçado por minha mãe e meu pai.",
  ui_story_5046_50461202_24_dialog_content = "Deve ter sido um sonho bom.",
  ui_story_5046_50461202_25_dialog_content = "Eu ouso enfrentar qualquer coisa. Eu herdei isso da minha mãe e do meu pai.",
  ui_story_5046_50461202_26_dialog_content = "E de você, PlayerName.",
  ui_story_5046_50461202_27_dialog_content = "Obrigado por estar lá para mim.",
  ui_story_5046_50461202_28_dialog_content = "Você não precisa me agradecer. Somos amigos, afinal.",
  ui_story_5046_50461202_29_dialog_content = "Quero juntar as duas metades do pingente agora. PlayerName, você vai se juntar a mim?",
  ui_story_5046_50461202_30_dialog_content = "Claro! Vamos fazer isso juntos!",
  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>Clique-</color>",
  ui_story_5046_50461202_32_dialog_content = "Algo parece ter saído do fundo depois de juntar as duas metades...",
  ui_story_5046_50461202_33_dialog_content = "<color=#e8d9bb>*desdobramento do papel*</color>",
  ui_story_5046_50461202_34_dialog_content = "É... É um...",
  ui_story_5046_50461202_35_dialog_content = "Tantas fotos...",
  ui_story_5046_50461202_36_dialog_content = "Esta é... uma foto da minha família que desenhei quando era pequeno.",
  ui_story_5046_50461202_37_dialog_content = "Esta é a última coisa que eu esperava encontrar no pingente.",
  ui_story_5046_50461202_38_dialog_content = "Algumas de suas fotos de infância também estão aqui!",
  ui_story_5046_50461202_39_dialog_content = "Tem mais duas fotos aqui...",
  ui_story_5046_50461202_40_dialog_content = "Esta deve ser sua mãe. Então, isso deve ser...",
  ui_story_5046_50461202_41_dialog_content = "Pai...",
  ui_story_5046_50461202_42_dialog_content = "Huh? Esse é o seu pai?",
  ui_story_5046_50461202_43_dialog_content = "Parece que estão em um laboratório...",
  ui_story_5046_50461202_44_dialog_content = "Eu...",
  ui_story_5046_50461202_45_dialog_content = "Eu nunca conheci meu pai.",
  ui_story_5046_50461202_46_dialog_content = "Mas olhando essa foto, acho que deve ser ele...",
  ui_story_5046_50461202_47_dialog_content = "\"Enquanto você juntar essas duas metades, nossa família sempre estará unida...\"",
  ui_story_5046_50461202_48_dialog_content = "Agora nossa família estará unida para sempre.",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>Em algum lugar de Umbraton</color>",
  ui_story_5046_50461202_50_dialog_content = "Depois de entregar a carta a Zenas, eu o segui.",
  ui_story_5046_50461202_51_dialog_content = "Vocês ficam por aqui e vasculham cada centímetro do lugar.",
  ui_story_5046_50461202_52_dialog_content = "Sim, senhor!",
  ui_story_5046_50461202_53_dialog_content = "...",
  ui_story_5046_50461202_54_dialog_content = "(Por que ele está indo para cá...? Ele está indo para o orfanato?)",
  ui_story_5046_50461202_55_dialog_content = "Já faz muito tempo, velho amigo.",
  ui_story_5046_50461202_56_dialog_content = "É você.",
  ui_story_5046_50461202_57_dialog_content = "(Hamell? Essa coisa em sua mão poderia ser o que o Shadowlord quer?)",
  ui_story_5046_50461202_58_dialog_content = "Não está feliz em ver seu velho amigo?",
  ui_story_5046_50461202_59_dialog_content = "Só estou com medo de que você não esteja aqui porque queria me ver, mas porque quer algo de mim.",
  ui_story_5046_50461202_60_dialog_content = "Não seja tão cínico. Dessa vez estou aqui para trazer uma novidade para vocês.",
  ui_story_5046_50461202_61_dialog_content = "Então, ela pediu para se encontrar. O que isso tem a ver comigo?",
  ui_story_5046_50461202_62_dialog_content = "André e os outros dois estão mortos. Mais cedo ou mais tarde, será a nossa vez.",
  ui_story_5046_50461202_63_dialog_content = "Em vez de esperar que ela venha à nossa porta, vamos cumprimentá-la.",
  ui_story_5046_50461202_64_dialog_content = "(Parece que Hamell continua olhando para lá inconscientemente.)",
  ui_story_5046_50461202_65_dialog_content = "Eu sei que você quer perguntar por que eu não fiz nada.",
  ui_story_5046_50461202_66_dialog_content = "Nesta carta dela, ela me chama pelo nome. Se alguém descobrisse a conexão entre nós, isso poderia tornar as coisas muito mais complicadas.",
  ui_story_5046_50461202_67_dialog_content = "Se isso acontecer, não poderei mais protegê-lo. Quem pode dizer... você pode até ser descoberto também.",
  ui_story_5046_50461202_68_dialog_content = "Você está me ameaçando...",
  ui_story_5046_50461202_69_dialog_content = "Todos nós precisamos cuidar de nós mesmos. Este é o endereço.",
  ui_story_5046_50461202_70_dialog_content = "Tudo bem, eu posso te ajudar com isso, mas você precisa encontrar algumas pessoas para me ajudar.",
  ui_story_5046_50461202_71_dialog_content = "Depois que Zenas saiu, vasculhei enquanto Hamell estava dormindo e o encontrei.",
  ui_story_5046_50461202_72_dialog_content = "Um registro de suas datas de transação, preços e informações do comprador.",
  ui_story_5046_50461202_73_dialog_content = "Impressionante.",
  ui_story_5046_50461202_74_dialog_content = "Muitos anos atrás, Umbraton era uma terra caótica e sem lei. O povo de Lumópolis o tratava como um depósito de lixo onde enterravam seus pecados.",
  ui_story_5046_50461202_75_dialog_content = "Agora que sou o guardião de Umbraton, não vou deixar que volte a ser como era.",
  ui_story_5046_50461202_76_dialog_content = "As sombras conhecem todos os segredos.",
  ui_story_5046_50461202_77_dialog_content = "Entendido, Senhor das Sombras.",
  ui_story_5046_50461202_78_dialog_content = "Você se saiu bem nos últimos dias.",
  ui_story_5046_50461202_79_dialog_content = "<color=#e8d9bb>Prisão de Lumopolis</color>",
  ui_story_5046_50461202_80_dialog_content = "...",
  ui_story_5046_50461202_81_dialog_content = "Lá vem minha jovem.",
  ui_story_5046_50461202_82_dialog_content = "Está tão frio e sombrio aqui. Este não é lugar para uma mocinha como você.",
  ui_story_5046_50461202_83_dialog_content = "Vim me despedir de você e do meu passado.",
  ui_story_5046_50461202_84_dialog_content = "Eu sempre costumava segui-lo cegamente, progredindo na direção que você queria, tanto em meus pensamentos quanto em minhas ações.",
  ui_story_5046_50461202_85_dialog_content = "Eu era seu fantoche.",
  ui_story_5046_50461202_86_dialog_content = "Moça, nunca a forcei a fazer nada que não quisesse. O que está em sua mente?",
  ui_story_5046_50461202_87_dialog_content = "Me deixa doente saber que você estava por trás de tudo isso, mas você persiste em fingir essa atitude indiferente!",
  ui_story_5046_50461202_88_dialog_content = "Você é uma escória completa e absoluta!",
  ui_story_5046_50461202_89_dialog_content = "...",
  ui_story_5046_50461202_90_dialog_content = "Desculpe, eu me esqueci.",
  ui_story_5046_50461202_91_dialog_content = "O pingente.",
  ui_story_5046_50461202_92_dialog_content = "O que tem nesse pingente?",
  ui_story_5046_50461202_93_dialog_content = "Isso é tudo que você queria perguntar?",
  ui_story_5046_50461202_94_dialog_content = "...",
  ui_story_5046_50461202_95_dialog_content = "Paguei tanto por este pingente.",
  ui_story_5046_50461202_96_dialog_content = "Quero saber se há algo escondido dentro... O que estou procurando.",
  ui_story_5046_50461202_97_dialog_content = "Havia apenas algumas fotos da família de Hati nele.",
  ui_story_5046_50461202_98_dialog_content = "Apenas algumas fotos?",
  ui_story_5046_50461202_99_dialog_content = "Apenas algumas fotos.",
  ui_story_5046_50461202_100_dialog_content = "Hahahahahaha!",
  ui_story_5046_50461202_101_dialog_content = "Bem eu nunca...",
  ui_story_5046_50461202_102_dialog_content = "Eu não esperava que as coisas acabassem assim...",
  ui_story_5046_50461202_103_dialog_content = "Se você não tem mais nada a dizer...",
  ui_story_5046_50461202_104_dialog_content = "Eu vou me despedir.",
  ui_story_5046_50461202_105_dialog_content = "...",
  ui_story_5046_50461202_106_dialog_content = "Esta é a última vez que nos veremos.",
  ui_story_5046_50461202_107_dialog_content = "Adeus senhor.",
  ui_story_5046_50461202_108_dialog_content = "(Adeus... ao meu passado.)",
  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>Cerimônia do Dia da Conclusão do Orfanato Umbraton</color>",
  ui_story_5046_50461202_110_dialog_content = "A conclusão deste orfanato simboliza os esforços meticulosos de incontáveis cidadãos atenciosos de Umbraton. Por favor, permita-me aproveitar esta oportunidade para expressar minha gratidão a essas pessoas mais uma vez!",
  ui_story_5046_50461202_111_dialog_content = "Eu declaro que o Orfanato Umbraton foi oficialmente concluído!",
  ui_story_5046_50461202_112_dialog_content = "Parabéns!",
  ui_story_5046_50461202_113_dialog_content = "Que triunfo! É magnífico!",
  ui_story_5046_50461202_114_dialog_content = "Espero que este orfanato seja fonte de muitas lembranças felizes, e que os erros do passado jamais se repitam.",
  ui_story_5046_50461202_115_dialog_content = "Este orfanato está agora sob a supervisão do Shadowlord de Umbraton, então você não precisa se preocupar com isso, PlayerName.",
  ui_story_5046_50461202_116_dialog_content = "Grime!?",
  ui_story_5046_50461202_117_dialog_content = "No dia em que Zenas foi preso, Hati e fui ao Firefly Bar te procurar, mas você não estava lá...",
  ui_story_5046_50461202_118_dialog_content = "Eu tinha negócios para cuidar.",
  ui_story_5046_50461202_119_dialog_content = "A propósito, onde está Hati?",
  ui_story_5046_50461202_120_dialog_content = "Ela é...",
  ui_story_5046_50461202_121_dialog_content = "Agora, vamos dar as boas-vindas ao herói do combate a incêndios do nosso orfanato...Hati!",
  ui_story_5046_50461202_122_dialog_content = "...",
  ui_story_5046_50461202_123_dialog_content = "As habilidades heroicas de combate a incêndios de Hati evitaram desastres em Umbraton nos últimos dois meses, apagando grandes e pequenos incêndios.",
  ui_story_5046_50461202_124_dialog_content = "Alguns dias atrás, uma garotinha ficou presa em um incêndio no ensaio para esta cerimônia...",
  ui_story_5046_50461202_125_dialog_content = "Hati correu sem pensar duas vezes e a resgatou...",
  ui_story_5046_50461202_126_dialog_content = "Então, ela não é uma incendiária...",
  ui_story_5046_50461202_127_dialog_content = "Ela realmente estava lá salvando alguém?",
  ui_story_5046_50461202_128_dialog_content = "Ela é tão corajosa, como uma grande heroína...",
  ui_story_5046_50461202_129_dialog_content = "Perder Bethel é tão pensativo. Agora ninguém em Umbraton vai tratar Hati como um criminoso.",
  ui_story_5046_50461202_130_dialog_content = "Ela é inteligente. Eu não conseguiria lidar com tudo tão bem, mesmo que tivesse três cérebros.",
  ui_story_5046_50461202_131_dialog_content = "Hehe... Você tem suas próprias forças, PlayerName. Não se esqueça, ninguém é perfeito.",
  ui_story_5046_50461202_132_dialog_content = "Isso é tão irritante.",
  ui_story_5046_50461202_133_dialog_content = "Ei... Você saiu correndo do palco tão rápido.",
  ui_story_5046_50461202_134_dialog_content = "Meu cabelo estava em pé enquanto eu estava lá em cima.",
  ui_story_5046_50461202_135_dialog_content = "Você vai se acostumar com isso. Afinal, você não está no mundo exterior há tanto tempo e ainda há muitas coisas para aprender aqui.",
  ui_story_5046_50461202_136_dialog_content = "Hum...",
  ui_story_5046_50461202_137_dialog_content = "Hati, quais são seus planos para o futuro?",
  ui_story_5046_50461202_138_dialog_content = "Eu...",
  ui_story_5046_50461202_139_dialog_content = "Não sei.",
  ui_story_5046_50461202_140_dialog_content = "Encontrar minhas memórias perdidas de minha mãe costumava ser meu objetivo.",
  ui_story_5046_50461202_141_dialog_content = "Mas agora esse objetivo foi alcançado...",
  ui_story_5046_50461202_142_dialog_content = "Não sei o que mais devo fazer.",
  ui_story_5046_50461202_143_dialog_content = "Isso não importa. A vida é essencialmente apenas um objetivo após o outro!",
  ui_story_5046_50461202_144_dialog_content = "Você deve sempre fazer uma pausa antes de encontrar seu próximo objetivo.",
  ui_story_5046_50461202_145_dialog_content = "Afinal, você já se saiu tão bem em alcançar seu último objetivo.",
  ui_story_5046_50461202_146_dialog_content = "Meu próximo objetivo?",
  ui_story_5046_50461202_147_dialog_content = "Não sei qual será meu próximo objetivo.",
  ui_story_5046_50461202_148_dialog_content = "Você vai encontrá-lo.",
  ui_story_5046_50461202_149_dialog_content = "Sua vida apenas começou!",
  ui_story_5046_50461202_150_dialog_content = "Como eu disse antes, muitas coisas novas e emocionantes estão esperando por você para descobrir neste mundo!",
  ui_story_5046_50461202_151_dialog_content = "Por enquanto, apenas aproveite seu tempo de lazer enquanto pode!",
  ui_story_5046_50461202_152_dialog_content = "Uhum.",
  ui_story_5046_50461202_153_dialog_content = "Obrigada, PlayerName.",
  ui_story_5046_50461202_154_dialog_content = "Estou mais preocupado se você pode ter outra dor de cabeça em breve...",
  ui_story_5046_50461202_155_dialog_content = "Eu estou imaginando o que aquele cachorro grande que se parece com você vai dizer a você a seguir...",
  ui_story_5046_50461202_156_dialog_content = "Eu não me importo.",
  ui_story_5046_50461202_157_dialog_content = "Já chegamos a um acordo.",
  ui_story_5046_50461202_158_dialog_content = "Agora, nós somos um.",
  ui_story_5046_50461202_159_dialog_content = "Nossa!",
  ui_story_5046_50461202_160_dialog_content = "Você se parece com aquele cachorro grande!",
  ui_story_5046_50461202_161_dialog_content = "Uhum.",
  ui_story_5046_50461202_162_dialog_content = "Não tenha medo.",
  ui_story_5046_50461202_163_dialog_content = "Agora posso aproveitar totalmente seu poder...",
  ui_story_5046_50461202_164_dialog_content = "É o poder do fogo.",
  ui_story_5046_50461202_165_dialog_content = "Cão grande!",
  ui_story_5046_50461202_166_dialog_content = "Você é...",
  ui_story_5046_50461202_167_dialog_content = "Você é... a garotinha daquele dia.",
  ui_story_5046_50461202_168_dialog_content = "Fiz um anel de flores para o cachorrinho que nos salvou!",
  ui_story_5046_50461202_169_dialog_content = "Você sabe onde está o cachorrinho?",
  ui_story_5046_50461202_170_dialog_content = "Ela...",
  ui_story_5046_50461202_171_dialog_content = "Ela está bem aqui.",
  ui_story_5046_50461202_172_dialog_content = "Uau!",
  ui_story_5046_50461202_173_dialog_content = "Eu realmente pareço tão assustador?",
  ui_story_5046_50461202_174_dialog_content = "Que cachorrinho enorme!",
  ui_story_5046_50461202_175_dialog_content = "Ela é linda!",
  ui_story_5046_50461202_176_dialog_content = "...",
  ui_story_5046_50461202_177_dialog_content = "Você é o cachorrão que me salvou outro dia?",
  ui_story_5046_50461202_178_dialog_content = "Uhum.",
  ui_story_5046_50461202_179_dialog_content = "Oh! Eu sei!",
  ui_story_5046_50461202_180_dialog_content = "O cachorrão tem trabalhado tanto para salvar as pessoas por toda a cidade, ficando cada vez mais forte e cada vez mais incrível!",
  ui_story_5046_50461202_181_dialog_content = "É por isso que o cãozinho se tornou um cãozinho super enorme!",
  ui_story_5046_50461202_182_dialog_content = "Ahahahaha...",
  ui_story_5046_50461202_183_dialog_content = "Cachorrinho! Cão grande herói!",
  ui_story_5046_50461202_184_dialog_content = "Hya... Hya...",
  ui_story_5046_50461202_185_dialog_content = "Waah... não consigo alcançar...",
  ui_story_5046_50461202_186_dialog_content = "Você está tentando colocar esta guirlanda nela?",
  ui_story_5046_50461202_187_dialog_content = "Sim!",
  ui_story_5046_50461202_188_dialog_content = "Deixe-me agachar um pouco.",
  ui_story_5046_50461202_189_dialog_content = "Perfeito!",
  ui_story_5046_50461202_190_dialog_content = "Obrigado por me salvar!",
  ui_story_5046_50461202_191_dialog_content = "Saí secretamente para colher essas flores sem avisar o zelador...",
  ui_story_5046_50461202_192_dialog_content = "Você não deveria se esgueirar assim!",
  ui_story_5046_50461202_193_dialog_content = "Mas... Mas eu pensei que o cachorrão me salvou...",
  ui_story_5046_50461202_194_dialog_content = "Então eu deveria dar um presente para o cachorrinho!",
  ui_story_5046_50461202_195_dialog_content = "Contanto que você esteja bem.",
